def getwalletnfts(chain, address, format=None, limit=None, cursor=None, normalizeMetadata=None, mediaItems=None, excludeSpam=None, tokenAddresses=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getwalletnfts"
    status = "ok"

    def _log_and_return(payload):
        nonlocal status
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": endpoint,
                "status": status,
                "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass
        return payload

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            if obj.get("endpoint") != endpoint:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(off):
        obj = {"v": 1, "endpoint": endpoint, "offset": off}
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _is_hex_addr(s):
        if not isinstance(s, str):
            return False
        s2 = s.lower()
        if not (s2.startswith("0x") and len(s2) == 42):
            return False
        hexd = "0123456789abcdef"
        return all(c in hexd for c in s2[2:])

    def _normalize_wallet_addr(s):
        if not isinstance(s, str):
            return None
        s = s.strip()
        if s.lower().startswith("0x"):
            return s.lower()
        return s

    def _format_token_id(token_id, fmt):
        if token_id is None:
            return None
        if not isinstance(token_id, str):
            token_id = str(token_id)
        fmt = fmt or "decimal"
        if fmt not in ("decimal", "hex"):
            return None
        if fmt == "decimal":
            return token_id
        # hex
        try:
            if token_id.startswith("0x") or token_id.startswith("0X"):
                n = int(token_id, 16)
            else:
                n = int(token_id, 10)
            return hex(n)
        except Exception:
            return None

    def _should_exclude_spam(asset_row):
        if not excludeSpam:
            return False
        if not isinstance(asset_row, dict):
            return False
        ss = asset_row.get("spam_status")
        return ss in ("spam", "suspected_spam")

    # Validate required
    if not isinstance(chain, str) or not chain.strip():
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "chain must be a non-empty string"))
    if not isinstance(address, str) or not address.strip():
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "address must be a non-empty string"))

    if format is None:
        format = "decimal"
    if format not in ("decimal", "hex"):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "format must be one of: decimal, hex"))

    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "limit must be an integer"))
    if limit < 1 or limit > 100:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "limit out of range (1..100)"))

    if normalizeMetadata is None:
        normalizeMetadata = False
    if mediaItems is None:
        mediaItems = False
    if excludeSpam is None:
        excludeSpam = False
    if not isinstance(normalizeMetadata, bool) or not isinstance(mediaItems, bool) or not isinstance(excludeSpam, bool):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "normalizeMetadata, mediaItems, excludeSpam must be boolean"))

    if tokenAddresses is not None:
        if not isinstance(tokenAddresses, list) or any(not isinstance(x, str) or not x.strip() for x in tokenAddresses):
            status = "error"
            return _log_and_return(_err("VALIDATION_ERROR", "tokenAddresses must be an array of non-empty strings"))

    chains = _load("chains.json")
    if not isinstance(chains, list):
        chains = []
    chain_row = next((c for c in chains if isinstance(c, dict) and c.get("chain_key") == chain), None)
    if not chain_row:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "Unsupported chain"))
    chain_id = chain_row.get("id")

    wallet_addr = _normalize_wallet_addr(address)
    # Basic address validation by chain type
    if chain_row.get("chain_type") == "evm":
        if not _is_hex_addr(wallet_addr):
            status = "error"
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid EVM address"))
    else:
        # allow non-empty for non-evm in this minimal schema
        if not wallet_addr:
            status = "error"
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid address"))

    offset = _parse_cursor(cursor)
    if offset is None:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid cursor"))

    addresses = _load("addresses.json")
    if not isinstance(addresses, list):
        addresses = []

    # create-on-read wallet address row allowed
    wallet_row = next((a for a in addresses if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("address") == wallet_addr), None)
    now = datetime.datetime.utcnow().isoformat() + "Z"
    if not wallet_row:
        new_id = f"addr_{int(time.time()*1000)}_{len(addresses)+1}"
        wallet_row = {
            "id": new_id,
            "chain_id": chain_id,
            "address": wallet_addr,
            "address_kind": "wallet",
            "ens_name": None,
            "ens_resolved_address": None,
            "first_seen_at": None,
            "last_seen_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        addresses.append(wallet_row)
        _save("addresses.json", addresses)
    else:
        if wallet_row.get("address_kind") != "wallet":
            # treat as wallet for endpoints; do not mutate kind
            pass

    wallet_id = wallet_row.get("id")

    # TokenAddresses filter: map to contract address_ids
    contract_id_filter = None
    if tokenAddresses is not None:
        contract_id_filter = set()
        for ta in tokenAddresses:
            ta_norm = _normalize_wallet_addr(ta)
            if chain_row.get("chain_type") == "evm":
                if not _is_hex_addr(ta_norm):
                    status = "error"
                    return _log_and_return(_err("VALIDATION_ERROR", f"Invalid contract address in tokenAddresses: {ta}"))
            addr_row = next((a for a in addresses if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("address") == ta_norm), None)
            if addr_row:
                contract_id_filter.add(addr_row.get("id"))
            # If not present, filter means nothing will match (no create-on-read for contracts here)
        # If provided and none resolved, result empty
        if len(contract_id_filter) == 0:
            result = {"result": [], "total": 0, "page_size": limit, "cursor": None, "has_more": False}
            return _log_and_return(result)

    events = _load("events.json")
    if not isinstance(events, list):
        events = []

    # Ownership inference: latest confirmed nft_transfer per (contract_address_id, token_id)
    # where wallet appears as to_address_id in last transfer and not burned.
    # Determine burn/zero address row for chain (create if missing as per rule).
    zero_addr = "0x0000000000000000000000000000000000000000" if chain_row.get("chain_type") == "evm" else "11111111111111111111111111111111"
    burn_row = next((a for a in addresses if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("address") == zero_addr), None)
    if not burn_row:
        burn_id = f"addr_{int(time.time()*1000)}_{len(addresses)+1}"
        burn_row = {
            "id": burn_id,
            "chain_id": chain_id,
            "address": zero_addr,
            "address_kind": "other",
            "ens_name": None,
            "ens_resolved_address": None,
            "first_seen_at": None,
            "last_seen_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        addresses.append(burn_row)
        _save("addresses.json", addresses)
    burn_id = burn_row.get("id")

    # Build latest transfer map
    latest = {}
    for ev in events:
        if not isinstance(ev, dict):
            continue
        if ev.get("chain_id") != chain_id:
            continue
        if ev.get("status") != "confirmed":
            continue
        if ev.get("event_type") != "nft_transfer":
            continue
        caid = ev.get("contract_address_id")
        tid = ev.get("token_id")
        if caid is None or tid is None:
            continue
        if contract_id_filter is not None and caid not in contract_id_filter:
            continue
        key = (caid, str(tid))
        bn = ev.get("block_number")
        ts = ev.get("block_timestamp")
        li = ev.get("log_index")
        # determine ordering tuple
        try:
            bn_i = int(bn) if bn is not None else -1
        except Exception:
            bn_i = -1
        try:
            li_i = int(li) if li is not None else -1
        except Exception:
            li_i = -1
        ord_t = (bn_i, ts or "", li_i, ev.get("id") or "")
        prev = latest.get(key)
        if prev is None or ord_t > prev[0]:
            latest[key] = (ord_t, ev)

    # Collect items owned by wallet
    owned_keys = []
    for key, (_ord, ev) in latest.items():
        to_id = ev.get("to_address_id")
        if to_id == wallet_id and to_id != burn_id:
            owned_keys.append(key)

    # Resolve asset rows for nft_item when present, else return minimal using transfer data and collection metadata if exists
    assets = _load("assets.json")
    if not isinstance(assets, list):
        assets = []
    # Build index for collections and items
    items_by_key = {}
    collections_by_contract = {}
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("chain_id") != chain_id:
            continue
        at = a.get("asset_type")
        if at == "nft_item":
            caid = a.get("contract_address_id")
            tid = a.get("token_id")
            if caid is None or tid is None:
                continue
            items_by_key[(caid, str(tid))] = a
        elif at == "nft_collection":
            caid = a.get("contract_address_id")
            if caid is not None:
                collections_by_contract[caid] = a

    # Sort deterministically: by contract address then token_id (as int when possible)
    def _tok_sort(k):
        caid, tid = k
        contract_addr = next((ad.get("address") for ad in addresses if isinstance(ad, dict) and ad.get("id") == caid), "")
        try:
            tid_i = int(tid, 10) if not (isinstance(tid, str) and tid.lower().startswith("0x")) else int(tid, 16)
        except Exception:
            tid_i = None
        return (contract_addr, tid_i if tid_i is not None else 10**50, tid)

    owned_keys.sort(key=_tok_sort)

    total = len(owned_keys)
    page_keys = owned_keys[offset:offset + limit]
    has_more = offset + limit < total
    next_cursor = _make_cursor(offset + limit) if has_more else None

    def _normalized_metadata(meta):
        if not normalizeMetadata:
            return None
        if not isinstance(meta, dict):
            return None
        nm = {}
        for k in ("name", "description", "image", "image_url", "animation_url", "external_url", "attributes"):
            if k in meta:
                nm[k] = meta.get(k)
        # common normalization: image -> image_url
        if "image_url" not in nm and "image" in nm:
            nm["image_url"] = nm.get("image")
        return nm if nm else None

    def _media_items(meta):
        if not mediaItems:
            return None
        if not isinstance(meta, dict):
            return None
        out = []
        img = meta.get("image_url") or meta.get("image")
        anim = meta.get("animation_url")
        if isinstance(img, str) and img:
            out.append({"type": "image", "url": img})
        if isinstance(anim, str) and anim:
            out.append({"type": "animation", "url": anim})
        return out if out else None

    result_rows = []
    for (caid, tid) in page_keys:
        item = items_by_key.get((caid, str(tid)))
        if item and _should_exclude_spam(item):
            continue
        coll = collections_by_contract.get(caid)
        if coll and _should_exclude_spam(coll):
            continue

        contract_addr = next((ad.get("address") for ad in addresses if isinstance(ad, dict) and ad.get("id") == caid), None)
        token_id_fmt = _format_token_id(str(tid), format)
        if token_id_fmt is None:
            token_id_fmt = str(tid)

        meta = item.get("metadata") if isinstance(item, dict) else None
        if not isinstance(meta, dict) and isinstance(coll, dict):
            # some collections store item-like metadata in collection metadata; do not fabricate token fields
            meta = meta

        row = {
            "token_address": contract_addr,
            "token_id": token_id_fmt,
            "name": (item.get("name") if isinstance(item, dict) else None),
            "symbol": (item.get("symbol") if isinstance(item, dict) else (coll.get("symbol") if isinstance(coll, dict) else None)),
            "collection_name": (coll.get("name") if isinstance(coll, dict) else None),
            "amount": "1",
            "contract_type": "ERC721",
            "metadata": meta if isinstance(meta, (dict, list, str)) else meta,
            "normalized_metadata": _normalized_metadata(meta),
            "media_items": _media_items(meta),
            "spam_status": (item.get("spam_status") if isinstance(item, dict) else (coll.get("spam_status") if isinstance(coll, dict) else "unknown")),
            "block_number_minted": None,
            "last_token_uri_sync": None,
            "last_metadata_sync": (item.get("updated_at") if isinstance(item, dict) else None),
        }
        result_rows.append(row)

    # If spam filtering removed some within page, Moralis would still page; we keep cursor semantics stable by slicing before spam removal.
    payload = {
        "result": result_rows,
        "total": total,
        "page_size": limit,
        "cursor": next_cursor,
        "has_more": has_more
    }
    return _log_and_return(payload)

def getmultiplenfts(chain, tokens, normalizeMetadata=None, mediaItems=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getmultiplenfts"
    status = "ok"

    def _log_and_return(payload):
        nonlocal status
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": endpoint,
                "status": status,
                "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass
        return payload

    def _is_hex_addr(s):
        if not isinstance(s, str):
            return False
        s2 = s.lower()
        if not (s2.startswith("0x") and len(s2) == 42):
            return False
        hexd = "0123456789abcdef"
        return all(c in hexd for c in s2[2:])

    def _normalized_metadata(meta):
        if not normalizeMetadata:
            return None
        if not isinstance(meta, dict):
            return None
        nm = {}
        for k in ("name", "description", "image", "image_url", "animation_url", "external_url", "attributes"):
            if k in meta:
                nm[k] = meta.get(k)
        if "image_url" not in nm and "image" in nm:
            nm["image_url"] = nm.get("image")
        return nm if nm else None

    def _media_items(meta):
        if not mediaItems:
            return None
        if not isinstance(meta, dict):
            return None
        out = []
        img = meta.get("image_url") or meta.get("image")
        anim = meta.get("animation_url")
        if isinstance(img, str) and img:
            out.append({"type": "image", "url": img})
        if isinstance(anim, str) and anim:
            out.append({"type": "animation", "url": anim})
        return out if out else None

    # Validate
    if not isinstance(chain, str) or not chain.strip():
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "chain must be a non-empty string"))
    if not isinstance(tokens, list):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "tokens must be an array"))
    if len(tokens) < 1:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "tokens must not be empty"))
    if len(tokens) > 25:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "tokens exceeds max of 25"))

    if normalizeMetadata is None:
        normalizeMetadata = False
    if mediaItems is None:
        mediaItems = False
    if not isinstance(normalizeMetadata, bool) or not isinstance(mediaItems, bool):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "normalizeMetadata and mediaItems must be boolean"))

    chains = _load("chains.json")
    if not isinstance(chains, list):
        chains = []
    chain_row = next((c for c in chains if isinstance(c, dict) and c.get("chain_key") == chain), None)
    if not chain_row:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "Unsupported chain"))
    chain_id = chain_row.get("id")
    is_evm = chain_row.get("chain_type") == "evm"

    addresses = _load("addresses.json")
    if not isinstance(addresses, list):
        addresses = []
    assets = _load("assets.json")
    if not isinstance(assets, list):
        assets = []

    # Index addresses by (chain_id, address)
    addr_index = {}
    for a in addresses:
        if isinstance(a, dict) and a.get("chain_id") == chain_id and isinstance(a.get("address"), str):
            addr_index[a["address"]] = a

    # Index NFT items
    items_index = {}
    col_index = {}
    for a in assets:
        if not isinstance(a, dict) or a.get("chain_id") != chain_id:
            continue
        if a.get("asset_type") == "nft_item":
            caid = a.get("contract_address_id")
            tid = a.get("token_id")
            if caid is not None and tid is not None:
                items_index[(caid, str(tid))] = a
        elif a.get("asset_type") == "nft_collection":
            caid = a.get("contract_address_id")
            if caid is not None:
                col_index[caid] = a

    results = []
    for t in tokens:
        if not isinstance(t, dict):
            status = "error"
            return _log_and_return(_err("VALIDATION_ERROR", "Each token entry must be an object"))
        if "token_address" not in t or "token_id" not in t:
            status = "error"
            return _log_and_return(_err("VALIDATION_ERROR", "Each token entry must include token_address and token_id"))
        ta = t.get("token_address")
        tid = t.get("token_id")
        if not isinstance(ta, str) or not ta.strip():
            status = "error"
            return _log_and_return(_err("VALIDATION_ERROR", "token_address must be a non-empty string"))
        if not isinstance(tid, str) or not tid.strip():
            status = "error"
            return _log_and_return(_err("VALIDATION_ERROR", "token_id must be a non-empty string"))

        ta_norm = ta.strip().lower() if is_evm else ta.strip()
        if is_evm and not _is_hex_addr(ta_norm):
            status = "error"
            return _log_and_return(_err("VALIDATION_ERROR", f"Invalid EVM contract address: {ta}"))

        addr_row = addr_index.get(ta_norm)
        contract_address_id = addr_row.get("id") if addr_row else None

        item = items_index.get((contract_address_id, str(tid))) if contract_address_id else None
        coll = col_index.get(contract_address_id) if contract_address_id else None

        meta = item.get("metadata") if isinstance(item, dict) else None
        results.append({
            "token_address": ta_norm,
            "token_id": str(tid),
            "name": (item.get("name") if isinstance(item, dict) else None),
            "symbol": (item.get("symbol") if isinstance(item, dict) else (coll.get("symbol") if isinstance(coll, dict) else None)),
            "collection_name": (coll.get("name") if isinstance(coll, dict) else None),
            "metadata": meta,
            "normalized_metadata": _normalized_metadata(meta),
            "media_items": _media_items(meta),
            "floor_price_native": (coll.get("floor_price_native") if isinstance(coll, dict) else None),
            "floor_price_usd": (coll.get("floor_price_usd") if isinstance(coll, dict) else None),
            "floor_price_refreshed_at": (coll.get("floor_price_refreshed_at") if isinstance(coll, dict) else None),
            "spam_status": (item.get("spam_status") if isinstance(item, dict) else (coll.get("spam_status") if isinstance(coll, dict) else "unknown")),
        })

    return _log_and_return({"result": results})

def getwalletnftcollections(chain, address, limit=None, cursor=None, excludeSpam=None, normalizeMetadata=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getwalletnftcollections"
    status = "ok"

    def _log_and_return(payload):
        nonlocal status
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": endpoint,
                "status": status,
                "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass
        return payload

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            if obj.get("endpoint") != endpoint:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(off):
        obj = {"v": 1, "endpoint": endpoint, "offset": off}
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _is_hex_addr(s):
        if not isinstance(s, str):
            return False
        s2 = s.lower()
        if not (s2.startswith("0x") and len(s2) == 42):
            return False
        hexd = "0123456789abcdef"
        return all(c in hexd for c in s2[2:])

    def _normalize_addr(s, is_evm):
        if not isinstance(s, str):
            return None
        s = s.strip()
        return s.lower() if is_evm and s.lower().startswith("0x") else s

    def _normalized_metadata(meta):
        if not normalizeMetadata:
            return None
        if not isinstance(meta, dict):
            return None
        nm = {}
        for k in ("name", "description", "image", "image_url", "external_url"):
            if k in meta:
                nm[k] = meta.get(k)
        if "image_url" not in nm and "image" in nm:
            nm["image_url"] = nm.get("image")
        return nm if nm else None

    def _should_exclude_spam(asset_row):
        if not excludeSpam:
            return False
        if not isinstance(asset_row, dict):
            return False
        return asset_row.get("spam_status") in ("spam", "suspected_spam")

    # Validate
    if not isinstance(chain, str) or not chain.strip():
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "chain must be a non-empty string"))
    if not isinstance(address, str) or not address.strip():
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "address must be a non-empty string"))

    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "limit must be an integer"))
    if limit < 1 or limit > 100:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "limit out of range (1..100)"))

    if excludeSpam is None:
        excludeSpam = False
    if normalizeMetadata is None:
        normalizeMetadata = False
    if not isinstance(excludeSpam, bool) or not isinstance(normalizeMetadata, bool):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "excludeSpam and normalizeMetadata must be boolean"))

    chains = _load("chains.json")
    if not isinstance(chains, list):
        chains = []
    chain_row = next((c for c in chains if isinstance(c, dict) and c.get("chain_key") == chain), None)
    if not chain_row:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "Unsupported chain"))
    chain_id = chain_row.get("id")
    is_evm = chain_row.get("chain_type") == "evm"

    addr_norm = _normalize_addr(address, is_evm)
    if is_evm and not _is_hex_addr(addr_norm):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid EVM address"))

    offset = _parse_cursor(cursor)
    if offset is None:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid cursor"))

    addresses = _load("addresses.json")
    if not isinstance(addresses, list):
        addresses = []

    # create-on-read wallet address row allowed
    wallet_row = next((a for a in addresses if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("address") == addr_norm), None)
    now = datetime.datetime.utcnow().isoformat() + "Z"
    if not wallet_row:
        wallet_row = {
            "id": f"addr_{int(time.time()*1000)}_{len(addresses)+1}",
            "chain_id": chain_id,
            "address": addr_norm,
            "address_kind": "wallet",
            "ens_name": None,
            "ens_resolved_address": None,
            "first_seen_at": None,
            "last_seen_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        addresses.append(wallet_row)
        _save("addresses.json", addresses)
    wallet_id = wallet_row.get("id")

    events = _load("events.json")
    if not isinstance(events, list):
        events = []

    # Burn/zero address row required
    zero_addr = "0x0000000000000000000000000000000000000000" if is_evm else "11111111111111111111111111111111"
    burn_row = next((a for a in addresses if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("address") == zero_addr), None)
    if not burn_row:
        burn_row = {
            "id": f"addr_{int(time.time()*1000)}_{len(addresses)+1}",
            "chain_id": chain_id,
            "address": zero_addr,
            "address_kind": "other",
            "ens_name": None,
            "ens_resolved_address": None,
            "first_seen_at": None,
            "last_seen_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        addresses.append(burn_row)
        _save("addresses.json", addresses)
    burn_id = burn_row.get("id")

    # latest owner per (contract, token_id)
    latest = {}
    for ev in events:
        if not isinstance(ev, dict):
            continue
        if ev.get("chain_id") != chain_id or ev.get("status") != "confirmed" or ev.get("event_type") != "nft_transfer":
            continue
        caid = ev.get("contract_address_id")
        tid = ev.get("token_id")
        if caid is None or tid is None:
            continue
        key = (caid, str(tid))
        try:
            bn = int(ev.get("block_number")) if ev.get("block_number") is not None else -1
        except Exception:
            bn = -1
        ts = ev.get("block_timestamp") or ""
        try:
            li = int(ev.get("log_index")) if ev.get("log_index") is not None else -1
        except Exception:
            li = -1
        ord_t = (bn, ts, li, ev.get("id") or "")
        prev = latest.get(key)
        if prev is None or ord_t > prev[0]:
            latest[key] = (ord_t, ev)

    # count by contract_address_id where last owner == wallet and not burned
    counts = {}
    for (caid, _tid), (_o, ev) in latest.items():
        to_id = ev.get("to_address_id")
        if to_id == wallet_id and to_id != burn_id:
            counts[caid] = counts.get(caid, 0) + 1

    # fetch collections assets
    assets = _load("assets.json")
    if not isinstance(assets, list):
        assets = []
    collections = []
    for caid, cnt in counts.items():
        coll = next((a for a in assets if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("asset_type") == "nft_collection" and a.get("contract_address_id") == caid), None)
        if coll and _should_exclude_spam(coll):
            continue
        contract_addr = next((ad.get("address") for ad in addresses if isinstance(ad, dict) and ad.get("id") == caid), None)
        meta = coll.get("metadata") if isinstance(coll, dict) else None
        collections.append({
            "token_address": contract_addr,
            "name": (coll.get("name") if isinstance(coll, dict) else None),
            "symbol": (coll.get("symbol") if isinstance(coll, dict) else None),
            "metadata": meta,
            "normalized_metadata": _normalized_metadata(meta),
            "floor_price_native": (coll.get("floor_price_native") if isinstance(coll, dict) else None),
            "floor_price_usd": (coll.get("floor_price_usd") if isinstance(coll, dict) else None),
            "floor_price_refreshed_at": (coll.get("floor_price_refreshed_at") if isinstance(coll, dict) else None),
            "owned_tokens": cnt,
            "spam_status": (coll.get("spam_status") if isinstance(coll, dict) else "unknown"),
        })

    # deterministic sort by token_address
    collections.sort(key=lambda r: (r.get("token_address") or ""))

    total = len(collections)
    page = collections[offset:offset + limit]
    has_more = offset + limit < total
    next_cursor = _make_cursor(offset + limit) if has_more else None

    return _log_and_return({
        "result": page,
        "total": total,
        "page_size": limit,
        "cursor": next_cursor,
        "has_more": has_more
    })

def getcontractnfts(chain, address, limit=None, cursor=None, format=None, normalizeMetadata=None, mediaItems=None, excludeSpam=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getcontractnfts"
    status = "ok"

    def _log_and_return(payload):
        nonlocal status
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": endpoint,
                "status": status,
                "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass
        return payload

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            if obj.get("endpoint") != endpoint:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(off):
        obj = {"v": 1, "endpoint": endpoint, "offset": off}
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _is_hex_addr(s):
        if not isinstance(s, str):
            return False
        s2 = s.lower()
        if not (s2.startswith("0x") and len(s2) == 42):
            return False
        hexd = "0123456789abcdef"
        return all(c in hexd for c in s2[2:])

    def _format_token_id(token_id, fmt):
        if token_id is None:
            return None
        if not isinstance(token_id, str):
            token_id = str(token_id)
        fmt = fmt or "decimal"
        if fmt not in ("decimal", "hex"):
            return None
        if fmt == "decimal":
            return token_id
        try:
            if token_id.startswith("0x") or token_id.startswith("0X"):
                n = int(token_id, 16)
            else:
                n = int(token_id, 10)
            return hex(n)
        except Exception:
            return None

    def _normalized_metadata(meta):
        if not normalizeMetadata:
            return None
        if not isinstance(meta, dict):
            return None
        nm = {}
        for k in ("name", "description", "image", "image_url", "animation_url", "external_url", "attributes"):
            if k in meta:
                nm[k] = meta.get(k)
        if "image_url" not in nm and "image" in nm:
            nm["image_url"] = nm.get("image")
        return nm if nm else None

    def _media_items(meta):
        if not mediaItems:
            return None
        if not isinstance(meta, dict):
            return None
        out = []
        img = meta.get("image_url") or meta.get("image")
        anim = meta.get("animation_url")
        if isinstance(img, str) and img:
            out.append({"type": "image", "url": img})
        if isinstance(anim, str) and anim:
            out.append({"type": "animation", "url": anim})
        return out if out else None

    def _should_exclude_spam(asset_row):
        if not excludeSpam:
            return False
        if not isinstance(asset_row, dict):
            return False
        return asset_row.get("spam_status") in ("spam", "suspected_spam")

    # Validate
    if not isinstance(chain, str) or not chain.strip():
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "chain must be a non-empty string"))
    if not isinstance(address, str) or not address.strip():
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "address must be a non-empty string"))

    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "limit must be an integer"))
    if limit < 1 or limit > 100:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "limit out of range (1..100)"))

    if format is None:
        format = "decimal"
    if format not in ("decimal", "hex"):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "format must be one of: decimal, hex"))

    if normalizeMetadata is None:
        normalizeMetadata = False
    if mediaItems is None:
        mediaItems = False
    if excludeSpam is None:
        excludeSpam = False
    if not isinstance(normalizeMetadata, bool) or not isinstance(mediaItems, bool) or not isinstance(excludeSpam, bool):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "normalizeMetadata, mediaItems, excludeSpam must be boolean"))

    chains = _load("chains.json")
    if not isinstance(chains, list):
        chains = []
    chain_row = next((c for c in chains if isinstance(c, dict) and c.get("chain_key") == chain), None)
    if not chain_row:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "Unsupported chain"))
    chain_id = chain_row.get("id")
    is_evm = chain_row.get("chain_type") == "evm"

    addr_norm = address.strip().lower() if is_evm else address.strip()
    if is_evm and not _is_hex_addr(addr_norm):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid EVM contract address"))

    offset = _parse_cursor(cursor)
    if offset is None:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid cursor"))

    addresses = _load("addresses.json")
    if not isinstance(addresses, list):
        addresses = []

    contract_row = next((a for a in addresses if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("address") == addr_norm), None)
    contract_id = contract_row.get("id") if contract_row else None

    assets = _load("assets.json")
    if not isinstance(assets, list):
        assets = []

    # Collect nft_item assets for this contract
    items = []
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("chain_id") != chain_id:
            continue
        if a.get("asset_type") != "nft_item":
            continue
        if contract_id is None or a.get("contract_address_id") != contract_id:
            continue
        if _should_exclude_spam(a):
            continue
        items.append(a)

    # deterministic sort by token_id numeric then string
    def _tid_sort(a):
        tid = a.get("token_id")
        s = str(tid) if tid is not None else ""
        try:
            n = int(s, 16) if s.lower().startswith("0x") else int(s, 10)
        except Exception:
            n = None
        return (n if n is not None else 10**50, s)

    items.sort(key=_tid_sort)

    total = len(items)
    page_items = items[offset:offset + limit]
    has_more = offset + limit < total
    next_cursor = _make_cursor(offset + limit) if has_more else None

    # Collection-level info
    coll = None
    if contract_id is not None:
        coll = next((a for a in assets if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("asset_type") == "nft_collection" and a.get("contract_address_id") == contract_id), None)
    if coll and _should_exclude_spam(coll):
        coll = None

    result = []
    for it in page_items:
        meta = it.get("metadata")
        tid_fmt = _format_token_id(it.get("token_id"), format)
        if tid_fmt is None:
            tid_fmt = str(it.get("token_id")) if it.get("token_id") is not None else None
        result.append({
            "token_address": addr_norm,
            "token_id": tid_fmt,
            "name": it.get("name"),
            "symbol": it.get("symbol") or (coll.get("symbol") if isinstance(coll, dict) else None),
            "collection_name": (coll.get("name") if isinstance(coll, dict) else None),
            "metadata": meta,
            "normalized_metadata": _normalized_metadata(meta),
            "media_items": _media_items(meta),
            "floor_price_native": (coll.get("floor_price_native") if isinstance(coll, dict) else None),
            "floor_price_usd": (coll.get("floor_price_usd") if isinstance(coll, dict) else None),
            "floor_price_refreshed_at": (coll.get("floor_price_refreshed_at") if isinstance(coll, dict) else None),
            "spam_status": it.get("spam_status") or (coll.get("spam_status") if isinstance(coll, dict) else "unknown"),
            "last_metadata_sync": it.get("updated_at"),
        })

    return _log_and_return({
        "result": result,
        "total": total,
        "page_size": limit,
        "cursor": next_cursor,
        "has_more": has_more
    })

def getnftowners(chain, address, tokenId=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    # Basic validation
    if not isinstance(chain, str) or not chain.strip():
        return _err("VALIDATION_ERROR", "Invalid `chain`.")
    if not isinstance(address, str) or not address.strip():
        return _err("VALIDATION_ERROR", "Invalid `address`.")
    if tokenId is not None and (not isinstance(tokenId, str) or tokenId.strip() == ""):
        return _err("VALIDATION_ERROR", "Invalid `tokenId`.")
    if tokenId is not None:
        # tokenId must be a non-negative integer string in this minimal server
        if not tokenId.isdigit():
            return _err("VALIDATION_ERROR", "Invalid `tokenId` format; expected a non-negative integer string.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "Invalid `limit`; must be between 1 and 100.")
    if cursor is not None and (not isinstance(cursor, str) or cursor.strip() == ""):
        return _err("VALIDATION_ERROR", "Invalid `cursor`.")

    # Resolve chain
    chains = _load("chains.json")
    chain_row = None
    for c in chains:
        if isinstance(c, dict) and c.get("chain_key") == chain:
            chain_row = c
            break
    if not chain_row:
        return _err("VALIDATION_ERROR", "Unsupported `chain`.")
    chain_id = chain_row.get("id")

    # Normalize contract address: EVM lowercased
    addr_in = address.strip()
    if chain_row.get("chain_type") == "evm":
        if not (addr_in.startswith("0x") and len(addr_in) == 42):
            return _err("VALIDATION_ERROR", "Invalid contract `address` for EVM chain.")
        hexd = addr_in[2:]
        try:
            int(hexd, 16)
        except ValueError:
            return _err("VALIDATION_ERROR", "Invalid contract `address` for EVM chain.")
        contract_addr_norm = "0x" + hexd.lower()
    else:
        # For non-EVM, accept non-empty string; no base58 validation in minimal schema
        contract_addr_norm = addr_in

    # Cursor decode: base64url(JSON: {"o": int})
    offset = 0
    if cursor is not None:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "o" not in obj:
                return _err("VALIDATION_ERROR", "Invalid `cursor`.")
            offset = obj["o"]
            if not isinstance(offset, int) or offset < 0:
                return _err("VALIDATION_ERROR", "Invalid `cursor`.")
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            return _err("VALIDATION_ERROR", "Invalid `cursor`.")

    addresses = _load("addresses.json")
    assets = _load("assets.json")
    events = _load("events.json")

    # Find contract address row (must exist to be indexed)
    contract_addr_row = None
    for a in addresses:
        if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("address") == contract_addr_norm:
            contract_addr_row = a
            break
    if not contract_addr_row:
        # Not indexed contract
        return _err("NOT_FOUND", "NFT contract not indexed.")

    contract_address_id = contract_addr_row.get("id")

    # Determine relevant nft_transfer events for this contract (+ tokenId if provided)
    # Only confirmed
    evs = []
    for e in events:
        if not isinstance(e, dict):
            continue
        if e.get("chain_id") != chain_id:
            continue
        if e.get("event_type") != "nft_transfer":
            continue
        if e.get("status") != "confirmed":
            continue
        if e.get("contract_address_id") != contract_address_id:
            continue
        # token id matching: event.token_id OR asset.token_id (via asset_id)
        if tokenId is not None:
            ok = False
            if e.get("token_id") == tokenId:
                ok = True
            elif e.get("asset_id"):
                aid = e.get("asset_id")
                for asr in assets:
                    if isinstance(asr, dict) and asr.get("id") == aid and asr.get("chain_id") == chain_id:
                        if asr.get("asset_type") == "nft_item" and asr.get("token_id") == tokenId:
                            ok = True
                        break
            if not ok:
                continue
        evs.append(e)

    if not evs:
        # If contract indexed but no transfers for this token/contract, return empty set
        resp = {"result": [], "total": 0, "page_size": limit, "cursor": None, "has_more": False}
        # no request-log collection exists; nothing to persist besides data mutations (none here)
        return resp

    # Find latest transfer per token_id within this contract
    # We use (block_number, log_index, updated_at/created_at) ordering
    def _ts(d):
        v = d.get("block_timestamp")
        if isinstance(v, str):
            try:
                return datetime.datetime.fromisoformat(v.replace("Z", "+00:00")).timestamp()
            except ValueError:
                return 0.0
        return 0.0

    latest_by_token = {}  # token_id -> event dict
    for e in evs:
        # resolve token_id
        tid = e.get("token_id")
        if tid is None and e.get("asset_id"):
            aid = e.get("asset_id")
            for asr in assets:
                if isinstance(asr, dict) and asr.get("id") == aid and asr.get("asset_type") == "nft_item":
                    if asr.get("chain_id") == chain_id and asr.get("contract_address_id") == contract_address_id:
                        tid = asr.get("token_id")
                    break
        if tid is None:
            continue
        cur = latest_by_token.get(tid)
        if cur is None:
            latest_by_token[tid] = e
            continue
        # compare
        bn1, bn2 = cur.get("block_number", -1), e.get("block_number", -1)
        li1, li2 = cur.get("log_index", -1), e.get("log_index", -1)
        if not isinstance(li1, int): li1 = -1
        if not isinstance(li2, int): li2 = -1
        if isinstance(bn2, int) and isinstance(bn1, int):
            if bn2 > bn1 or (bn2 == bn1 and li2 > li1) or (bn2 == bn1 and li2 == li1 and _ts(e) > _ts(cur)):
                latest_by_token[tid] = e

    if tokenId is not None:
        # ensure only the asked token
        if tokenId not in latest_by_token:
            resp = {"result": [], "total": 0, "page_size": limit, "cursor": None, "has_more": False}
            return resp

    # Ensure burn/zero address row exists per chain for burn detection (rule says it must be represented)
    zero_address_norm = None
    if chain_row.get("chain_type") == "evm":
        zero_address_norm = "0x" + ("0" * 40)
    else:
        zero_address_norm = "0"  # minimal placeholder for non-evm

    zero_addr_row = None
    for a in addresses:
        if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("address") == zero_address_norm:
            zero_addr_row = a
            break
    if not zero_addr_row:
        # Create-on-read allowed for addresses only (wallet endpoints explicitly; but rule here requires representation).
        # We'll create minimal "other" address row to satisfy burn detection.
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        def _new_id(prefix, rows):
            import secrets
            while True:
                nid = f"{prefix}_{secrets.token_hex(8)}"
                if all(not (isinstance(r, dict) and r.get("id") == nid) for r in rows):
                    return nid
        zero_addr_row = {
            "id": _new_id("addr", addresses),
            "chain_id": chain_id,
            "address": zero_address_norm,
            "address_kind": "other",
            "ens_name": None,
            "ens_resolved_address": None,
            "first_seen_at": None,
            "last_seen_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        addresses.append(zero_addr_row)
        _save("addresses.json", addresses)

    zero_id = zero_addr_row.get("id")

    # Aggregate owners: latest transfer determines ownership; burned if last to is zero/burn
    owners_map = {}  # to_address_id -> set(token_id)
    for tid, e in latest_by_token.items():
        to_id = e.get("to_address_id")
        if to_id is None:
            continue
        if to_id == zero_id:
            continue
        owners_map.setdefault(to_id, set()).add(tid)

    # Build owner rows
    # resolve address strings
    addr_by_id = {a.get("id"): a for a in addresses if isinstance(a, dict) and a.get("chain_id") == chain_id}
    owner_rows = []
    for owner_id, tids in owners_map.items():
        ar = addr_by_id.get(owner_id)
        owner_addr = ar.get("address") if isinstance(ar, dict) else None
        owner_rows.append({
            "owner_address": owner_addr,
            "owner_address_id": owner_id,
            "token_count": len(tids),
            "token_ids": None if tokenId is None else sorted(list(tids), key=lambda x: int(x) if isinstance(x, str) and x.isdigit() else x)
        })

    # Sort: token_count desc, then owner_address asc
    owner_rows.sort(key=lambda r: (-int(r.get("token_count") or 0), (r.get("owner_address") or "")))

    total = len(owner_rows)
    page = owner_rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"o": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    return {
        "result": page,
        "total": total,
        "page_size": limit,
        "cursor": next_cursor,
        "has_more": has_more
    }

def getnftcontracttransfers(chain, address, tokenId=None, fromDate=None, toDate=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(chain, str) or not chain.strip():
        return _err("VALIDATION_ERROR", "Invalid `chain`.")
    if not isinstance(address, str) or not address.strip():
        return _err("VALIDATION_ERROR", "Invalid `address`.")
    if tokenId is not None and (not isinstance(tokenId, str) or tokenId.strip() == ""):
        return _err("VALIDATION_ERROR", "Invalid `tokenId`.")
    if tokenId is not None and not tokenId.isdigit():
        return _err("VALIDATION_ERROR", "Invalid `tokenId` format; expected a non-negative integer string.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "Invalid `limit`; must be between 1 and 100.")
    if cursor is not None and (not isinstance(cursor, str) or cursor.strip() == ""):
        return _err("VALIDATION_ERROR", "Invalid `cursor`.")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError("bad")
        return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))

    try:
        fd = _parse_dt(fromDate)
        td = _parse_dt(toDate)
    except ValueError:
        return _err("VALIDATION_ERROR", "Malformed `fromDate`/`toDate`; expected ISO-8601 date-time.")

    if fd is not None and td is not None and fd > td:
        return _err("VALIDATION_ERROR", "`fromDate` must be <= `toDate`.")

    # Resolve chain
    chains = _load("chains.json")
    chain_row = None
    for c in chains:
        if isinstance(c, dict) and c.get("chain_key") == chain:
            chain_row = c
            break
    if not chain_row:
        return _err("VALIDATION_ERROR", "Unsupported `chain`.")
    chain_id = chain_row.get("id")

    # Normalize contract address
    addr_in = address.strip()
    if chain_row.get("chain_type") == "evm":
        if not (addr_in.startswith("0x") and len(addr_in) == 42):
            return _err("VALIDATION_ERROR", "Invalid contract `address` for EVM chain.")
        try:
            int(addr_in[2:], 16)
        except ValueError:
            return _err("VALIDATION_ERROR", "Invalid contract `address` for EVM chain.")
        contract_addr_norm = "0x" + addr_in[2:].lower()
    else:
        contract_addr_norm = addr_in

    # Cursor
    offset = 0
    if cursor is not None:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "o" not in obj:
                return _err("VALIDATION_ERROR", "Invalid `cursor`.")
            offset = obj["o"]
            if not isinstance(offset, int) or offset < 0:
                return _err("VALIDATION_ERROR", "Invalid `cursor`.")
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            return _err("VALIDATION_ERROR", "Invalid `cursor`.")

    addresses = _load("addresses.json")
    assets = _load("assets.json")
    events = _load("events.json")

    # Contract address row must exist (indexed)
    contract_addr_row = None
    for a in addresses:
        if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("address") == contract_addr_norm:
            contract_addr_row = a
            break
    if not contract_addr_row:
        return _err("NOT_FOUND", "NFT contract not indexed.")
    contract_address_id = contract_addr_row.get("id")

    asset_by_id = {a.get("id"): a for a in assets if isinstance(a, dict) and a.get("chain_id") == chain_id}

    def _event_tid(e):
        tid = e.get("token_id")
        if tid is None and e.get("asset_id"):
            asr = asset_by_id.get(e.get("asset_id"))
            if isinstance(asr, dict) and asr.get("asset_type") == "nft_item" and asr.get("contract_address_id") == contract_address_id:
                tid = asr.get("token_id")
        return tid

    def _event_dt(e):
        v = e.get("block_timestamp")
        if isinstance(v, str):
            try:
                return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
            except ValueError:
                return None
        return None

    # Filter transfers
    filtered = []
    for e in events:
        if not isinstance(e, dict):
            continue
        if e.get("chain_id") != chain_id:
            continue
        if e.get("event_type") != "nft_transfer":
            continue
        if e.get("status") != "confirmed":
            continue
        if e.get("contract_address_id") != contract_address_id:
            continue
        dt = _event_dt(e)
        if dt is None:
            continue
        if fd is not None and dt < fd:
            continue
        if td is not None and dt > td:
            continue
        if tokenId is not None:
            tid = _event_tid(e)
            if tid != tokenId:
                continue
        filtered.append(e)

    # Sort newest first: block_number desc, log_index desc, timestamp desc
    def _li(x):
        v = x.get("log_index")
        return v if isinstance(v, int) else -1

    filtered.sort(key=lambda e: (
        -(e.get("block_number") if isinstance(e.get("block_number"), int) else -1),
        -_li(e),
        e.get("block_timestamp") if isinstance(e.get("block_timestamp"), str) else ""
    ))

    total = len(filtered)
    page = filtered[offset: offset + limit]

    # Prepare output rows
    addr_by_id = {a.get("id"): a for a in addresses if isinstance(a, dict) and a.get("chain_id") == chain_id}
    out = []
    for e in page:
        tid = _event_tid(e)
        fa = addr_by_id.get(e.get("from_address_id")) if e.get("from_address_id") else None
        ta = addr_by_id.get(e.get("to_address_id")) if e.get("to_address_id") else None
        out.append({
            "transaction_hash": e.get("transaction_hash"),
            "log_index": e.get("log_index"),
            "block_number": e.get("block_number"),
            "block_timestamp": e.get("block_timestamp"),
            "from_address": fa.get("address") if isinstance(fa, dict) else None,
            "to_address": ta.get("address") if isinstance(ta, dict) else None,
            "token_id": tid,
            "contract_address": contract_addr_norm,
            "event_id": e.get("id")
        })

    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"o": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    return {
        "result": out,
        "total": total,
        "page_size": limit,
        "cursor": next_cursor,
        "has_more": has_more
    }

def getnftbycontracttraits(chain, address, traits, limit=None, cursor=None, normalizeMetadata=None, mediaItems=None, **_extra):
    import json, os, datetime, base64, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getnftbycontracttraits"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, error=None, meta=None):
        # Best-effort: if request_logs.json exists use it; otherwise create it (observability).
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"mor_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "error": error,
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "Invalid `cursor`.")
        s = cur.strip()
        # accept "offset:<n>" or base64 {"offset":n}
        if s.startswith("offset:"):
            try:
                off = int(s.split(":", 1)[1])
                if off < 0:
                    return None, _err("VALIDATION_ERROR", "Invalid `cursor`.")
                return off, None
            except Exception:
                return None, _err("VALIDATION_ERROR", "Invalid `cursor`.")
        try:
            padded = s + "=" * (-len(s) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"], None
            if isinstance(obj, int) and obj >= 0:
                return obj, None
            return None, _err("VALIDATION_ERROR", "Invalid `cursor`.")
        except Exception:
            return None, _err("VALIDATION_ERROR", "Invalid `cursor`.")

    def _make_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _resolve_chain(chain_in, chains_rows):
        if not isinstance(chain_in, str) or not chain_in.strip():
            return None, _err("VALIDATION_ERROR", "Invalid `chain`.")
        c = chain_in.strip().lower()
        for r in chains_rows:
            if not isinstance(r, dict):
                continue
            if str(r.get("chain_key", "")).lower() == c or str(r.get("id", "")).lower() == c:
                return r, None
        return None, _err("VALIDATION_ERROR", "Unsupported `chain`.", chain=chain_in)

    # ---- validate inputs (relaxed to match parameter schema; traits.value is STRING but callers may send numbers) ----
    if not isinstance(chain, str) or not chain.strip():
        e = _err("VALIDATION_ERROR", "Invalid `chain`.")
        _append_request_log("error", e["error"])
        return e
    if not isinstance(address, str) or not address.strip():
        e = _err("VALIDATION_ERROR", "Invalid `address`.")
        _append_request_log("error", e["error"])
        return e
    if not isinstance(traits, list) or len(traits) == 0:
        e = _err("VALIDATION_ERROR", "Invalid `traits`; must be a non-empty array.")
        _append_request_log("error", e["error"])
        return e
    for i, t in enumerate(traits):
        if not isinstance(t, dict):
            e = _err("VALIDATION_ERROR", "Invalid `traits`; each item must be an object.", index=i)
            _append_request_log("error", e["error"])
            return e
        if "trait_type" not in t or "value" not in t:
            e = _err("VALIDATION_ERROR", "Invalid `traits`; each item must contain `trait_type` and `value`.", index=i)
            _append_request_log("error", e["error"])
            return e
        if not isinstance(t.get("trait_type"), str) or not t["trait_type"].strip():
            e = _err("VALIDATION_ERROR", "Invalid `traits.trait_type`.", index=i)
            _append_request_log("error", e["error"])
            return e
        # Relax: accept string/number/bool; coerce to string for matching.
        v = t.get("value")
        if v is None:
            e = _err("VALIDATION_ERROR", "Invalid `traits.value`.", index=i)
            _append_request_log("error", e["error"])
            return e

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        e = _err("VALIDATION_ERROR", "Invalid `limit`; must be between 1 and 100.")
        _append_request_log("error", e["error"])
        return e
    if normalizeMetadata is not None and not isinstance(normalizeMetadata, bool):
        e = _err("VALIDATION_ERROR", "Invalid `normalizeMetadata`; must be boolean.")
        _append_request_log("error", e["error"])
        return e
    if mediaItems is not None and not isinstance(mediaItems, bool):
        e = _err("VALIDATION_ERROR", "Invalid `mediaItems`; must be boolean.")
        _append_request_log("error", e["error"])
        return e

    offset, cerr = _parse_cursor(cursor)
    if cerr:
        _append_request_log("error", cerr["error"])
        return cerr

    # ---- resolve chain/address/collection ----
    chains_rows = _load("chains.json")
    if not isinstance(chains_rows, list):
        chains_rows = []
    chain_row, cherr = _resolve_chain(chain, chains_rows)
    if cherr:
        _append_request_log("error", cherr["error"])
        return cherr
    chain_id = chain_row.get("id")
    chain_type = chain_row.get("chain_type")

    addr_in = address.strip()
    if chain_type == "evm":
        if not re.fullmatch(r"0x[a-fA-F0-9]{40}", addr_in):
            e = _err("VALIDATION_ERROR", "Invalid contract `address` for EVM chain.")
            _append_request_log("error", e["error"])
            return e
        addr_norm = addr_in.lower()
    else:
        # allow non-evm format with non-empty
        addr_norm = addr_in

    addresses_rows = _load("addresses.json")
    if not isinstance(addresses_rows, list):
        addresses_rows = []
    contract_addr_row = None
    for r in addresses_rows:
        if not isinstance(r, dict):
            continue
        if r.get("chain_id") == chain_id and str(r.get("address", "")).lower() == str(addr_norm).lower():
            contract_addr_row = r
            break
    if not contract_addr_row:
        # Do not error; contract may not be indexed; return empty.
        result = {"result": [], "total": 0, "page_size": limit, "cursor": None}
        _append_request_log("ok", meta={"chain_id": chain_id, "matched": 0})
        return result
    contract_address_id = contract_addr_row.get("id")

    assets_rows = _load("assets.json")
    if not isinstance(assets_rows, list):
        assets_rows = []

    # Candidate NFTs are nft_item on that chain/contract
    candidates = []
    for a in assets_rows:
        if not isinstance(a, dict):
            continue
        if a.get("chain_id") != chain_id:
            continue
        if a.get("asset_type") != "nft_item":
            continue
        if a.get("contract_address_id") != contract_address_id:
            continue
        if a.get("status") == "hidden":
            continue
        candidates.append(a)

    # Trait match: metadata.attributes (common) or metadata.normalized_metadata.attributes
    def _extract_attrs(meta):
        if not isinstance(meta, dict):
            return []
        attrs = meta.get("attributes")
        if isinstance(attrs, list):
            return attrs
        # some datasets store in "metadata" nested under "metadata"
        mm = meta.get("metadata")
        if isinstance(mm, dict) and isinstance(mm.get("attributes"), list):
            return mm.get("attributes")
        nm = meta.get("normalized_metadata")
        if isinstance(nm, dict) and isinstance(nm.get("attributes"), list):
            return nm.get("attributes")
        return []

    def _matches(asset_row):
        meta = asset_row.get("metadata")
        attrs = _extract_attrs(meta)
        if not attrs:
            return False
        # Build dict of trait_type->set(values as strings)
        trait_map = {}
        for it in attrs:
            if not isinstance(it, dict):
                continue
            tt = it.get("trait_type")
            vv = it.get("value")
            if tt is None or vv is None:
                continue
            k = str(tt)
            trait_map.setdefault(k, set()).add(str(vv))
        for t in traits:
            if str(t.get("trait_type")).strip() == "":
                return False
            req_k = str(t.get("trait_type"))
            req_v = str(t.get("value"))
            if req_k not in trait_map:
                return False
            if req_v not in trait_map[req_k]:
                return False
        return True

    matched = [a for a in candidates if _matches(a)]

    # Deterministic order: token_id numeric if possible, else string
    def _tok_key(a):
        tid = a.get("token_id")
        if tid is None:
            return (1, 0, "")
        s = str(tid)
        if s.isdigit():
            try:
                return (0, int(s), s)
            except Exception:
                return (1, 0, s)
        return (1, 0, s)

    matched.sort(key=_tok_key)

    total = len(matched)
    page = matched[offset: offset + limit]
    next_off = offset + len(page)
    next_cursor = _make_cursor(next_off) if next_off < total else None

    # Response shaping (includeMetadata/mediaItems flags are best-effort since schema stores metadata blob already)
    resp_items = []
    for a in page:
        item = dict(a)
        if not (normalizeMetadata or False):
            # keep as stored; do not strip
            pass
        if not (mediaItems or False):
            # if metadata has media, leave it (do not fabricate), but if a "media" field exists, can omit
            if isinstance(item.get("metadata"), dict) and "media" in item["metadata"]:
                # do not mutate store; only response
                md = dict(item["metadata"])
                md.pop("media", None)
                md.pop("media_items", None)
                item["metadata"] = md
        resp_items.append(item)

    out = {
        "result": resp_items,
        "total": total,
        "page_size": limit,
        "cursor": next_cursor,
        "has_more": next_cursor is not None,
    }
    _append_request_log("ok", meta={"chain_id": chain_id, "contract_address_id": contract_address_id, "returned": len(resp_items), "total": total})
    return out

