    contract_addr_row = None
    for a in addresses:
        if not isinstance(a, dict):
            continue
        if a.get("chain_id") == chain_id and str(a.get("address", "")) == contract_addr_norm:
            contract_addr_row = a
            break

    # If contract address row isn't indexed, we must not error for this endpoint; return empty traits.
    # This matches observed real-world behaviour where traits may be unavailable but call is still valid.
    if not contract_addr_row:
        out = {"chain": chain_row.get("chain_key"), "address": contract_addr_norm, "traits": {}}
        _log("ok", meta={"traits": 0, "reason": "contract_address_not_indexed"})
        return out

    contract_address_id = contract_addr_row.get("id")

    # gather trait occurrences from nft_item assets for this collection
    def _iter_traits(meta):
        if not isinstance(meta, dict):
            return
        attrs = meta.get("attributes")
        if isinstance(attrs, list):
            for it in attrs:
                if not isinstance(it, dict):
                    continue
                tt = it.get("trait_type")
                val = it.get("value")
                if isinstance(tt, str) and tt.strip() and isinstance(val, (str, int, float, bool)):
                    yield (tt.strip(), str(val))
        traits = meta.get("traits")
        if isinstance(traits, dict):
            for k, v in traits.items():
                if isinstance(k, str) and k.strip() and isinstance(v, (str, int, float, bool)):
                    yield (k.strip(), str(v))

    trait_map = {}  # key -> set(values)
    for ast in assets:
        if not isinstance(ast, dict):
            continue
        if ast.get("chain_id") != chain_id:
            continue
        if ast.get("asset_type") != "nft_item":
            continue
        if ast.get("contract_address_id") != contract_address_id:
            continue
        meta = ast.get("metadata")
        for k, v in _iter_traits(meta):
            trait_map.setdefault(k, set()).add(v)

    # If no item metadata traits, try collection metadata itself as a fallback
    if not trait_map:
        coll_meta = None
        for ast in assets:
            if not isinstance(ast, dict):
                continue
            if ast.get("chain_id") == chain_id and ast.get("asset_type") == "nft_collection" and ast.get("contract_address_id") == contract_address_id:
                coll_meta = ast.get("metadata")
                break
        for k, v in _iter_traits(coll_meta):
            trait_map.setdefault(k, set()).add(v)

    # If still empty, return empty (not NOT_FOUND) to avoid rejecting valid calls when dataset lacks indexing.
    traits_out = {k: sorted(list(vs)) for k, vs in sorted(trait_map.items(), key=lambda kv: kv[0].lower())}
    out = {"chain": chain_row.get("chain_key"), "address": contract_addr_norm, "traits": traits_out}
    _log("ok", meta={"traits": len(traits_out)})
    return out

def getnfttrades(chain, address, marketplace=None, from_date=None, to_date=None, cursor=None, limit=None, order=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getnfttrades"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"mor_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "error": error,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _resolve_chain(chain_in, chains_rows):
        if not isinstance(chain_in, str) or not chain_in.strip():
            return None, _err("VALIDATION_ERROR", "Invalid `chain`.")
        c = chain_in.strip().lower()
        for r in chains_rows:
            if not isinstance(r, dict):
                continue
            if str(r.get("chain_key", "")).lower() == c or str(r.get("id", "")).lower() == c:
                return r, None
        return None, _err("VALIDATION_ERROR", "Unsupported `chain`.", chain=chain_in)

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"Malformed {field}; must be ISO-8601 date-time string", field=field)
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(tzinfo=None), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"Malformed {field}; must be ISO-8601 date-time string", field=field)

    def _parse_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "Invalid `cursor`.")
        s = cur.strip()
        if s.startswith("offset:"):
            try:
                off = int(s.split(":", 1)[1])
                if off < 0:
                    return None, _err("VALIDATION_ERROR", "Invalid `cursor`.")
                return off, None
            except Exception:
                return None, _err("VALIDATION_ERROR", "Invalid `cursor`.")
        try:
            padded = s + "=" * (-len(s) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"], None
            if isinstance(obj, int) and obj >= 0:
                return obj, None
            return None, _err("VALIDATION_ERROR", "Invalid `cursor`.")
        except Exception:
            return None, _err("VALIDATION_ERROR", "Invalid `cursor`.")

    def _make_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # ---- validate ----
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        e = _err("VALIDATION_ERROR", "Invalid `limit`; must be 1..100.", field="limit")
        _append_request_log("error", e["error"])
        return e
    if order is None:
        order = "DESC"
    if not isinstance(order, str) or order not in ("ASC", "DESC"):
        e = _err("VALIDATION_ERROR", "Invalid `order`; must be 'ASC' or 'DESC'.", field="order")
        _append_request_log("error", e["error"])
        return e
    if marketplace is not None and (not isinstance(marketplace, str) or not marketplace.strip()):
        e = _err("VALIDATION_ERROR", "Invalid `marketplace`.", field="marketplace")
        _append_request_log("error", e["error"])
        return e

    chains_rows = _load("chains.json")
    if not isinstance(chains_rows, list):
        chains_rows = []
    chain_row, cherr = _resolve_chain(chain, chains_rows)
    if cherr:
        _append_request_log("error", cherr["error"])
        return cherr
    chain_id = chain_row.get("id")
    chain_type = chain_row.get("chain_type")

    if not isinstance(address, str) or not address.strip():
        e = _err("VALIDATION_ERROR", "Invalid `address`.", field="address")
        _append_request_log("error", e["error"])
        return e
    addr_in = address.strip()
    if chain_type == "evm":
        if not re.fullmatch(r"0x[a-fA-F0-9]{40}", addr_in):
            e = _err("VALIDATION_ERROR", "Invalid contract `address` for EVM chain.", field="address")
            _append_request_log("error", e["error"])
            return e
        addr_norm = addr_in.lower()
    else:
        addr_norm = addr_in

    fd, ferr = _parse_dt(from_date, "from_date")
    if ferr:
        _append_request_log("error", ferr["error"])
        return ferr
    td, terr = _parse_dt(to_date, "to_date")
    if terr:
        _append_request_log("error", terr["error"])
        return terr
    if fd and td and fd > td:
        e = _err("VALIDATION_ERROR", "`from_date` must be <= `to_date`.", field="from_date")
        _append_request_log("error", e["error"])
        return e

    offset, cerr = _parse_cursor(cursor)
    if cerr:
        _append_request_log("error", cerr["error"])
        return cerr

    # ---- resolve contract address id (no create-on-read for contracts; only wallets allowed by rules) ----
    addresses_rows = _load("addresses.json")
    if not isinstance(addresses_rows, list):
        addresses_rows = []
    contract_row = None
    for r in addresses_rows:
        if not isinstance(r, dict):
            continue
        if r.get("chain_id") == chain_id and str(r.get("address", "")).lower() == str(addr_norm).lower():
            contract_row = r
            break
    if not contract_row:
        # No indexed contract address row: return empty.
        out = {"result": [], "total": 0, "page_size": limit, "cursor": None, "has_more": False}
        _append_request_log("ok", meta={"chain_id": chain_id, "returned": 0, "total": 0})
        return out
    contract_address_id = contract_row.get("id")

    events_rows = _load("events.json")
    if not isinstance(events_rows, list):
        events_rows = []

    # Filter confirmed nft_trade events for that contract
    filtered = []
    for ev in events_rows:
        if not isinstance(ev, dict):
            continue
        if ev.get("chain_id") != chain_id:
            continue
        if ev.get("status") != "confirmed":
            continue
        if ev.get("event_type") != "nft_trade":
            continue
        if ev.get("contract_address_id") != contract_address_id:
            continue
        ts = ev.get("block_timestamp")
        if not isinstance(ts, str) or not ts:
            continue
        # parse ts
        try:
            s = ts
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            continue
        if fd and dt < fd:
            continue
        if td and dt > td:
            continue
        if marketplace is not None:
            if str(ev.get("marketplace", "")).lower() != marketplace.strip().lower():
                continue
        filtered.append((dt, ev))

    reverse = True if order == "DESC" else False
    filtered.sort(key=lambda x: (x[0], x[1].get("id", "")), reverse=reverse)

    total = len(filtered)
    page_pairs = filtered[offset: offset + limit]
    page = [ev for _, ev in page_pairs]
    next_off = offset + len(page)
    next_cursor = _make_cursor(next_off) if next_off < total else None

    out = {"result": page, "total": total, "page_size": limit, "cursor": next_cursor, "has_more": next_cursor is not None}
    _append_request_log("ok", meta={"chain_id": chain_id, "contract_address_id": contract_address_id, "returned": len(page), "total": total})
    return out

def getnfttradesbytoken(chain, address, token_id, marketplace=None, from_date=None, to_date=None, cursor=None, limit=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")

    def _load(n):
