            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"Malformed {field}; must be ISO-8601 date-time string")
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt, None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"Malformed {field}; must be ISO-8601 date-time string")

    def _is_evm_hex_address(a):
        if not isinstance(a, str):
            return False
        s = a.strip()
        if len(s) != 42 or not s.startswith("0x"):
            return False
        hx = s[2:]
        try:
            int(hx, 16)
            return True
        except ValueError:
            return False

    def _chain_match(chains, chain_param):
        if not isinstance(chain_param, str) or not chain_param.strip():
            return None
        c = chain_param.strip().lower()
        for row in chains:
            if not isinstance(row, dict):
                continue
            if str(row.get("chain_key", "")).lower() == c:
                return row
        return None

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return _load("request_logs.json")

    def _log_call(endpoint, status, latency_ms, meta=None):
        logs = _ensure_request_log()
        rid = f"rl_{int(time.time()*1000)}_{os.getpid()}"
        row = {
            "id": rid,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "getnfttradesbytoken"

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

    if order is None:
        order = "DESC"
    if not isinstance(order, str) or order not in ("ASC", "DESC"):
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "order must be one of: ASC, DESC")

    if not isinstance(address, str) or not address.strip():
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "address must be a non-empty string")
    if not isinstance(token_id, str) or not token_id.strip():
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "token_id must be a non-empty string")
    token_id_norm = token_id.strip()

    chains = _load("chains.json")
    chain_row = _chain_match(chains, chain)
    if not chain_row:
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Unsupported chain")

    chain_id = chain_row.get("id")
    chain_type = chain_row.get("chain_type")

    if chain_type == "evm":
        if not _is_evm_hex_address(address):
            _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid contract address for EVM chain")
        addr_norm = address.strip().lower()
    else:
        addr_norm = address.strip()

    fd, e = _parse_dt(from_date, "from_date")
    if e:
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return e
    td, e = _parse_dt(to_date, "to_date")
    if e:
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return e
    if fd and td and fd > td:
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "from_date must be <= to_date")

    if marketplace is not None and (not isinstance(marketplace, str) or not marketplace.strip()):
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "marketplace must be a non-empty string when provided")

    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            payload = json.loads(base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("endpoint") != endpoint:
                raise ValueError("bad cursor")
            if payload.get("chain_id") != chain_id or payload.get("address") != addr_norm or payload.get("order") != order:
                raise ValueError("cursor does not match request")
            if payload.get("token_id") != token_id_norm:
                raise ValueError("cursor does not match request")
            if payload.get("marketplace") != (marketplace.strip() if isinstance(marketplace, str) else None):
                raise ValueError("cursor does not match request")
            if payload.get("from_date") != (from_date.strip() if isinstance(from_date, str) else None):
                raise ValueError("cursor does not match request")
            if payload.get("to_date") != (to_date.strip() if isinstance(to_date, str) else None):
                raise ValueError("cursor does not match request")
            offset = int(payload.get("offset", 0))
            if offset < 0:
                raise ValueError("bad offset")
        except Exception:
            _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor")

    addresses = _load("addresses.json")
    contract_row = None
    for a in addresses:
        if isinstance(a, dict) and a.get("chain_id") == chain_id and str(a.get("address", "")) == addr_norm:
            contract_row = a
            break
    if not contract_row:
        resp = {"result": [], "total": 0, "page_size": limit, "cursor": None, "has_more": False}
        _log_call(endpoint, "ok", int((time.time() - t0) * 1000), {"returned": 0})
        return resp
    contract_address_id = contract_row.get("id")

    events = _load("events.json")
    rows = []
    for ev in events:
        if not isinstance(ev, dict):
            continue
        if ev.get("chain_id") != chain_id:
            continue
        if ev.get("event_type") != "nft_trade":
            continue
        if ev.get("status") != "confirmed":
            continue
        if ev.get("contract_address_id") != contract_address_id:
            continue
        # match token_id either directly on event.token_id or inside asset metadata is out-of-scope; schema has token_id column
        if str(ev.get("token_id") or "") != token_id_norm:
            continue
        if marketplace is not None and ev.get("marketplace") != marketplace.strip():
            continue

        bts = ev.get("block_timestamp")
        bdt, _e = _parse_dt(bts, "block_timestamp") if isinstance(bts, str) else (None, None)
        if fd and (bdt is None or bdt < fd):
            continue
        if td and (bdt is None or bdt > td):
            continue
        rows.append(ev)

    def _key(ev):
        bts = ev.get("block_timestamp")
        dt, _e = _parse_dt(bts, "block_timestamp") if isinstance(bts, str) else (None, None)
        bn = ev.get("block_number")
        tx = ev.get("transaction_hash") or ""
        li = ev.get("log_index")
        li = li if isinstance(li, int) else -1
        if dt is None:
            dt = datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (dt, bn if isinstance(bn, int) else -1, tx, li)

    rows.sort(key=_key, reverse=(order == "DESC"))
    total = len(rows)
    page = rows[offset:offset + limit]

    next_cursor = None
    if offset + limit < total:
        payload = {
            "endpoint": endpoint,
            "chain_id": chain_id,
            "address": addr_norm,
            "token_id": token_id_norm,
            "marketplace": marketplace.strip() if isinstance(marketplace, str) else None,
            "from_date": from_date.strip() if isinstance(from_date, str) else None,
            "to_date": to_date.strip() if isinstance(to_date, str) else None,
            "order": order,
            "offset": offset + limit,
        }
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8")

    resp = {"result": page, "total": total, "page_size": limit, "cursor": next_cursor, "has_more": next_cursor is not None}
    _log_call(endpoint, "ok", int((time.time() - t0) * 1000), {"returned": len(page), "total": total})
    return resp

