        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}"

    t0 = time.time()
    endpoint = "getnfttradesbywallet"

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

    if order is None:
        order = "DESC"
    if not isinstance(order, str) or order not in ("ASC", "DESC"):
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "order must be one of: ASC, DESC")

    if not isinstance(address, str) or not address.strip():
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "address must be a non-empty string")
    addr_in = address.strip()

    chains = _load("chains.json")
    chain_row = _chain_match(chains, chain)
    if not chain_row:
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Unsupported chain")
    chain_id = chain_row.get("id")
    chain_type = chain_row.get("chain_type")

    if chain_type == "evm":
        if not _is_evm_hex_address(addr_in):
            _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid wallet address for EVM chain")
        addr_norm = addr_in.lower()
    else:
        addr_norm = addr_in

    fd, e = _parse_dt(from_date, "from_date")
    if e:
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return e
    td, e = _parse_dt(to_date, "to_date")
    if e:
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return e
    if fd and td and fd > td:
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "from_date must be <= to_date")

    if marketplace is not None and (not isinstance(marketplace, str) or not marketplace.strip()):
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "marketplace must be a non-empty string when provided")

    # cursor decode
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            payload = json.loads(base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("endpoint") != endpoint:
                raise ValueError("bad cursor")
            if payload.get("chain_id") != chain_id or payload.get("address") != addr_norm or payload.get("order") != order:
                raise ValueError("cursor does not match request")
            if payload.get("marketplace") != (marketplace.strip() if isinstance(marketplace, str) else None):
                raise ValueError("cursor does not match request")
            if payload.get("from_date") != (from_date.strip() if isinstance(from_date, str) else None):
                raise ValueError("cursor does not match request")
            if payload.get("to_date") != (to_date.strip() if isinstance(to_date, str) else None):
                raise ValueError("cursor does not match request")
            offset = int(payload.get("offset", 0))
            if offset < 0:
                raise ValueError("bad offset")
        except Exception:
            _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # Wallet endpoints: create-on-read for addresses only, and must be address_kind='wallet'
    addresses = _load("addresses.json")
    wallet_row = None
    for a in addresses:
        if isinstance(a, dict) and a.get("chain_id") == chain_id and str(a.get("address", "")) == addr_norm and a.get("address_kind") == "wallet":
            wallet_row = a
            break
    if not wallet_row:
        # ensure unique(chain_id,address): if same address exists with different kind, reuse (can't create duplicate)
        existing = None
        for a in addresses:
            if isinstance(a, dict) and a.get("chain_id") == chain_id and str(a.get("address", "")) == addr_norm:
                existing = a
                break
        if existing:
            # if it's not a wallet, we must not mutate kind; just treat as not eligible wallet row
            wallet_row = existing if existing.get("address_kind") == "wallet" else None
        else:
            # create a wallet row
            now = _now_iso()
            new_row = {
                "id": _gen_id("addr"),
                "chain_id": chain_id,
                "address": addr_norm,
                "address_kind": "wallet",
                "ens_name": None,
                "ens_resolved_address": None,
                "first_seen_at": None,
                "last_seen_at": None,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            addresses.append(new_row)
            _save("addresses.json", addresses)
            wallet_row = new_row

    if not wallet_row:
        resp = {"result": [], "total": 0, "page_size": limit, "cursor": None, "has_more": False}
        _log_call(endpoint, "ok", int((time.time() - t0) * 1000), {"returned": 0})
        return resp

    wallet_id = wallet_row.get("id")

    events = _load("events.json")
    rows = []
    for ev in events:
        if not isinstance(ev, dict):
            continue
        if ev.get("chain_id") != chain_id:
            continue
        if ev.get("event_type") != "nft_trade":
            continue
        if ev.get("status") != "confirmed":
            continue
        if ev.get("from_address_id") != wallet_id and ev.get("to_address_id") != wallet_id:
            continue
        if marketplace is not None and ev.get("marketplace") != marketplace.strip():
            continue
        bts = ev.get("block_timestamp")
        bdt, _e = _parse_dt(bts, "block_timestamp") if isinstance(bts, str) else (None, None)
        if fd and (bdt is None or bdt < fd):
            continue
        if td and (bdt is None or bdt > td):
            continue
        rows.append(ev)

    def _key(ev):
        bts = ev.get("block_timestamp")
        dt, _e = _parse_dt(bts, "block_timestamp") if isinstance(bts, str) else (None, None)
        bn = ev.get("block_number")
        tx = ev.get("transaction_hash") or ""
        li = ev.get("log_index")
        li = li if isinstance(li, int) else -1
        if dt is None:
            dt = datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (dt, bn if isinstance(bn, int) else -1, tx, li)

    rows.sort(key=_key, reverse=(order == "DESC"))
    total = len(rows)
    page = rows[offset:offset + limit]

    next_cursor = None
    if offset + limit < total:
        payload = {
            "endpoint": endpoint,
            "chain_id": chain_id,
            "address": addr_norm,
            "marketplace": marketplace.strip() if isinstance(marketplace, str) else None,
            "from_date": from_date.strip() if isinstance(from_date, str) else None,
            "to_date": to_date.strip() if isinstance(to_date, str) else None,
            "order": order,
            "offset": offset + limit,
        }
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8")

    resp = {"result": page, "total": total, "page_size": limit, "cursor": next_cursor, "has_more": next_cursor is not None}
    _log_call(endpoint, "ok", int((time.time() - t0) * 1000), {"returned": len(page), "total": total})
    return resp

def getnftbulkcontractmetadata(chain, addresses, include_floor_price=None, cursor=None, limit=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_evm_hex_address(a):
        if not isinstance(a, str):
            return False
        s = a.strip()
        if len(s) != 42 or not s.startswith("0x"):
            return False
        hx = s[2:]
        try:
            int(hx, 16)
            return True
        except ValueError:
            return False

    def _chain_match(chains, chain_param):
        if not isinstance(chain_param, str) or not chain_param.strip():
            return None
        c = chain_param.strip().lower()
        for row in chains:
            if not isinstance(row, dict):
                continue
            if str(row.get("chain_key", "")).lower() == c:
                return row
        return None

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return _load("request_logs.json")

    def _log_call(endpoint, status, latency_ms, meta=None):
        logs = _ensure_request_log()
        rid = f"rl_{int(time.time()*1000)}_{os.getpid()}"
        row = {"id": rid, "endpoint": endpoint, "status": status, "latency_ms": latency_ms, "timestamp": _now_iso()}
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "getnftbulkcontractmetadata"

    if include_floor_price is None:
        include_floor_price = False
    if not isinstance(include_floor_price, bool):
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_floor_price must be a boolean")

    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 25:
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 25")

    if not isinstance(addresses, list) or len(addresses) < 1 or len(addresses) > 25:
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "addresses must be an array with 1 to 25 items")

    chains = _load("chains.json")
    chain_row = _chain_match(chains, chain)
    if not chain_row:
        _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Unsupported chain")
    chain_id = chain_row.get("id")
    chain_type = chain_row.get("chain_type")

    # validate & normalize input addresses in request order
    norm_addrs = []
    for i, a in enumerate(addresses):
        if not isinstance(a, str) or not a.strip():
            _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"addresses[{i}] must be a non-empty string")
        s = a.strip()
        if chain_type == "evm":
            if not _is_evm_hex_address(s):
                _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", f"Invalid contract address at addresses[{i}] for EVM chain")
            s = s.lower()
        norm_addrs.append(s)

    # cursor decode supports backend pagination over request-order list
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            payload = json.loads(base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("endpoint") != endpoint:
                raise ValueError("bad cursor")
            if payload.get("chain_id") != chain_id:
                raise ValueError("cursor does not match request")
            if payload.get("addresses") != norm_addrs:
                raise ValueError("cursor does not match request")
            offset = int(payload.get("offset", 0))
            if offset < 0:
                raise ValueError("bad offset")
        except Exception:
            _log_call(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # Load lookup tables
    addr_rows = _load("addresses.json")
    assets = _load("assets.json")

    # Build map (chain_id, address) -> address_row
    addr_map = {}
    for r in addr_rows:
        if not isinstance(r, dict):
            continue
        if r.get("chain_id") != chain_id:
            continue
        addr_map[str(r.get("address", ""))] = r

    # Build map contract_address_id -> nft_collection asset row (prefer active, else any non-hidden, else any)
    coll_by_contract = {}
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("chain_id") != chain_id:
            continue
        if a.get("asset_type") != "nft_collection":
            continue
        caid = a.get("contract_address_id")
        if not caid:
            continue
        prev = coll_by_contract.get(caid)
        if prev is None:
            coll_by_contract[caid] = a
        else:
            # prefer active over deprecated over hidden
            rank = {"active": 2, "deprecated": 1, "hidden": 0}
            if rank.get(a.get("status"), 0) > rank.get(prev.get("status"), 0):
                coll_by_contract[caid] = a

    # Page through request-order list
    sliced = norm_addrs[offset:offset + limit]
    result = []
    for s in sliced:
        ar = addr_map.get(s)
        contract_address_id = ar.get("id") if isinstance(ar, dict) else None
        coll = coll_by_contract.get(contract_address_id) if contract_address_id else None

        # Response row is derived from stored asset metadata when possible; otherwise minimal
        out = {
            "chain": str(chain_row.get("chain_key")),
            "address": s,
            "name": coll.get("name") if isinstance(coll, dict) else None,
            "symbol": coll.get("symbol") if isinstance(coll, dict) else None,
            "logo_url": coll.get("logo_url") if isinstance(coll, dict) else None,
            "metadata": coll.get("metadata") if isinstance(coll, dict) else None,
        }
        if include_floor_price:
            out.update({
                "floor_price_native": coll.get("floor_price_native") if isinstance(coll, dict) else None,
                "floor_price_usd": coll.get("floor_price_usd") if isinstance(coll, dict) else None,
                "floor_price_refreshed_at": coll.get("floor_price_refreshed_at") if isinstance(coll, dict) else None,
            })
        result.append(out)

    next_cursor = None
    if offset + limit < len(norm_addrs):
        payload = {"endpoint": endpoint, "chain_id": chain_id, "addresses": norm_addrs, "offset": offset + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8")

    resp = {
        "result": result,
        "total": len(norm_addrs),
        "page_size": limit,
        "cursor": next_cursor,
        "has_more": next_cursor is not None,
    }
    _log_call(endpoint, "ok", int((time.time() - t0) * 1000), {"returned": len(result), "total": len(norm_addrs)})
    return resp

def getnftmetadata(chain, address, token_id, normalize_metadata=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getnftmetadata"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"mor_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "error": error,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    # validation
    if not isinstance(chain, str) or not chain.strip():
        e = _err("VALIDATION_ERROR", "chain must be a non-empty string", field="chain")
        _log("error", e["error"])
        return e
    if not isinstance(address, str) or not address.strip():
        e = _err("VALIDATION_ERROR", "address must be a non-empty string", field="address")
        _log("error", e["error"])
        return e
    if not isinstance(token_id, str) or not token_id.strip():
        e = _err("VALIDATION_ERROR", "token_id must be a non-empty string", field="token_id")
        _log("error", e["error"])
        return e
    if normalize_metadata is not None and not isinstance(normalize_metadata, bool):
        e = _err("VALIDATION_ERROR", "normalize_metadata must be boolean", field="normalize_metadata")
        _log("error", e["error"])
        return e
    normalize_metadata = bool(normalize_metadata) if normalize_metadata is not None else False

    # resolve chain by chain_key or chains.id
    chains = _load("chains.json")
    if not isinstance(chains, list):
        chains = []
    chain_in = chain.strip().lower()
    chain_row = None
    for r in chains:
        if not isinstance(r, dict):
            continue
        if str(r.get("chain_key", "")).lower() == chain_in or str(r.get("id", "")).lower() == chain_in:
            chain_row = r
            break
    if not chain_row:
        e = _err("VALIDATION_ERROR", "Unsupported `chain`.", chain=chain)
        _log("error", e["error"])
        return e
    chain_id = chain_row.get("id")

    addr_in = address.strip()
    if chain_row.get("chain_type") == "evm":
        if not re.fullmatch(r"^0x[a-fA-F0-9]{40}$", addr_in):
            e = _err("VALIDATION_ERROR", "Invalid contract `address` for EVM chain.", field="address")
            _log("error", e["error"])
            return e
        contract_addr_norm = "0x" + addr_in[2:].lower()
    else:
        contract_addr_norm = addr_in

    addresses = _load("addresses.json")
    if not isinstance(addresses, list):
        addresses = []
    assets = _load("assets.json")
    if not isinstance(assets, list):
        assets = []

    contract_addr_row = None
    for a in addresses:
        if not isinstance(a, dict):
            continue
        if a.get("chain_id") == chain_id and str(a.get("address", "")) == contract_addr_norm:
            contract_addr_row = a
            break

    # If contract address isn't indexed, do not error; return an "unindexed" minimal response.
    contract_address_id = contract_addr_row.get("id") if contract_addr_row else None

    nft_item = None
    if contract_address_id:
        for ast in assets:
            if not isinstance(ast, dict):
                continue
            if ast.get("chain_id") == chain_id and ast.get("asset_type") == "nft_item" and ast.get("contract_address_id") == contract_address_id and str(ast.get("token_id")) == token_id:
                nft_item = ast
                break

    collection = None
    if contract_address_id:
        for ast in assets:
            if not isinstance(ast, dict):
                continue
            if ast.get("chain_id") == chain_id and ast.get("asset_type") == "nft_collection" and ast.get("contract_address_id") == contract_address_id:
                collection = ast
                break

    # Build response; real API serves stale metadata if present; if missing, respond with minimal object not error.
    meta = {}
    if nft_item and isinstance(nft_item.get("metadata"), dict):
        meta = nft_item.get("metadata") or {}
    name = nft_item.get("name") if nft_item else None
    symbol = nft_item.get("symbol") if nft_item else None
    token_uri = None
    if isinstance(meta, dict):
        token_uri = meta.get("token_uri") or meta.get("tokenUri") or meta.get("uri")

    def _normalize(meta_in):
        if not isinstance(meta_in, dict):
            return meta_in
        m = dict(meta_in)
        attrs = m.get("attributes")
        if isinstance(attrs, list):
            norm_attrs = []
            for it in attrs:
                if not isinstance(it, dict):
                    continue
                tt = it.get("trait_type") or it.get("traitType") or it.get("key") or it.get("name")
                val = it.get("value")
                if isinstance(tt, str) and tt.strip() and isinstance(val, (str, int, float, bool)):
                    norm_attrs.append({"trait_type": tt.strip(), "value": val})
            if norm_attrs:
                m["attributes"] = norm_attrs
        if "name" not in m and isinstance(name, str) and name:
            m["name"] = name
        if "symbol" not in m and isinstance(symbol, str) and symbol:
            m["symbol"] = symbol
        return m

    meta_out = _normalize(meta) if normalize_metadata else meta

    resp = {
        "chain": chain_row.get("chain_key"),
        "contract_address": contract_addr_norm,
        "token_id": token_id,
        "contract_address_id": contract_address_id,
        "token_uri": token_uri,
        "name": name or (meta_out.get("name") if isinstance(meta_out, dict) else None),
        "symbol": symbol or (meta_out.get("symbol") if isinstance(meta_out, dict) else None),
        "metadata": meta_out if meta_out is not None else {},
        "collection": None,
        "indexed": bool(nft_item),
    }
    if collection:
        resp["collection"] = {
            "asset_id": collection.get("id"),
            "name": collection.get("name"),
            "symbol": collection.get("symbol"),
            "logo_url": collection.get("logo_url"),
            "metadata": collection.get("metadata"),
        }

    _log("ok", meta={"indexed": resp["indexed"], "has_contract": bool(contract_address_id)})
    return resp

def getnfttransfers(chain, address, token_id, from_date=None, to_date=None, cursor=None, limit=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # -------- validation --------
    if not isinstance(chain, str) or not chain.strip():
        return _err("VALIDATION_ERROR", "chain must be a non-empty string")
    if not isinstance(address, str) or not address.strip():
        return _err("VALIDATION_ERROR", "address must be a non-empty string")
    if not isinstance(token_id, str) or not token_id.strip():
        return _err("VALIDATION_ERROR", "token_id must be a non-empty string")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    if order is None:
        order = "DESC"
    if not isinstance(order, str) or order not in ("ASC", "DESC"):
        return _err("VALIDATION_ERROR", "order must be one of: ASC, DESC")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1])
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")
    fd = _parse_dt(from_date, "from_date")
    if isinstance(fd, dict) and "error" in fd:
        return fd
    td = _parse_dt(to_date, "to_date")
    if isinstance(td, dict) and "error" in td:
        return td
    if fd and td and fd > td:
        return _err("VALIDATION_ERROR", "from_date must be <= to_date")

    # -------- resolve chain --------
    chains = _load("chains.json")
    chain_row = None
    c_in = chain.strip().lower()
    for c in chains:
        if str(c.get("chain_key", "")).lower() == c_in or str(c.get("id", "")).lower() == c_in:
            chain_row = c
            break
    if not chain_row:
        return _err("NOT_FOUND", "Unknown chain", chain=chain)
    if chain_row.get("status") == "disabled":
        return _err("UNAUTHORIZED", "Chain is disabled for serving requests", chain=chain_row.get("chain_key"))
    chain_id = chain_row.get("id")
    chain_type = chain_row.get("chain_type")

    # address format
    addr_in = address.strip()
    if chain_type == "evm":
        if not re.fullmatch(r"0x[a-fA-F0-9]{40}", addr_in):
            return _err("VALIDATION_ERROR", "Invalid EVM contract address format", address=address)
        addr_norm = addr_in.lower()
    elif chain_type == "solana":
        if not (32 <= len(addr_in) <= 64) or not re.fullmatch(r"[1-9A-HJ-NP-Za-km-z]+", addr_in):
            return _err("VALIDATION_ERROR", "Invalid Solana address format", address=address)
        addr_norm = addr_in
    else:
        addr_norm = addr_in

    if not re.fullmatch(r"[0-9]+", token_id.strip()):
        return _err("VALIDATION_ERROR", "token_id must be a base-10 integer string", token_id=token_id)
    tok = token_id.strip()

    # cursor decode (base64 json: {"o": offset})
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            offset = int(obj.get("o", 0))
            if offset < 0:
                return _err("VALIDATION_ERROR", "cursor is invalid")
        except (ValueError, json.JSONDecodeError):
            return _err("VALIDATION_ERROR", "cursor is invalid")

    endpoint = "getnfttransfers"
    status_for_log = "success"

    try:
        addresses = _load("addresses.json")
        contract_addr_row = None
        for a in addresses:
            if a.get("chain_id") == chain_id and str(a.get("address", "")).lower() == addr_norm.lower():
                contract_addr_row = a
                break
        if not contract_addr_row:
            # empty result set, not error
            return {
                "result": [],
                "total": 0,
                "page_size": limit,
                "cursor": cursor,
                "next_cursor": None,
                "has_more": False
            }
        contract_address_id = contract_addr_row.get("id")

        events = _load("events.json")
        rows = []
        for e in events:
            if e.get("chain_id") != chain_id:
                continue
            if e.get("status") != "confirmed":
                continue
            if e.get("event_type") != "nft_transfer":
                continue
            if e.get("contract_address_id") != contract_address_id:
                continue
            # token_id can be stored in events.token_id or inferred from asset; for this endpoint require token_id match
            if str(e.get("token_id")) != tok:
                continue
            bt = e.get("block_timestamp")
            if not isinstance(bt, str) or not bt:
                continue
            try:
                if bt.endswith("Z"):
                    btdt = datetime.datetime.fromisoformat(bt[:-1]).replace(tzinfo=datetime.timezone.utc)
                else:
                    btdt = datetime.datetime.fromisoformat(bt)
                    if btdt.tzinfo is None:
                        btdt = btdt.replace(tzinfo=datetime.timezone.utc)
                    btdt = btdt.astimezone(datetime.timezone.utc)
            except ValueError:
                continue
            if fd and btdt < fd:
                continue
            if td and btdt > td:
                continue
            rows.append(e)

        # sort
        def _bt_key(ev):
            s = ev.get("block_timestamp") or ""
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

        reverse = (order == "DESC")
        rows.sort(key=_bt_key, reverse=reverse)

        total = len(rows)
        page = rows[offset: offset + limit]
        next_off = offset + len(page)
        has_more = next_off < total
        next_cursor = None
        if has_more:
            payload = json.dumps({"o": next_off}, separators=(",", ":")).encode("utf-8")
            next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

        # hydrate address strings
        addr_by_id = {a.get("id"): a for a in addresses if a.get("chain_id") == chain_id}
        result = []
        for e in page:
            fa = addr_by_id.get(e.get("from_address_id"))
