            ca = addr_by_id.get(e.get("contract_address_id"))
            result.append({
                "transaction_hash": e.get("transaction_hash"),
                "log_index": e.get("log_index"),
                "block_number": e.get("block_number"),
                "block_timestamp": e.get("block_timestamp"),
                "from_address": fa.get("address") if fa else None,
                "to_address": ta.get("address") if ta else None,
                "contract_address": ca.get("address") if ca else address,
                "token_id": tok,
                "amount_raw": e.get("amount_raw"),
                "amount_decimal": e.get("amount_decimal"),
                "metadata": e.get("metadata"),
                "event_id": e.get("id")
            })

        return {
            "result": result,
            "total": total,
            "page_size": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    finally:
        latency_ms = int((time.time() - _t0) * 1000)
        for log_name in ("request_logs.json", "usage.json", "audit_logs.json"):
            p = os.path.join(_DB, log_name)
            if os.path.exists(p):
                logs = _load(log_name)
                if not isinstance(logs, list):
                    logs = []
                logs.append({
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": endpoint,
                    "chain_id": chain_id if 'chain_id' in locals() else None,
                    "status": status_for_log,
                    "latency_ms": latency_ms,
                    "timestamp": now
                })
                _save(log_name, logs)
                break

