            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")
        try:
            # Accept trailing Z
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")

    def _chain_resolve(chain_in, chains_rows):
        # Accept chain_key or id
        if not isinstance(chain_in, str) or not chain_in.strip():
            return None, _err("VALIDATION_ERROR", "chain must be a non-empty string")
        c = chain_in.strip()
        for r in chains_rows:
            if r.get("id") == c or r.get("chain_key") == c:
                return r, None
        return None, _err("NOT_FOUND", "chain not found")

    def _is_evm_chain(chain_row):
        return chain_row.get("chain_type") == "evm"

    def _norm_evm_addr(a):
        if not isinstance(a, str):
            return None
        aa = a.strip().lower()
        if aa.startswith("0x") and len(aa) == 42:
            h = aa[2:]
            hexd = "0123456789abcdef"
            if all(ch in hexd for ch in h):
                return aa
        return None

    def _log(endpoint, status, chain_id=None, meta=None):
        rows = _load("request_logs.json")
        if not isinstance(rows, list):
            rows = []
        rows.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": status,
            "chain_id": chain_id,
            "credential_id": None,
            "latency_ms": None,
            "timestamp": _now_iso(),
            "meta": meta or {}
        })
        _save("request_logs.json", rows)

    t0 = time.time()
    endpoint = "getnftsaleprices"

    # Validate required types
    if not isinstance(address, str) or not address.strip():
        _log(endpoint, "VALIDATION_ERROR", None, {"field": "address"})
        return _err("VALIDATION_ERROR", "address must be a non-empty string")
    if not isinstance(token_id, str) or token_id == "":
        _log(endpoint, "VALIDATION_ERROR", None, {"field": "token_id"})
        return _err("VALIDATION_ERROR", "token_id must be a non-empty string")
    if not isinstance(days, int):
        _log(endpoint, "VALIDATION_ERROR", None, {"field": "days"})
        return _err("VALIDATION_ERROR", "days must be an integer")
    if days < 1 or days > 3650:
        _log(endpoint, "VALIDATION_ERROR", None, {"field": "days"})
        return _err("VALIDATION_ERROR", "days must be between 1 and 3650")

    if marketplace is not None and (not isinstance(marketplace, str) or not marketplace.strip()):
        _log(endpoint, "VALIDATION_ERROR", None, {"field": "marketplace"})
        return _err("VALIDATION_ERROR", "marketplace must be a non-empty string when provided")

    chains = _load("chains.json")
    chain_row, e = _chain_resolve(chain, chains)
    if e:
        _log(endpoint, e["error"]["code"], None, {"field": "chain"})
        return e
    chain_id = chain_row.get("id")

    if chain_row.get("status") == "disabled":
        _log(endpoint, "INVALID_TRANSITION", chain_id, {"reason": "chain_disabled"})
        return _err("INVALID_TRANSITION", "chain is disabled")

    if not _is_evm_chain(chain_row):
        _log(endpoint, "VALIDATION_ERROR", chain_id, {"reason": "non_evm_chain"})
        return _err("VALIDATION_ERROR", "NFT sale price statistics are only supported for EVM chains in this datastore")

    addr_norm = _norm_evm_addr(address)
    if not addr_norm:
        _log(endpoint, "VALIDATION_ERROR", chain_id, {"field": "address"})
        return _err("VALIDATION_ERROR", "address must be a valid EVM hex address")

    # Parse/derive window
    to_dt, e = _parse_dt(to_date, "to_date")
    if e:
        _log(endpoint, e["error"]["code"], chain_id, {"field": "to_date"})
        return e
    if to_dt is None:
        to_dt = datetime.datetime.now(datetime.timezone.utc)

    from_dt, e = _parse_dt(from_date, "from_date")
    if e:
        _log(endpoint, e["error"]["code"], chain_id, {"field": "from_date"})
        return e

    # If both from_date and to_date provided, use them; else use days lookback from to_dt
    if from_date is not None:
        if from_dt >= to_dt:
            _log(endpoint, "VALIDATION_ERROR", chain_id, {"field": "from_date"})
            return _err("VALIDATION_ERROR", "from_date must be earlier than to_date")
    else:
        from_dt = to_dt - datetime.timedelta(days=days)

    # Resolve contract address row (do not create; this is not a wallet endpoint)
    addresses = _load("addresses.json")
    contract_addr_row = None
    for a in addresses:
        if a.get("chain_id") == chain_id and a.get("address") == addr_norm:
            contract_addr_row = a
            break
    if not contract_addr_row:
        _log(endpoint, "NOT_FOUND", chain_id, {"reason": "contract_address_not_indexed"})
        return _err("NOT_FOUND", "contract address not found")

    contract_address_id = contract_addr_row.get("id")

    # Filter nft_trade events for this NFT: prefer asset_id that matches nft_item, else match contract+token_id on event
    assets = _load("assets.json")
    nft_item_asset_ids = set()
    for r in assets:
        if r.get("chain_id") == chain_id and r.get("asset_type") == "nft_item" and r.get("contract_address_id") == contract_address_id and r.get("token_id") == token_id:
            nft_item_asset_ids.add(r.get("id"))

    events = _load("events.json")

    def _parse_event_ts(v):
        if not isinstance(v, str):
            return None
        try:
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    # Gather sales
    sales = []
    for ev in events:
        if ev.get("chain_id") != chain_id:
            continue
        if ev.get("status") != "confirmed":
            continue
        if ev.get("event_type") != "nft_trade":
            continue
        if marketplace is not None and ev.get("marketplace") != marketplace:
            continue

        ev_ts = _parse_event_ts(ev.get("block_timestamp"))
        if ev_ts is None:
            continue
        if not (from_dt <= ev_ts < to_dt):
            continue

        # Match NFT
        matched = False
        if nft_item_asset_ids and ev.get("asset_id") in nft_item_asset_ids:
            matched = True
        else:
            if ev.get("contract_address_id") == contract_address_id and (ev.get("token_id") == token_id or (isinstance(ev.get("metadata"), dict) and str(ev["metadata"].get("token_id")) == str(token_id))):
                matched = True
        if not matched:
            continue

        # Determine price: prefer metadata fields; else value_usd if present; else skip
        price_native = None
        price_usd = None
        md = ev.get("metadata") if isinstance(ev.get("metadata"), dict) else {}
        for k in ("price_native", "price", "sale_price_native", "floor_price_native"):
            if isinstance(md.get(k), (int, float)):
                price_native = float(md.get(k))
                break
        if isinstance(md.get("price_usd"), (int, float)):
            price_usd = float(md.get("price_usd"))
        elif isinstance(ev.get("value_usd"), (int, float)):
            price_usd = float(ev.get("value_usd"))

        # Only count a sale if we have at least one numeric price
        if price_native is None and price_usd is None:
            continue

        sales.append({
            "ts": ev_ts,
            "block_number": ev.get("block_number"),
            "log_index": ev.get("log_index") if ev.get("log_index") is not None else -1,
            "transaction_hash": ev.get("transaction_hash"),
            "marketplace": ev.get("marketplace"),
            "price_native": price_native,
            "price_usd": price_usd
        })

    # Sort by time then block/log for "last"
    sales.sort(key=lambda x: (x["ts"], x["block_number"] if isinstance(x["block_number"], int) else -1, x["log_index"] if isinstance(x["log_index"], int) else -1))

    def _agg(field):
        vals = [s[field] for s in sales if isinstance(s.get(field), (int, float))]
        if not vals:
            return None, None, None, None
        low = min(vals)
        high = max(vals)
        avg = sum(vals) / len(vals)
        last = None
        for s in reversed(sales):
            if isinstance(s.get(field), (int, float)):
                last = s[field]
                break
        return last, low, high, avg

    last_native, low_native, high_native, avg_native = _agg("price_native")
    last_usd, low_usd, high_usd, avg_usd = _agg("price_usd")

    resp = {
        "chain": chain_row.get("chain_key"),
        "chain_id": chain_id,
        "address": addr_norm,
        "token_id": token_id,
        "marketplace": marketplace,
        "from_date": from_dt.isoformat(),
        "to_date": to_dt.isoformat(),
        "total_trades": len(sales),
        "price_native": {
            "last": last_native,
            "low": low_native,
            "high": high_native,
            "average": avg_native
        },
        "price_usd": {
            "last": last_usd,
            "low": low_usd,
            "high": high_usd,
            "average": avg_usd
        },
        "last_trade": (None if not sales else {
            "transaction_hash": sales[-1].get("transaction_hash"),
            "block_number": sales[-1].get("block_number"),
            "log_index": None if sales[-1].get("log_index") == -1 else sales[-1].get("log_index"),
            "block_timestamp": sales[-1]["ts"].isoformat(),
            "marketplace": sales[-1].get("marketplace"),
            "price_native": sales[-1].get("price_native"),
            "price_usd": sales[-1].get("price_usd")
        })
    }

    _log(endpoint, "OK", chain_id, {"latency_ms": int((time.time() - t0) * 1000)})
    return resp

def getswapsbytokenaddress(chain, token_address, from_block=None, to_block=None, from_date=None, to_date=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getswapsbytokenaddress"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error=None, meta=None, chain_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"mor_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "chain_id": chain_id,
            "credential_id": None,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "error": error,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _parse_dt(s, field, exclusive=False):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string", field=field)
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid RFC3339 date-time string", field=field)

    def _norm_evm_addr(a):
        if not isinstance(a, str):
            return None
        aa = a.strip()
        if not re.fullmatch(r"^0x[a-fA-F0-9]{40}$", aa):
            return None
        return "0x" + aa[2:].lower()

    def _decode_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        s = cur.strip()

        # support simple "offset:<n>" cursors
        if s.startswith("offset:"):
            try:
                off = int(s.split(":", 1)[1])
                if off < 0:
                    return None, _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
                return off, None
            except ValueError:
                return None, _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

        # support opaque base64 json {"v":1,"o":<offset>}
        try:
            raw = base64.urlsafe_b64decode(s.encode("utf-8") + b"=" * (-len(s) % 4)).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return None, _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            off = obj.get("o")
            if not isinstance(off, int) or off < 0:
                return None, _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    def _encode_cursor(off):
        raw = json.dumps({"v": 1, "o": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # validate
    if not isinstance(chain, str) or not chain.strip():
        e = _err("VALIDATION_ERROR", "chain must be a non-empty string", field="chain")
        _log("error", e["error"])
        return e
    norm_token = _norm_evm_addr(token_address)
    if norm_token is None:
        e = _err("VALIDATION_ERROR", "token_address must be a valid EVM address", field="token_address")
        _log("error", e["error"])
        return e

    if from_block is not None and (not isinstance(from_block, int) or from_block < 0):
        e = _err("VALIDATION_ERROR", "from_block must be an integer >= 0", field="from_block")
        _log("error", e["error"])
        return e
    if to_block is not None and (not isinstance(to_block, int) or to_block < 0):
        e = _err("VALIDATION_ERROR", "to_block must be an integer >= 0", field="to_block")
        _log("error", e["error"])
        return e
    if from_block is not None and to_block is not None and from_block > to_block:
        e = _err("VALIDATION_ERROR", "from_block must be <= to_block", field="from_block")
        _log("error", e["error"])
        return e

    from_dt, err = _parse_dt(from_date, "from_date")
    if err:
        _log("error", err["error"])
        return err
    to_dt, err = _parse_dt(to_date, "to_date")
    if err:
        _log("error", err["error"])
        return err
    if from_dt is not None and to_dt is not None and from_dt > to_dt:
        e = _err("VALIDATION_ERROR", "from_date must be <= to_date", field="from_date")
        _log("error", e["error"])
        return e

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or not (1 <= limit <= 1000):
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 1000", field="limit")
        _log("error", e["error"])
        return e

    if order is None:
        order = "DESC"
    if not isinstance(order, str) or order not in ("ASC", "DESC"):
        e = _err("VALIDATION_ERROR", "order must be ASC or DESC", field="order")
        _log("error", e["error"])
        return e

    offset, err = _decode_cursor(cursor)
    if err:
        _log("error", err["error"])
        return err

    # resolve chain by id or chain_key (business rule)
    chains_rows = _load("chains.json")
    if not isinstance(chains_rows, list):
        chains_rows = []
    chain_row = None
    c_in = chain.strip()
    for r in chains_rows:
        if isinstance(r, dict) and (r.get("id") == c_in or r.get("chain_key") == c_in):
            chain_row = r
            break
    if not chain_row:
        e = _err("NOT_FOUND", "chain not found", chain=chain)
        _log("error", e["error"])
        return e
    chain_id = chain_row.get("id")

    # resolve token contract address row (do NOT error if absent; return empty dataset)
    addresses = _load("addresses.json")
    if not isinstance(addresses, list):
        addresses = []
    token_addr_row = next((a for a in addresses if isinstance(a, dict) and a.get("chain_id") == chain_id and (a.get("address") or "").lower() == norm_token.lower()), None)
    token_addr_id = token_addr_row.get("id") if token_addr_row else None

    # resolve token asset row if exists (erc20)
    assets = _load("assets.json")
    if not isinstance(assets, list):
        assets = []
    token_asset_row = None
    if token_addr_id:
        for a in assets:
            if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("asset_type") == "erc20" and a.get("contract_address_id") == token_addr_id:
                token_asset_row = a
                break
    token_asset_id = token_asset_row.get("id") if token_asset_row else None

    events = _load("events.json")
    if not isinstance(events, list):
        events = []

    def _evt_dt(ev):
        ts = ev.get("block_timestamp")
        if not isinstance(ts, str) or not ts:
            return None
        try:
            ss = ts
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    # filter swaps: events.event_type='swap', confirmed, chain-scoped, and involving token via asset_id or counter_asset_id.
    # If token not resolvable to an asset_id, return empty list (do not NOT_FOUND).
    matched = []
    if token_asset_id:
        for ev in events:
            if not isinstance(ev, dict):
                continue
            if ev.get("chain_id") != chain_id:
                continue
            if ev.get("event_type") != "swap":
                continue
            if ev.get("status") != "confirmed":
                continue
            if ev.get("asset_id") != token_asset_id and ev.get("counter_asset_id") != token_asset_id:
                continue
            bn = ev.get("block_number")
            if isinstance(bn, int):
                if from_block is not None and bn < from_block:
                    continue
                if to_block is not None and bn > to_block:
                    continue
            else:
                continue  # schema requires integer
            dt = _evt_dt(ev)
            if from_dt is not None and dt is not None and dt < from_dt:
                continue
            if to_dt is not None and dt is not None and dt >= to_dt:
                continue
            matched.append(ev)

    # sort and paginate
    def _sort_key(ev):
        li = ev.get("log_index")
        if not isinstance(li, int):
            li = -1
        return (ev.get("block_number", 0), li, ev.get("id") or "")
    matched.sort(key=_sort_key, reverse=(order == "DESC"))

    total = len(matched)
    page = matched[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    resp = {
        "result": page,
        "total": total,
        "page_size": limit,
        "cursor": next_cursor,
        "has_more": has_more,
    }
    _log("ok", meta={"returned": len(page), "total": total, "order": order}, chain_id=chain_id)
    return resp

