    if not isinstance(assets, list):
        assets = []
    events = _load("events.json")
    if not isinstance(events, list):
        events = []
    entity_addresses = _load("entity_addresses.json")
    if not isinstance(entity_addresses, list):
        entity_addresses = []
    entities = _load("entities.json")
    if not isinstance(entities, list):
        entities = []

    # Find or create contract address row (create-on-read allowed for addresses)
    contract_addr_row = next((a for a in addresses if isinstance(a, dict) and a.get("chain_id") == chain_id and isinstance(a.get("address"), str) and a.get("address").lower() == ta), None)
    if contract_addr_row is None:
        # create minimal address row as contract
        def _new_id(prefix, rows):
            alpha = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
            ts = int(time.time() * 1000)
            base = ""
            x = ts
            for _ in range(10):
                base = alpha[x % len(alpha)] + base
                x //= len(alpha)
            cand = f"{prefix}_{base}"
            existing = {r.get("id") for r in rows if isinstance(r, dict)}
            while cand in existing:
                base = base[1:] + alpha[(ts + len(existing)) % len(alpha)]
                cand = f"{prefix}_{base}"
            return cand

        now = _now()
        contract_addr_row = {
            "id": _new_id("mor_addr", addresses),
            "chain_id": chain_id,
            "address": ta,
            "address_kind": "contract",
            "ens_name": None,
            "ens_resolved_address": None,
            "first_seen_at": None,
            "last_seen_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        addresses.append(contract_addr_row)
        _save("addresses.json", addresses)

    contract_address_id = contract_addr_row.get("id")

    # Find token asset (ERC20) if present; do NOT error if missing (compute from events anyway)
    token_asset = next((ast for ast in assets if isinstance(ast, dict) and ast.get("chain_id") == chain_id and ast.get("asset_type") == "erc20" and ast.get("contract_address_id") == contract_address_id), None)

    # Choose cut block: use provided to_block, else max confirmed block_number on chain
    confirmed_chain_events = [e for e in events if isinstance(e, dict) and e.get("chain_id") == chain_id and e.get("status") == "confirmed"]
    if to_block is None:
        max_bn = None
        for ev in confirmed_chain_events:
            bn = ev.get("block_number")
            if isinstance(bn, int):
                if max_bn is None or bn > max_bn:
                    max_bn = bn
        to_block_eff = max_bn if max_bn is not None else 0
    else:
        to_block_eff = to_block

    # Compute holders from net transfer deltas (confirmed token_transfer, up to to_block)
    token_transfers = []
    for ev in confirmed_chain_events:
        if ev.get("event_type") != "token_transfer":
            continue
        if ev.get("asset_id") is None and token_asset is None:
            # can't match by asset_id; try match by contract_address_id if present on transfer event metadata fields
            # minimal schema doesn't guarantee it; so only include those explicitly linked by asset_id when available
            continue
        if token_asset is not None:
            if ev.get("asset_id") != token_asset.get("id"):
                continue
        # block cut
        bn = ev.get("block_number")
        if isinstance(bn, int) and bn > to_block_eff:
            continue
        token_transfers.append(ev)

    # If no token_asset or no linked events, still return empty analytics rather than NOT_FOUND
    # Parse amount_raw as int string; fallback to amount_decimal when present
    deltas = {}  # address_id -> float/int in "raw units" as int
    for ev in token_transfers:
        from_id = ev.get("from_address_id")
        to_id = ev.get("to_address_id")
        amt_raw = ev.get("amount_raw")
        amt_dec = ev.get("amount_decimal")
        amt = None
        if isinstance(amt_raw, str) and amt_raw.strip():
            s = amt_raw.strip()
            if re.fullmatch(r"^-?\d+$", s):
                try:
                    amt = int(s)
                except ValueError:
                    amt = None
        if amt is None and isinstance(amt_dec, (int, float)) and not (isinstance(amt_dec, float) and (math.isnan(amt_dec) or math.isinf(amt_dec))):
            # convert decimal amount to scaled integer if decimals known, else keep float
            if token_asset and isinstance(token_asset.get("decimals"), int):
                try:
                    amt = int(round(float(amt_dec) * (10 ** int(token_asset.get("decimals")))))
                except Exception:
                    amt = None
            else:
                amt = float(amt_dec)

        if amt is None:
            continue

        if isinstance(from_id, str):
            deltas[from_id] = deltas.get(from_id, 0) - amt
        if isinstance(to_id, str):
            deltas[to_id] = deltas.get(to_id, 0) + amt

    holders = {aid: bal for aid, bal in deltas.items() if isinstance(bal, (int, float)) and bal > 0}
    total_holders = len(holders)

    # Supply held by holders (raw integer sum where ints; if floats mixed, sum floats)
    total_supply_raw = None
    if holders:
        if all(isinstance(v, int) for v in holders.values()):
            total_supply_raw = int(sum(holders.values()))
        else:
            total_supply_raw = float(sum(float(v) for v in holders.values()))

    # Distribution (simple buckets)
    distribution = None
    if include_distribution:
        # bucket by percentiles of balances (top 1/5/10/20) and long tail count
        items = sorted(holders.items(), key=lambda kv: kv[1], reverse=True)
        n = len(items)
        def _sum_top(pct):
            k = max(1, int(math.ceil(n * pct)))
            vals = [items[i][1] for i in range(min(k, n))]
            if total_supply_raw in (None, 0):
                return {"count": len(vals), "balance_raw": int(sum(vals)) if all(isinstance(v, int) for v in vals) else float(sum(float(v) for v in vals)), "share": None}
            bal = int(sum(vals)) if all(isinstance(v, int) for v in vals) else float(sum(float(v) for v in vals))
            return {"count": len(vals), "balance_raw": bal, "share": float(bal) / float(total_supply_raw) if float(total_supply_raw) > 0 else None}
        distribution = {
            "total_holders": total_holders,
            "total_supply_raw": total_supply_raw,
            "top_1p": _sum_top(0.01) if n else {"count": 0, "balance_raw": 0, "share": None},
            "top_5p": _sum_top(0.05) if n else {"count": 0, "balance_raw": 0, "share": None},
            "top_10p": _sum_top(0.10) if n else {"count": 0, "balance_raw": 0, "share": None},
            "top_20p": _sum_top(0.20) if n else {"count": 0, "balance_raw": 0, "share": None},
        }

    # Trends/acquisition: approximate using holder changes over daily buckets from transfers timestamps
    trends = None
    acquisition = None
    if include_trends or include_acquisition:
        # parse timestamps
        def _parse_ts(s):
            if not isinstance(s, str) or not s.strip():
                return None
            ss = s.strip()
            try:
                if ss.endswith("Z"):
                    ss = ss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return None

        # Use a window ending at the latest timestamp among considered transfers (or now)
        latest_ts = None
        for ev in token_transfers:
            ts = _parse_ts(ev.get("block_timestamp"))
            if ts and (latest_ts is None or ts > latest_ts):
                latest_ts = ts
        if latest_ts is None:
            latest_ts = datetime.datetime.now(datetime.timezone.utc)

        start_ts = latest_ts - datetime.timedelta(days=days)

        window_transfers = []
        for ev in token_transfers:
            ts = _parse_ts(ev.get("block_timestamp"))
            if ts is None:
                continue
            if ts < start_ts or ts > latest_ts:
                continue
            window_transfers.append((ts, ev))

        # Build snapshots at end of each day in window by replaying deltas
        # Start from balances at start_ts: approximate by replaying only events up to start_ts
        # For small datastore this is fine; if not, return empty trend arrays.
        balances = {}  # address_id -> raw balance
        # replay all token transfers up to start_ts (within cut block already)
        all_cut_transfers = []
        for ev in confirmed_chain_events:
            if ev.get("event_type") != "token_transfer":
                continue
            if token_asset is not None and ev.get("asset_id") != token_asset.get("id"):
                continue
            bn = ev.get("block_number")
            if isinstance(bn, int) and bn > to_block_eff:
                continue
            ts = _parse_ts(ev.get("block_timestamp"))
            if ts is None:
                continue
            if ts <= start_ts:
                all_cut_transfers.append((ts, ev))
        all_cut_transfers.sort(key=lambda x: x[0])

        def _amt(ev):
            ar = ev.get("amount_raw")
            if isinstance(ar, str) and re.fullmatch(r"^-?\d+$", ar.strip()):
                try:
                    return int(ar.strip())
                except ValueError:
                    return None
            ad = ev.get("amount_decimal")
            if isinstance(ad, (int, float)):
                if token_asset and isinstance(token_asset.get("decimals"), int):
                    try:
                        return int(round(float(ad) * (10 ** int(token_asset.get("decimals")))))
                    except Exception:
                        return None
                return float(ad)
            return None

        for _, ev in all_cut_transfers:
            amt = _amt(ev)
            if amt is None:
                continue
            f = ev.get("from_address_id")
            t = ev.get("to_address_id")
            if isinstance(f, str):
                balances[f] = balances.get(f, 0) - amt
            if isinstance(t, str):
                balances[t] = balances.get(t, 0) + amt

        # Now iterate days and apply window transfers
        window_transfers.sort(key=lambda x: x[0])
        idx = 0
        points = []
        acquisitions = []
        # Track first-seen holder in window based on becoming >0
        prev_positive = {k for k, v in balances.items() if isinstance(v, (int, float)) and v > 0}
        for d in range(days):
            day_end = (start_ts + datetime.timedelta(days=d+1))
            day_start = (start_ts + datetime.timedelta(days=d))
            # apply transfers within this day (day_start, day_end]
            while idx < len(window_transfers) and window_transfers[idx][0] <= day_end:
                ts, ev = window_transfers[idx]
                idx += 1
                if ts <= day_start:
                    continue
                amt = _amt(ev)
                if amt is None:
                    continue
                f = ev.get("from_address_id")
                t = ev.get("to_address_id")
                if isinstance(f, str):
                    balances[f] = balances.get(f, 0) - amt
                if isinstance(t, str):
                    balances[t] = balances.get(t, 0) + amt

            cur_positive = {k for k, v in balances.items() if isinstance(v, (int, float)) and v > 0}
            points.append({
                "timestamp": day_end.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
                "holders": len(cur_positive),
            })
            if include_acquisition:
                new_holders = len(cur_positive - prev_positive)
                acquisitions.append({
                    "timestamp": day_end.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
                    "new_holders": new_holders,
                })
            prev_positive = cur_positive

        if include_trends:
            trends = {
                "window_days": days,
                "points": points,
            }
        if include_acquisition:
            acquisition = {
                "window_days": days,
                "points": acquisitions,
            }

    resp = {
        "chain_id": chain_id,
        "chain": chain_row.get("chain_key"),
        "token_address": ta,
        "contract_address_id": contract_address_id,
        "asset_id": token_asset.get("id") if token_asset else None,
        "to_block": to_block_eff,
        "total_holders": total_holders,
        "total_supply_raw": total_supply_raw,
        "distribution": distribution,
        "trends": trends,
        "acquisition": acquisition,
    }
    _log("ok", meta={"included": {"distribution": include_distribution, "trends": include_trends, "acquisition": include_acquisition}}, chain_id=chain_id)
    return resp

def gethistoricaltokenholders(chain, token_address, from_date, to_date, interval, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "gethistoricaltokenholders"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"mor_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "error": error,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _resolve_chain(chain_in, chains_rows):
        if not isinstance(chain_in, str) or not chain_in.strip():
            return None, _err("VALIDATION_ERROR", "chain must be a non-empty string", field="chain")
        c = chain_in.strip().lower()
        for r in chains_rows:
            if not isinstance(r, dict):
                continue
            if str(r.get("chain_key", "")).lower() == c or str(r.get("id", "")).lower() == c:
                return r, None
        return None, _err("NOT_FOUND", "chain not found", chain=chain_in)

    def _parse_dt(s, field):
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string", field=field)
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(tzinfo=None), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string", field=field)

    def _bucket_seconds(iv):
        return {"1h": 3600, "4h": 14400, "1d": 86400, "1w": 604800}.get(iv)

    def _bucket_start(dt, sec):
        epoch = int(dt.replace(tzinfo=datetime.timezone.utc).timestamp())
        b = (epoch // sec) * sec
        return datetime.datetime.fromtimestamp(b, tz=datetime.timezone.utc).replace(tzinfo=None)

    def _parse_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "Invalid `cursor`.", field="cursor")
        s = cur.strip()
        if s.startswith("offset:"):
            try:
                off = int(s.split(":", 1)[1])
                if off < 0:
                    return None, _err("VALIDATION_ERROR", "Invalid `cursor`.", field="cursor")
                return off, None
            except Exception:
                return None, _err("VALIDATION_ERROR", "Invalid `cursor`.", field="cursor")
        try:
            padded = s + "=" * (-len(s) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"], None
            if isinstance(obj, int) and obj >= 0:
                return obj, None
            return None, _err("VALIDATION_ERROR", "Invalid `cursor`.", field="cursor")
        except Exception:
            return None, _err("VALIDATION_ERROR", "Invalid `cursor`.", field="cursor")

    def _make_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # validate
    sec = _bucket_seconds(interval)
    if sec is None:
        e = _err("VALIDATION_ERROR", "interval must be one of: 1h, 4h, 1d, 1w", field="interval")
        _append_request_log("error", e["error"])
        return e

    if limit is None:
        limit = 200
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        e = _err("VALIDATION_ERROR", "limit must be 1..1000", field="limit")
        _append_request_log("error", e["error"])
        return e

    if not isinstance(token_address, str) or not re.fullmatch(r"0x[a-fA-F0-9]{40}", token_address.strip()):
        e = _err("VALIDATION_ERROR", "token_address must be a 0x-prefixed 40-hex EVM address", field="token_address")
        _append_request_log("error", e["error"])
        return e
    token_address_norm = token_address.strip().lower()

    fd, ferr = _parse_dt(from_date, "from_date")
    if ferr:
        _append_request_log("error", ferr["error"])
        return ferr
    td, terr = _parse_dt(to_date, "to_date")
    if terr:
        _append_request_log("error", terr["error"])
        return terr
    if fd >= td:
        e = _err("VALIDATION_ERROR", "from_date must be < to_date", field="from_date")
        _append_request_log("error", e["error"])
        return e

    offset, cerr = _parse_cursor(cursor)
    if cerr:
        _append_request_log("error", cerr["error"])
        return cerr

    chains_rows = _load("chains.json")
    if not isinstance(chains_rows, list):
        chains_rows = []
    chain_row, cherr = _resolve_chain(chain, chains_rows)
    if cherr:
        _append_request_log("error", cherr["error"])
        return cherr
    chain_id = chain_row.get("id")

    # resolve token contract address_id and asset_id (erc20)
    addresses_rows = _load("addresses.json")
    if not isinstance(addresses_rows, list):
        addresses_rows = []
    token_addr_row = None
    for r in addresses_rows:
        if not isinstance(r, dict):
            continue
        if r.get("chain_id") == chain_id and str(r.get("address", "")).lower() == token_address_norm:
            token_addr_row = r
            break
    if not token_addr_row:
        # no indexed token address => no events => empty timeseries
        out = {"result": [], "total": 0, "page_size": limit, "cursor": None, "has_more": False}
        _append_request_log("ok", meta={"chain_id": chain_id, "returned": 0, "total": 0})
        return out

    token_contract_address_id = token_addr_row.get("id")
    assets_rows = _load("assets.json")
    if not isinstance(assets_rows, list):
        assets_rows = []
    token_asset_row = None
    for a in assets_rows:
        if not isinstance(a, dict):
            continue
        if a.get("chain_id") == chain_id and a.get("asset_type") == "erc20" and a.get("contract_address_id") == token_contract_address_id:
            if a.get("status") != "hidden":
                token_asset_row = a
                break
    # asset row is helpful but not required for holder derivation

    events_rows = _load("events.json")
    if not isinstance(events_rows, list):
        events_rows = []

    # collect relevant confirmed token_transfer events for this token
    evs = []
    for ev in events_rows:
        if not isinstance(ev, dict):
            continue
        if ev.get("chain_id") != chain_id:
            continue
        if ev.get("status") != "confirmed":
            continue
        if ev.get("event_type") != "token_transfer":
            continue
        # match by asset_id when present, else by contract_address_id
        if token_asset_row is not None:
            if ev.get("asset_id") != token_asset_row.get("id"):
                continue
        else:
            if ev.get("contract_address_id") != token_contract_address_id:
                continue
        ts = ev.get("block_timestamp")
        if not isinstance(ts, str) or not ts:
            continue
        try:
            ss = ts
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            continue
        if dt < fd or dt >= td:
            continue
        evs.append((dt, ev))

    evs.sort(key=lambda x: (x[0], str(x[1].get("id", ""))))

    # Build buckets boundaries (inclusive start, exclusive end), but only output those with computed holders
    start_bucket = _bucket_start(fd, sec)
    end_bucket = _bucket_start(td, sec)
    buckets = []
    cur = start_bucket
    while cur < end_bucket and len(buckets) < 50000:  # safety cap
        buckets.append(cur)
        cur = cur + datetime.timedelta(seconds=sec)

    if not buckets:
        out = {"result": [], "total": 0, "page_size": limit, "cursor": None, "has_more": False}
        _append_request_log("ok", meta={"chain_id": chain_id, "returned": 0, "total": 0})
        return out

    # For each bucket end, compute holders up to that end by replaying events once.
    # holder balances in raw units: use amount_raw if numeric string; else 0
    balances = {}  # address_id -> int
    bucket_points = []
    idx = 0
    for bstart in buckets:
        bend = bstart + datetime.timedelta(seconds=sec)
        while idx < len(evs) and evs[idx][0] < bend:
            ev = evs[idx][1]
            amt_raw = ev.get("amount_raw")
            try:
                amt = int(str(amt_raw)) if amt_raw is not None else 0
            except Exception:
                amt = 0
            if amt != 0:
                fa = ev.get("from_address_id")
                ta = ev.get("to_address_id")
                if isinstance(fa, str) and fa:
                    balances[fa] = balances.get(fa, 0) - amt
                if isinstance(ta, str) and ta:
                    balances[ta] = balances.get(ta, 0) + amt
            idx += 1
        # holders are those with balance > 0
        holders = 0
        for v in balances.values():
            if v > 0:
                holders += 1
        bucket_points.append({
            "bucket_start": bstart.replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
            "bucket_end": bend.replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
            "holders": holders,
        })

    total = len(bucket_points)
    page = bucket_points[offset: offset + limit]
    next_off = offset + len(page)
    next_cursor = _make_cursor(next_off) if next_off < total else None

    out = {"result": page, "total": total, "page_size": limit, "cursor": next_cursor, "has_more": next_cursor is not None}
    _append_request_log("ok", meta={"chain_id": chain_id, "returned": len(page), "total": total})
    return out

def getmultipletokenprices(chain, tokens, include=None, exclude_low_liquidity=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getmultipletokenprices"
    status = "success"

    # Validation
    if not isinstance(chain, str) or not chain.strip():
        return _err("VALIDATION_ERROR", "chain must be a non-empty string")
    if not isinstance(tokens, list) or len(tokens) < 1 or len(tokens) > 100:
        return _err("VALIDATION_ERROR", "tokens must be an array with 1..100 items")
    if include is not None:
        if not isinstance(include, list):
            return _err("VALIDATION_ERROR", "include must be an array when provided")
        allowed_inc = {"metadata", "offchain_metadata", "logo", "spam_status", "liquidity", "market"}
        for x in include:
            if x not in allowed_inc:
                return _err("VALIDATION_ERROR", f"include contains invalid value: {x}")
    if exclude_low_liquidity is not None and not isinstance(exclude_low_liquidity, bool):
        return _err("VALIDATION_ERROR", "exclude_low_liquidity must be boolean when provided")

    # Resolve chain (by chain_key; also accept chain id string if matches chains.id)
    chains = _load("chains.json")
    chain_row = None
    chain_in = chain.strip()
    for c in chains:
        if c.get("id") == chain_in or c.get("chain_key") == chain_in:
            chain_row = c
            break
    if not chain_row:
        return _err("VALIDATION_ERROR", "Invalid chain")
    if chain_row.get("chain_type") != "evm":
        return _err("VALIDATION_ERROR", "This endpoint supports EVM chains only")
    if chain_row.get("status") == "disabled":
        return _err("NOT_FOUND", "Chain is disabled")

    chain_id = chain_row["id"]

    addresses = _load("addresses.json")
    assets = _load("assets.json")
    events = _load("events.json")

    addr_by_chain_address = {}
    for a in addresses:
        if a.get("chain_id") == chain_id and isinstance(a.get("address"), str):
            addr_by_chain_address[a["address"].lower()] = a

    # Build helpers
    def _is_evm_address(s):
        if not isinstance(s, str):
            return False
        s = s.strip()
        if not s.startswith("0x") or len(s) != 42:
            return False
        try:
            int(s[2:], 16)
            return True
        except Exception:
            return False

    # Pre-index assets by contract_address_id (erc20 only)
    erc20_by_contract_addr_id = {}
    for asr in assets:
        if asr.get("chain_id") != chain_id:
            continue
        if asr.get("asset_type") != "erc20":
            continue
        if asr.get("status") == "hidden":
            continue
        caid = asr.get("contract_address_id")
        if caid:
            erc20_by_contract_addr_id[caid] = asr

    # For historical pricing: use latest confirmed swap involving asset_id with block_number <= to_block if present.
    # Expect metadata may include "price_usd" and/or "price_native" and/or "amount_usd"/"amount_native".
    # Fallback to asset.latest_price_* if no event-based match.
    swaps_by_asset = {}
    for ev in events:
        if ev.get("chain_id") != chain_id:
            continue
        if ev.get("status") != "confirmed":
            continue
        if ev.get("event_type") != "swap":
            continue
        aid = ev.get("asset_id")
        if not aid:
            continue
        swaps_by_asset.setdefault(aid, []).append(ev)
    for aid, lst in swaps_by_asset.items():
        lst.sort(key=lambda e: (e.get("block_number") if isinstance(e.get("block_number"), int) else -1,
                               e.get("log_index") if isinstance(e.get("log_index"), int) else -1))

    inc = set(include or [])
    liquidity_threshold_usd = 1000.0  # service-like threshold; only used when exclude_low_liquidity=True

    results = []
    # Validate each token query object strictly
    for i, q in enumerate(tokens):
        if not isinstance(q, dict):
            return _err("VALIDATION_ERROR", f"tokens[{i}] must be an object")
        if set(q.keys()) - {"token_address", "to_block", "exchange"}:
            return _err("VALIDATION_ERROR", f"tokens[{i}] contains additionalProperties not allowed")
        if "token_address" not in q:
            return _err("VALIDATION_ERROR", f"tokens[{i}].token_address is required")
        token_address = q.get("token_address")
        if not _is_evm_address(token_address):
            return _err("VALIDATION_ERROR", f"tokens[{i}].token_address must be a valid EVM address")
        to_block = q.get("to_block", None)
        if to_block is not None:
            if not isinstance(to_block, int) or to_block < 0:
                return _err("VALIDATION_ERROR", f"tokens[{i}].to_block must be an integer >= 0")
        exchange = q.get("exchange", None)
        if exchange is not None and not isinstance(exchange, str):
            return _err("VALIDATION_ERROR", f"tokens[{i}].exchange must be a string when provided")

    # Now answer each query (aligned array)
    for q in tokens:
        token_address_l = q["token_address"].lower()
        to_block = q.get("to_block", None)
        # exchange currently not used for filtering due to minimal schema; we pass through.
        exchange = q.get("exchange", None)

        addr_row = addr_by_chain_address.get(token_address_l)
        asset_row = None
        if addr_row:
            asset_row = erc20_by_contract_addr_id.get(addr_row["id"])

        # Derive price (latest or to_block)
        price_native = None
        price_usd = None

        if asset_row:
            price_native = asset_row.get("latest_price_native")
            price_usd = asset_row.get("latest_price_usd")

            # Historical override via swaps if to_block set
            if to_block is not None:
                lst = swaps_by_asset.get(asset_row.get("id"), [])
                # binary search last <= to_block
                lo, hi = 0, len(lst) - 1
                best = None
                while lo <= hi:
                    mid = (lo + hi) // 2
                    bn = lst[mid].get("block_number")
                    if not isinstance(bn, int):
                        lo = mid + 1
                        continue
                    if bn <= to_block:
                        best = lst[mid]
                        lo = mid + 1
                    else:
                        hi = mid - 1
                if best:
                    md = best.get("metadata") if isinstance(best.get("metadata"), dict) else {}
                    # Try common vendor-like fields
                    if isinstance(md, dict):
                        if isinstance(md.get("price_native"), (int, float)):
                            price_native = float(md["price_native"])
                        if isinstance(md.get("price_usd"), (int, float)):
                            price_usd = float(md["price_usd"])
                        # Fallback from amount/value fields
                        if price_usd is None and isinstance(best.get("value_usd"), (int, float)):
                            # cannot infer unit price without amount; keep value_usd unused
                            pass

        # Liquidity filter (if requested)
        if exclude_low_liquidity:
            liq = asset_row.get("liquidity_usd") if asset_row else None
            if liq is None or not isinstance(liq, (int, float)) or float(liq) < liquidity_threshold_usd:
                # excluded: return null-like entry aligned? Moralis often returns object with nulls.
                results.append({
                    "token_address": token_address_l,
                    "to_block": to_block,
                    "exchange": exchange,
                    "excluded": True
                })
                continue

        out = {
            "token_address": token_address_l,
            "to_block": to_block,
            "exchange": exchange,
            "native_price": price_native,
            "usd_price": price_usd
        }

        # Enrichments based on include
        if asset_row:
            if "metadata" in inc:
                out["metadata"] = asset_row.get("metadata")
            if "offchain_metadata" in inc:
                # Minimal schema doesn't separate; serve same metadata blob if present
                out["offchain_metadata"] = asset_row.get("metadata")
            if "logo" in inc:
                out["logo"] = asset_row.get("logo_url")
            if "spam_status" in inc:
                out["spam_status"] = asset_row.get("spam_status")
            if "liquidity" in inc:
                out["liquidity_usd"] = asset_row.get("liquidity_usd")
            if "market" in inc:
                out["market"] = {
                    "market_cap_usd": asset_row.get("market_cap_usd"),
                    "fdv_usd": asset_row.get("fdv_usd"),
                    "latest_price_usd": asset_row.get("latest_price_usd")
                }
            # Useful core metadata often returned regardless
            out["name"] = asset_row.get("name")
            out["symbol"] = asset_row.get("symbol")
            out["decimals"] = asset_row.get("decimals")
        else:
            out["name"] = None
            out["symbol"] = None
            out["decimals"] = None

        results.append(out)

    # Audit log (best-effort; schema may not include a request log collection)
    latency_ms = int((time.time() - t0) * 1000)
    try:
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "chain_id": chain_id,
                "status": status,
                "latency_ms": latency_ms,
                "created_at": datetime.datetime.utcnow().isoformat() + "Z"
            })
            _save("request_logs.json", logs)
    except Exception:
        pass

    return {
        "chain": chain_row.get("chain_key"),
        "chain_id": chain_id,
        "result": results
    }

def gettokenowners(chain, token_address, limit=None, cursor=None, order=None, min_percentage=None, include_entities=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "gettokenowners"
    status = "success"

    def _is_evm_address(s):
        if not isinstance(s, str):
            return False
        s = s.strip()
        if not s.startswith("0x") or len(s) != 42:
            return False
        try:
            int(s[2:], 16)
            return True
        except Exception:
            return False

    # Validation
    if not isinstance(chain, str) or not chain.strip():
        return _err("VALIDATION_ERROR", "chain must be a non-empty string")
    if not _is_evm_address(token_address):
        return _err("VALIDATION_ERROR", "token_address must be a valid EVM address")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be an integer in 1..500")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string when provided")
    if order is None:
        order = "DESC"
    if order not in ("DESC", "ASC"):
        return _err("VALIDATION_ERROR", "order must be 'DESC' or 'ASC'")
    if min_percentage is not None:
        if not isinstance(min_percentage, (int, float)) or min_percentage < 0 or min_percentage > 100:
            return _err("VALIDATION_ERROR", "min_percentage must be in [0..100]")
    if include_entities is not None and not isinstance(include_entities, bool):
        return _err("VALIDATION_ERROR", "include_entities must be boolean when provided")
    include_entities = bool(include_entities) if include_entities is not None else False

    # Resolve chain
    chains = _load("chains.json")
    chain_row = None
    chain_in = chain.strip()
    for c in chains:
        if c.get("id") == chain_in or c.get("chain_key") == chain_in:
            chain_row = c
            break
    if not chain_row:
        return _err("VALIDATION_ERROR", "Invalid chain")
    if chain_row.get("chain_type") != "evm":
        return _err("VALIDATION_ERROR", "This endpoint supports EVM chains only")
    if chain_row.get("status") == "disabled":
        return _err("NOT_FOUND", "Chain is disabled")
    chain_id = chain_row["id"]

    addresses = _load("addresses.json")
    assets = _load("assets.json")
    events = _load("events.json")
    entity_addresses = _load("entity_addresses.json")
    entities = _load("entities.json")

    # Build address index
    addr_by_chain_address = {}
    addr_by_id = {}
    for a in addresses:
        if a.get("chain_id") == chain_id and isinstance(a.get("address"), str):
            addr_by_chain_address[a["address"].lower()] = a
        if a.get("id"):
            addr_by_id[a["id"]] = a

    # Ensure token contract address exists (create-on-read allowed for addresses only)
    tok_addr_l = token_address.lower()
    tok_addr_row = addr_by_chain_address.get(tok_addr_l)
    now = datetime.datetime.utcnow().isoformat() + "Z"
    mutated_addresses = False
    if not tok_addr_row:
        new_id = f"addr_{int(time.time()*1000)}_{hashlib.sha1((chain_id+tok_addr_l).encode()).hexdigest()[:8]}"
        tok_addr_row = {
            "id": new_id,
            "chain_id": chain_id,
            "address": tok_addr_l,
            "address_kind": "contract",
            "ens_name": None,
            "ens_resolved_address": None,
            "first_seen_at": None,
            "last_seen_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        addresses.append(tok_addr_row)
        addr_by_chain_address[tok_addr_l] = tok_addr_row
        addr_by_id[new_id] = tok_addr_row
        mutated_addresses = True

    # Find ERC20 asset row for token
    token_asset = None
    for asr in assets:
        if asr.get("chain_id") == chain_id and asr.get("asset_type") == "erc20" and asr.get("contract_address_id") == tok_addr_row["id"]:
            if asr.get("status") != "hidden":
                token_asset = asr
            break
    if not token_asset:
        # No success without effect for "owners" list? This is a read; empty set is ok.
        token_asset_id = None
    else:
        token_asset_id = token_asset.get("id")

    # Cursor handling: cursor is base64 of json {"offset": int, "sig": str}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "offset" not in obj or "sig" not in obj:
                return _err("VALIDATION_ERROR", "Invalid cursor")
            if not isinstance(obj["offset"], int) or obj["offset"] < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor offset")
            # simple signature to bind to request params
            sig_base = f"{endpoint}|{chain_id}|{tok_addr_l}|{order}|{min_percentage}|{include_entities}"
            sig = hashlib.sha256(sig_base.encode()).hexdigest()[:16]
            if obj["sig"] != sig:
                return _err("VALIDATION_ERROR", "Invalid/expired cursor")
            offset = obj["offset"]
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # Compute balances from confirmed token_transfer events
    balances_raw = {}  # address_id -> int (raw)
    total_supply_raw = 0

    if token_asset_id:
        for ev in events:
            if ev.get("chain_id") != chain_id:
                continue
            if ev.get("status") != "confirmed":
                continue
            if ev.get("event_type") != "token_transfer":
                continue
            if ev.get("asset_id") != token_asset_id:
                continue
            amt_s = ev.get("amount_raw")
            if not isinstance(amt_s, str) or not amt_s.strip():
                continue
            try:
                amt = int(amt_s)
            except Exception:
                continue
            if amt == 0:
                continue
            fr = ev.get("from_address_id")
            to = ev.get("to_address_id")
            if fr:
                balances_raw[fr] = balances_raw.get(fr, 0) - amt
            if to:
                balances_raw[to] = balances_raw.get(to, 0) + amt

        # Total supply approximation: sum of positive balances (ignoring negative artefacts)
        for v in balances_raw.values():
            if v > 0:
                total_supply_raw += v

    # Prepare owner rows (only positive balances)
    owners = []
    decimals = token_asset.get("decimals") if token_asset else None
    if decimals is not None and not isinstance(decimals, int):
        decimals = None

    def _to_decimal(raw_int):
        if decimals is None:
            return None
        try:
            return float(raw_int) / (10 ** decimals)
        except Exception:
            return None

    for aid, bal in balances_raw.items():
        if bal <= 0:
            continue
        pct = None
        if total_supply_raw > 0:
            pct = (bal / total_supply_raw) * 100.0
        if min_percentage is not None and pct is not None and pct < float(min_percentage):
            continue
        arow = addr_by_id.get(aid)
        owners.append({
            "address": (arow.get("address") if arow else None),
            "address_id": aid,
            "balance_raw": str(bal),
            "balance": _to_decimal(bal),
            "percentage": pct
        })

    # Sort
    owners.sort(key=lambda r: (r["percentage"] if r["percentage"] is not None else 0.0, int(r["balance_raw"])), reverse=(order == "DESC"))
    total = len(owners)

    # Pagination
    page = owners[offset:offset + limit]
    next_cursor = None
    if offset + limit < total:
        sig_base = f"{endpoint}|{chain_id}|{tok_addr_l}|{order}|{min_percentage}|{include_entities}"
        sig = hashlib.sha256(sig_base.encode()).hexdigest()[:16]
        payload = {"offset": offset + limit, "sig": sig}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    # Enrich with entities/labels
    if include_entities and page:
        # map address_id -> (entity,label,role,confidence)
        joins = {}
        # Build entity index
        ent_by_id = {e.get("id"): e for e in entities if e.get("id")}
        for j in entity_addresses:
            if j.get("address_id") and j.get("entity_id"):
                joins.setdefault(j["address_id"], []).append(j)
        for r in page:
            arr = joins.get(r["address_id"], [])
            enriched = []
            for j in arr:
                e = ent_by_id.get(j["entity_id"])
                if not e or e.get("status") != "active":
                    continue
                enriched.append({
                    "entity_id": e.get("id"),
                    "entity_name": e.get("name"),
                    "category": e.get("category"),
                    "label": j.get("label"),
                    "role": j.get("role"),
                    "confidence": j.get("confidence")
                })
            r["entities"] = enriched

    # Persist any create-on-read address mutation
    if mutated_addresses:
        try:
            _save("addresses.json", addresses)
        except Exception:
            status = "error"
            return _err("CONFLICT", "Failed to persist address row")

    # Audit log (best-effort)
    latency_ms = int((time.time() - t0) * 1000)
    try:
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "chain_id": chain_id,
                "status": status,
                "latency_ms": latency_ms,
                "created_at": datetime.datetime.utcnow().isoformat() + "Z"
            })
            _save("request_logs.json", logs)
    except Exception:
        pass

    return {
        "chain": chain_row.get("chain_key"),
        "chain_id": chain_id,
        "token_address": tok_addr_l,
        "result": page,
        "total": total,
        "page_size": limit,
        "cursor": next_cursor
    }

def gettokenmetadata(chain, addresses, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "gettokenmetadata"
    status = "success"

    def _is_evm_address(s):
        if not isinstance(s, str):
            return False
        s = s.strip()
        if not s.startswith("0x") or len(s) != 42:
            return False
        try:
            int(s[2:], 16)
            return True
        except Exception:
            return False

    # Validation
    if not isinstance(chain, str) or not chain.strip():
        return _err("VALIDATION_ERROR", "chain must be a non-empty string")
    if not isinstance(addresses, list) or len(addresses) < 1 or len(addresses) > 100:
        return _err("VALIDATION_ERROR", "addresses must be an array with 1..100 items")
    for i, a in enumerate(addresses):
        if not _is_evm_address(a):
            return _err("VALIDATION_ERROR", f"addresses[{i}] must be a valid EVM address")

    # Resolve chain
    chains = _load("chains.json")
    chain_row = None
    chain_in = chain.strip()
    for c in chains:
        if c.get("id") == chain_in or c.get("chain_key") == chain_in:
            chain_row = c
            break
    if not chain_row:
        return _err("VALIDATION_ERROR", "Invalid chain")
    if chain_row.get("chain_type") != "evm":
        return _err("VALIDATION_ERROR", "This endpoint supports EVM chains only")
    if chain_row.get("status") == "disabled":
        return _err("NOT_FOUND", "Chain is disabled")
    chain_id = chain_row["id"]

    addr_rows = _load("addresses.json")
    assets = _load("assets.json")

    addr_by_chain_address = {}
    addr_by_id = {}
    for r in addr_rows:
        if r.get("chain_id") == chain_id and isinstance(r.get("address"), str):
            addr_by_chain_address[r["address"].lower()] = r
        if r.get("id"):
            addr_by_id[r["id"]] = r

    now = datetime.datetime.utcnow().isoformat() + "Z"
    mutated = False

    # Create-on-read allowed for addresses only (contract addresses)
    resolved_addr_ids = []
    for a in addresses:
        al = a.lower()
        row = addr_by_chain_address.get(al)
        if not row:
            new_id = f"addr_{int(time.time()*1000)}_{hashlib.sha1((chain_id+al).encode()).hexdigest()[:8]}"
            row = {
                "id": new_id,
                "chain_id": chain_id,
                "address": al,
                "address_kind": "contract",
                "ens_name": None,
                "ens_resolved_address": None,
                "first_seen_at": None,
                "last_seen_at": None,
                "status": "active",
                "created_at": now,
                "updated_at": now
            }
            addr_rows.append(row)
            addr_by_chain_address[al] = row
            addr_by_id[new_id] = row
            mutated = True
        resolved_addr_ids.append(row["id"])

    # Index ERC20 assets by contract_address_id
    erc20_by_contract = {}
    for asr in assets:
        if asr.get("chain_id") != chain_id:
            continue
        if asr.get("asset_type") != "erc20":
            continue
        if asr.get("status") == "hidden":
            continue
        caid = asr.get("contract_address_id")
        if caid:
            erc20_by_contract[caid] = asr

    out = []
    for a in addresses:
        al = a.lower()
        addr_row = addr_by_chain_address.get(al)
        asr = erc20_by_contract.get(addr_row["id"]) if addr_row else None
        if not asr:
            out.append({
                "token_address": al,
                "name": None,
                "symbol": None,
                "decimals": None,
                "logo": None,
                "spam_status": "unknown",
                "metadata": None
            })
        else:
            md = asr.get("metadata")
            out.append({
                "token_address": al,
                "name": asr.get("name"),
                "symbol": asr.get("symbol"),
                "decimals": asr.get("decimals"),
                "logo": asr.get("logo_url"),
                "spam_status": asr.get("spam_status"),
                "metadata": md,
                "market": {
                    "latest_price_native": asr.get("latest_price_native"),
                    "latest_price_usd": asr.get("latest_price_usd"),
                    "market_cap_usd": asr.get("market_cap_usd"),
                    "liquidity_usd": asr.get("liquidity_usd"),
                    "fdv_usd": asr.get("fdv_usd")
                }
            })

    if mutated:
        try:
            _save("addresses.json", addr_rows)
        except Exception:
            status = "error"
            return _err("CONFLICT", "Failed to persist address rows")

    # Audit log (best-effort)
    latency_ms = int((time.time() - t0) * 1000)
    try:
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "chain_id": chain_id,
                "status": status,
                "latency_ms": latency_ms,
                "created_at": datetime.datetime.utcnow().isoformat() + "Z"
            })
            _save("request_logs.json", logs)
    except Exception:
        pass

    return {
        "chain": chain_row.get("chain_key"),
        "chain_id": chain_id,
        "result": out
    }

def gettokencategories(chain, limit=None, cursor=None, q=None, **_extra):
    import json, os, datetime, time, base64, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, meta=None):
        start = time.time()
        row = {
            "id": "mor_req_" + hashlib.sha1(f"{_now()}|{time.time_ns()}|gettokencategories".encode()).hexdigest()[:12].upper(),
            "endpoint": "gettokencategories",
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": _now(),
            "meta": meta or {},
        }
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            reqs = []
        reqs.append(row)
        _save("request_logs.json", reqs)

    # --- Resolve ambient auth (best-effort, never refuse if no auth store exists) ---
    credential_id = None
    creds = _load("api_keys.json")
    if isinstance(creds, list):
        active = [c for c in creds if isinstance(c, dict) and c.get("status") in (None, "active", "enabled")]
        if active:
            credential_id = active[0].get("id")

    # --- Validate inputs ---
    if not isinstance(chain, str) or not chain.strip():
        _log("error", credential_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid 'chain': must be a non-empty string.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        _log("error", credential_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid 'limit': must be an integer between 1 and 1000.")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        _log("error", credential_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid 'cursor': must be a non-empty string when provided.")
    if q is not None and not isinstance(q, str):
        _log("error", credential_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid 'q': must be a string when provided.")

    # --- Chain resolution: accept chain_key or EVM chain id string (best-effort) ---
    chains = _load("chains.json")
    if not isinstance(chains, list):
        chains = []

    chain_in = chain.strip().lower()
    chain_row = None
    for ch in chains:
        if not isinstance(ch, dict):
            continue
        if str(ch.get("id", "")).lower() == chain_in:
            chain_row = ch
            break
        if str(ch.get("chain_key", "")).lower() == chain_in:
            chain_row = ch
            break

    # If user gave a number-like chain (e.g., "1", "137"), try mapping via common keys if present in store.
    if chain_row is None and re.fullmatch(r"\d+", chain_in or ""):
        # attempt best-effort mapping to known chain_key conventions
        common = {
            "1": "eth",
            "56": "bsc",
            "137": "polygon",
            "43114": "avalanche",
            "42161": "arbitrum",
            "10": "optimism",
            "250": "fantom",
            "8453": "base",
        }
        ck = common.get(chain_in)
        if ck:
            for ch in chains:
                if isinstance(ch, dict) and str(ch.get("chain_key", "")).lower() == ck:
                    chain_row = ch
                    break

    if chain_row is None:
        _log("error", credential_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid 'chain': unsupported or unknown chain identifier.")

    if chain_row.get("status") == "disabled":
        _log("error", credential_id, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Chain is currently disabled.")

    chain_id = chain_row.get("id")

    # --- Categories derivation (minimal schema): use assets.metadata.category / categories array if present ---
    assets = _load("assets.json")
    if not isinstance(assets, list):
        assets = []

    # Moralis categories are primarily for ERC-20 discovery; require EVM chain types for categories.
    if chain_row.get("chain_type") != "evm":
        _log("error", credential_id, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Token categories are not supported for this chain.")

    cats = set()
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("chain_id") != chain_id:
            continue
        if a.get("asset_type") != "erc20":
            continue
        if a.get("status") == "hidden":
            continue
        md = a.get("metadata")
        if isinstance(md, dict):
            c = md.get("category")
            if isinstance(c, str) and c.strip():
                cats.add(c.strip())
            c2 = md.get("categories")
            if isinstance(c2, list):
                for x in c2:
                    if isinstance(x, str) and x.strip():
                        cats.add(x.strip())

    if not cats:
        _log("error", credential_id, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "No token categories available for this chain.")

    cat_list = sorted(cats, key=lambda s: s.lower())

    if q is not None and q.strip():
        qq = q.strip().lower()
        cat_list = [c for c in cat_list if qq in c.lower()]

    # --- Cursor pagination ---
    # Cursor format: base64url(json({"v":1,"chain_id":...,"q":...,"o":offset,"exp":epoch}))
    offset = 0
    if cursor is not None:
        try:
            raw = cursor.strip().encode("utf-8")
            # add padding for b64 decode
            pad = b"=" * ((4 - (len(raw) % 4)) % 4)
            payload = base64.urlsafe_b64decode(raw + pad).decode("utf-8")
            obj = json.loads(payload)
        except Exception:
            _log("error", credential_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid 'cursor': could not decode.")
        if not isinstance(obj, dict) or obj.get("v") != 1:
            _log("error", credential_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid 'cursor': bad format.")
        if obj.get("chain_id") != chain_id:
            _log("error", credential_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid 'cursor': chain mismatch.")
        exp = obj.get("exp")
        if not isinstance(exp, int) or exp < 0:
            _log("error", credential_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid 'cursor': missing/invalid expiration.")
        if int(time.time()) > exp:
            _log("error", credential_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid 'cursor': expired.")
        if (obj.get("q") or None) != (q.strip() if isinstance(q, str) else None):
            _log("error", credential_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid 'cursor': query mismatch.")
        o = obj.get("o")
        if not isinstance(o, int) or o < 0:
            _log("error", credential_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid 'cursor': invalid offset.")
        offset = o

    total = len(cat_list)
    page = cat_list[offset: offset + limit]
    next_cursor = None
    has_more = offset + limit < total
    if has_more:
        obj = {
            "v": 1,
            "chain_id": chain_id,
            "q": (q.strip() if isinstance(q, str) and q.strip() else None),
            "o": offset + limit,
            "exp": int(time.time()) + 3600,  # 1 hour cursor TTL
        }
        enc = base64.urlsafe_b64encode(json.dumps(obj, separators=(",", ":")).encode("utf-8")).decode("utf-8")
        next_cursor = enc.rstrip("=")

    _log("ok", credential_id, {"chain_id": chain_id, "returned": len(page), "total": total})
    return {
        "result": [{"name": c} for c in page],
        "page": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
        "chain": {"id": chain_id, "chain_key": chain_row.get("chain_key")},
    }

def gettokentransfers(chain_id, contract_address_id, from_block=None, to_block=None, from_date=None, to_date=None, cursor=None, limit=None, include_metadata=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "gettokentransfers"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"mor_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "chain_id": chain_id,
            "credential_id": None,
            "error": error,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(chain_id, str) or not re.fullmatch(r"^mor_chain_[0-9A-Z]{3,}$", chain_id):
        e = _err("VALIDATION_ERROR", "chain_id must match ^mor_chain_[0-9A-Z]{3,}$", field="chain_id")
        _log("error", e["error"])
        return e
    if not isinstance(contract_address_id, str) or not re.fullmatch(r"^mor_addr_[0-9A-Z]{3,}$", contract_address_id):
        e = _err("VALIDATION_ERROR", "contract_address_id must match ^mor_addr_[0-9A-Z]{3,}$", field="contract_address_id")
        _log("error", e["error"])
        return e
    if from_block is not None and (not isinstance(from_block, int) or from_block < 0):
        e = _err("VALIDATION_ERROR", "from_block must be an integer >= 0", field="from_block")
        _log("error", e["error"])
        return e
    if to_block is not None and (not isinstance(to_block, int) or to_block < 0):
        e = _err("VALIDATION_ERROR", "to_block must be an integer >= 0", field="to_block")
        _log("error", e["error"])
        return e
    if from_block is not None and to_block is not None and from_block > to_block:
        e = _err("VALIDATION_ERROR", "from_block cannot be greater than to_block", field="from_block")
        _log("error", e["error"])
        return e

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string", field=field)
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string", field=field)

    fd, err = _parse_dt(from_date, "from_date")
    if err:
        _log("error", err["error"])
        return err
    td, err = _parse_dt(to_date, "to_date")
    if err:
        _log("error", err["error"])
        return err
    if fd and td and fd > td:
        e = _err("VALIDATION_ERROR", "from_date cannot be after to_date", field="from_date")
        _log("error", e["error"])
        return e

    if limit is None:
        limit = 25
    if not isinstance(limit, int) or not (1 <= limit <= 100):
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")
        _log("error", e["error"])
        return e

    if include_metadata is not None and not isinstance(include_metadata, bool):
        e = _err("VALIDATION_ERROR", "include_metadata must be boolean", field="include_metadata")
        _log("error", e["error"])
        return e
    include_metadata = bool(include_metadata) if include_metadata is not None else False

    # cursor decoding: accept base64 JSON {"offset": n} or "offset:n"
    def _decode_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        s = cur.strip()
        if s.startswith("offset:"):
            try:
                off = int(s.split(":", 1)[1])
                if off < 0:
                    raise ValueError()
                return off, None
            except ValueError:
                return None, _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(s.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            off = int(obj.get("offset", 0))
            if off < 0:
                raise ValueError()
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

    offset, err = _decode_cursor(cursor)
    if err:
        _log("error", err["error"])
        return err

    # Verify chain exists
    chains = _load("chains.json")
    if not isinstance(chains, list):
        chains = []
    if not any(isinstance(c, dict) and c.get("id") == chain_id for c in chains):
        e = _err("NOT_FOUND", "chain_id not found", chain_id=chain_id)
        _log("error", e["error"])
        return e

    # IMPORTANT: do not reject if contract_address_id doesn't exist on chain; return empty results
    events = _load("events.json")
    if not isinstance(events, list):
        events = []

    def _parse_ts(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    # Find ERC20 asset id linked to this contract, if any, to match transfers reliably
    assets = _load("assets.json")
    if not isinstance(assets, list):
        assets = []
    token_asset = next((a for a in assets if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("asset_type") == "erc20" and a.get("contract_address_id") == contract_address_id), None)
    token_asset_id = token_asset.get("id") if token_asset else None

    filtered = []
    for ev in events:
        if not isinstance(ev, dict):
            continue
        if ev.get("chain_id") != chain_id:
            continue
        if ev.get("status") != "confirmed":
            continue
        if ev.get("event_type") != "token_transfer":
            continue
        # match by asset_id when possible; else allow contract_address_id match if event provides it
        if token_asset_id is not None:
            if ev.get("asset_id") != token_asset_id:
                continue
        else:
            # fallback: some datasets may set contract_address_id for token transfers; accept it if present
            if ev.get("contract_address_id") != contract_address_id:
                continue

        bn = ev.get("block_number")
        if isinstance(from_block, int) and (not isinstance(bn, int) or bn < from_block):
            continue
        if isinstance(to_block, int) and (not isinstance(bn, int) or bn > to_block):
            continue
        ts = _parse_ts(ev.get("block_timestamp"))
        if fd and (ts is None or ts < fd):
            continue
        if td and (ts is None or ts > td):
            continue
        filtered.append(ev)

    # Order by block_number desc, log_index desc, created_at desc
    def _sort_key(ev):
        bn = ev.get("block_number")
        li = ev.get("log_index")
        ca = ev.get("created_at")
        return (
            -(bn if isinstance(bn, int) else -1),
            -(li if isinstance(li, int) else -1),
            ca if isinstance(ca, str) else "",
            ev.get("id") if isinstance(ev.get("id"), str) else "",
        )
    filtered.sort(key=_sort_key)

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_off}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Shape response rows
    def _shape(ev):
        out = {
            "id": ev.get("id"),
            "chain_id": ev.get("chain_id"),
            "event_type": ev.get("event_type"),
            "block_number": ev.get("block_number"),
            "block_timestamp": ev.get("block_timestamp"),
            "transaction_hash": ev.get("transaction_hash"),
            "log_index": ev.get("log_index"),
            "from_address_id": ev.get("from_address_id"),
            "to_address_id": ev.get("to_address_id"),
            "contract_address_id": ev.get("contract_address_id"),
            "asset_id": ev.get("asset_id"),
            "amount_raw": ev.get("amount_raw"),
            "amount_decimal": ev.get("amount_decimal"),
            "value_usd": ev.get("value_usd"),
            "status": ev.get("status"),
        }
        if include_metadata:
            out["metadata"] = ev.get("metadata")
        return out

    resp = {
        "result": [_shape(ev) for ev in page],
        "total": total,
        "page_size": limit,
        "cursor": next_cursor,
        "has_more": has_more,
    }
    _log("ok", meta={"offset": offset, "returned": len(page), "total": total, "include_metadata": include_metadata})
    return resp

def getnativebalancesforaddresses(chain_id, address_ids, block_number=None, include_usd_price=None, **_extra):
    import json, os, datetime, time, re, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getnativebalancesforaddresses"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"mor_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "chain_id": chain_id,
            "credential_id": None,
            "error": error,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    if not isinstance(chain_id, str) or not re.fullmatch(r"^mor_chain_[0-9A-Z]{3,}$", chain_id):
        e = _err("VALIDATION_ERROR", "chain_id must match ^mor_chain_[0-9A-Z]{3,}$", field="chain_id")
        _log("error", e["error"])
        return e
    if not isinstance(address_ids, list) or not (1 <= len(address_ids) <= 100):
        e = _err("VALIDATION_ERROR", "address_ids must be an array with 1..100 items", field="address_ids")
        _log("error", e["error"])
        return e
    pat = re.compile(r"^mor_addr_[0-9A-Z]{3,}$")
    for i, aid in enumerate(address_ids):
        if not isinstance(aid, str) or not pat.fullmatch(aid):
            e = _err("VALIDATION_ERROR", "Each address_id must match ^mor_addr_[0-9A-Z]{3,}$", field="address_ids", index=i)
            _log("error", e["error"])
            return e
    if block_number is not None and (not isinstance(block_number, int) or block_number < 0):
        e = _err("VALIDATION_ERROR", "block_number must be an integer >= 0", field="block_number")
        _log("error", e["error"])
        return e
    if include_usd_price is not None and not isinstance(include_usd_price, bool):
        e = _err("VALIDATION_ERROR", "include_usd_price must be boolean", field="include_usd_price")
        _log("error", e["error"])
        return e
    include_usd_price = bool(include_usd_price) if include_usd_price is not None else False

    chains = _load("chains.json")
    if not isinstance(chains, list):
        chains = []
    chain_row = next((c for c in chains if isinstance(c, dict) and c.get("id") == chain_id), None)
    if not chain_row:
        e = _err("NOT_FOUND", "chain_id not found", chain_id=chain_id)
        _log("error", e["error"])
        return e

    addresses = _load("addresses.json")
    if not isinstance(addresses, list):
        addresses = []
    events = _load("events.json")
    if not isinstance(events, list):
        events = []
    assets = _load("assets.json")
    if not isinstance(assets, list):
        assets = []

    # Validate address_ids belong to chain; for missing rows, return NOT_FOUND (per description)
    addr_map = {}
    for aid in address_ids:
        row = next((a for a in addresses if isinstance(a, dict) and a.get("id") == aid), None)
        if row is None:
            e = _err("NOT_FOUND", "address_id not found", address_id=aid)
            _log("error", e["error"])
            return e
        if row.get("chain_id") != chain_id:
            e = _err("VALIDATION_ERROR", "address_id does not belong to chain_id", field="address_ids", address_id=aid, chain_id=chain_id)
            _log("error", e["error"])
            return e
        addr_map[aid] = row

    # Determine effective cut block
    confirmed_chain_events = [e for e in events if isinstance(e, dict) and e.get("chain_id") == chain_id and e.get("status") == "confirmed"]
    if block_number is None:
        max_bn = 0
        for ev in confirmed_chain_events:
            bn = ev.get("block_number")
            if isinstance(bn, int) and bn > max_bn:
                max_bn = bn
        cut_block = max_bn
    else:
        cut_block = block_number

    # Find native asset row for chain (used for optional usd price)
    native_asset = next((a for a in assets if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("asset_type") == "native"), None)
    native_price_usd = None
    if include_usd_price and native_asset and isinstance(native_asset.get("latest_price_usd"), (int, float)):
        p = float(native_asset.get("latest_price_usd"))
        if not (math.isnan(p) or math.isinf(p)) and p >= 0:
            native_price_usd = p

    # Compute native balances from confirmed native_transfer deltas
    balances = {aid: 0 for aid in address_ids}
    for ev in confirmed_chain_events:
        if ev.get("event_type") != "native_transfer":
            continue
        bn = ev.get("block_number")
        if not isinstance(bn, int) or bn > cut_block:
            continue
        amt_raw = ev.get("amount_raw")
        amt_dec = ev.get("amount_decimal")
        amt = None
        if isinstance(amt_raw, str) and re.fullmatch(r"^-?\d+$", amt_raw.strip()):
            try:
                amt = int(amt_raw.strip())
            except ValueError:
                amt = None
        if amt is None and isinstance(amt_dec, (int, float)):
            amt = float(amt_dec)
        if amt is None:
            continue
        f = ev.get("from_address_id")
        t = ev.get("to_address_id")
        if isinstance(f, str) and f in balances:
            balances[f] -= amt
        if isinstance(t, str) and t in balances:
            balances[t] += amt

    result = []
    for aid in address_ids:
        bal = balances.get(aid, 0)
        row = {
            "address_id": aid,
            "balance_raw": str(bal) if isinstance(bal, int) else None,
            "balance": float(bal) if isinstance(bal, (int, float)) else None,
            "block_number": cut_block,
        }
        if include_usd_price:
            row["usd_price"] = native_price_usd
            row["usd_value"] = (float(bal) * native_price_usd) if (native_price_usd is not None and isinstance(bal, (int, float))) else None
        result.append(row)

    resp = {"chain_id": chain_id, "result": result}
    _log("ok", meta={"cut_block": cut_block, "count": len(result), "include_usd_price": include_usd_price})
    return resp

def getwalletapprovals(chain_id, wallet_address_id, token_contract_address_id=None, spender_address_id=None, status=None, cursor=None, limit=None, **_extra):
    import json, os, datetime, time, re, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _audit(endpoint, status_s, detail=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"mor_req_{int(time.time()*1000)}_{os.getpid()}",
            "ts": _now_iso(),
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int((time.time() - _t0) * 1000),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        if not isinstance(chain_id, str) or not re.match(r"^mor_chain_[0-9A-Z]{3,}$", chain_id):
            _audit("getwalletapprovals", "error", "invalid chain_id")
            return _err("VALIDATION_ERROR", "chain_id must match ^mor_chain_[0-9A-Z]{3,}$")
        if not isinstance(wallet_address_id, str) or not re.match(r"^mor_addr_[0-9A-Z]{3,}$", wallet_address_id):
            _audit("getwalletapprovals", "error", "invalid wallet_address_id")
            return _err("VALIDATION_ERROR", "wallet_address_id must match ^mor_addr_[0-9A-Z]{3,}$")

        if token_contract_address_id is not None and (not isinstance(token_contract_address_id, str) or not re.match(r"^mor_addr_[0-9A-Z]{3,}$", token_contract_address_id)):
            _audit("getwalletapprovals", "error", "invalid token_contract_address_id")
            return _err("VALIDATION_ERROR", "token_contract_address_id must match ^mor_addr_[0-9A-Z]{3,}$")
        if spender_address_id is not None and (not isinstance(spender_address_id, str) or not re.match(r"^mor_addr_[0-9A-Z]{3,}$", spender_address_id)):
            _audit("getwalletapprovals", "error", "invalid spender_address_id")
            return _err("VALIDATION_ERROR", "spender_address_id must match ^mor_addr_[0-9A-Z]{3,}$")

        if status is None:
            status = "confirmed"
        if not isinstance(status, str) or status not in ("confirmed", "pending"):
            _audit("getwalletapprovals", "error", "invalid status")
            return _err("VALIDATION_ERROR", "status must be one of: confirmed, pending")

        if limit is None:
            limit = 100
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            _audit("getwalletapprovals", "error", "invalid limit")
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

        offset = 0
        if cursor is not None:
            if not isinstance(cursor, str) or cursor == "":
                _audit("getwalletapprovals", "error", "invalid cursor")
                return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
                parts = raw.split(":")
                if len(parts) != 2 or parts[0] != "offset":
                    raise ValueError("bad cursor")
                offset = int(parts[1])
                if offset < 0:
                    raise ValueError("bad offset")
            except Exception:
                _audit("getwalletapprovals", "error", "malformed cursor")
                return _err("VALIDATION_ERROR", "cursor is malformed")

        chains = _load("chains.json")
        if not any(c.get("id") == chain_id for c in chains):
            _audit("getwalletapprovals", "error", "chain not found")
            return _err("NOT_FOUND", "chain_id not found")

        addrs = _load("addresses.json")
        wallet = next((a for a in addrs if a.get("id") == wallet_address_id and a.get("chain_id") == chain_id), None)
        if wallet is None:
            _audit("getwalletapprovals", "error", "wallet not found on chain")
            return _err("NOT_FOUND", "wallet_address_id not found on this chain")
        if wallet.get("address_kind") != "wallet":
            _audit("getwalletapprovals", "error", "not wallet")
            return _err("VALIDATION_ERROR", "wallet_address_id must refer to an addresses row with address_kind='wallet'")

        if token_contract_address_id is not None:
            ca = next((a for a in addrs if a.get("id") == token_contract_address_id and a.get("chain_id") == chain_id), None)
            if ca is None:
                _audit("getwalletapprovals", "error", "token contract not found")
                return _err("NOT_FOUND", "token_contract_address_id not found on this chain")
        if spender_address_id is not None:
            sa = next((a for a in addrs if a.get("id") == spender_address_id and a.get("chain_id") == chain_id), None)
            if sa is None:
                _audit("getwalletapprovals", "error", "spender not found")
                return _err("NOT_FOUND", "spender_address_id not found on this chain")

        assets = _load("assets.json")
        token_asset_id = None
        if token_contract_address_id is not None:
            token_asset = next((a for a in assets if a.get("chain_id") == chain_id and a.get("asset_type") == "erc20" and a.get("contract_address_id") == token_contract_address_id), None)
            token_asset_id = token_asset.get("id") if token_asset else None
            # If a token contract is specified but no ERC20 asset row exists, return empty list (read).
        # Collect approvals
        events = _load("events.json")
        approvals = []
        for e in events:
            if e.get("chain_id") != chain_id:
                continue
            if e.get("event_type") != "approval":
                continue
            if e.get("status") != status:
                continue

            # Wallet approvals: owner is from_address_id by convention in this minimal schema.
            if e.get("from_address_id") != wallet_address_id:
                continue

            if token_asset_id is not None and e.get("asset_id") != token_asset_id:
                continue
            if token_contract_address_id is not None:
                # Also require contract address match when present
                if e.get("contract_address_id") != token_contract_address_id:
                    continue
            if spender_address_id is not None and e.get("to_address_id") != spender_address_id:
                continue
            approvals.append(e)

        # Sort newest first
        def _key(e):
            li = e.get("log_index")
            li = li if isinstance(li, int) else -1
            bn = e.get("block_number")
            bn = bn if isinstance(bn, int) else -1
            return (bn, li)

        approvals.sort(key=_key, reverse=True)
        total = len(approvals)
        page = approvals[offset: offset + limit]
        next_cursor = None
        if offset + limit < total:
            next_cursor = base64.urlsafe_b64encode(f"offset:{offset+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

        addr_map = {a.get("id"): a for a in addrs if a.get("chain_id") == chain_id}

        def _addr_brief(aid):
            if not aid:
                return None
            a = addr_map.get(aid)
            if not a:
                return {"id": aid}
            return {"id": a.get("id"), "address": a.get("address"), "ens_name": a.get("ens_name")}

        out = []
        for e in page:
            out.append({
                "id": e.get("id"),
                "chain_id": e.get("chain_id"),
                "block_number": e.get("block_number"),
                "block_timestamp": e.get("block_timestamp"),
                "transaction_hash": e.get("transaction_hash"),
                "log_index": e.get("log_index"),
                "owner_address": _addr_brief(e.get("from_address_id")),
                "spender_address": _addr_brief(e.get("to_address_id")),
                "token_contract_address": _addr_brief(e.get("contract_address_id")),
                "asset_id": e.get("asset_id"),
                "amount_raw": e.get("amount_raw"),
                "amount_decimal": e.get("amount_decimal"),
                "status": e.get("status"),
                "metadata": e.get("metadata"),
            })

        _audit("getwalletapprovals", "ok")
        return {
            "result": out,
            "pagination": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": next_cursor is not None,
            },
        }
    except Exception as ex:
        _audit("getwalletapprovals", "error", "server_error")
        return _err("VALIDATION_ERROR", "Server error", detail=str(ex))

def getwallethistory(chain_id, wallet_address_id, from_block=None, to_block=None, from_date=None, to_date=None, include_internal_transfers=None, include_nft_transfers=None, include_token_transfers=None, cursor=None, limit=None, order=None, **_extra):
    import json, os, datetime, time, re, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _audit(endpoint, status_s, detail=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"mor_req_{int(time.time()*1000)}_{os.getpid()}",
            "ts": _now_iso(),
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int((time.time() - _t0) * 1000),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        if not isinstance(chain_id, str) or not re.match(r"^mor_chain_[0-9A-Z]{3,}$", chain_id):
            _audit("getwallethistory", "error", "invalid chain_id")
            return _err("VALIDATION_ERROR", "chain_id must match ^mor_chain_[0-9A-Z]{3,}$")
        if not isinstance(wallet_address_id, str) or not re.match(r"^mor_addr_[0-9A-Z]{3,}$", wallet_address_id):
            _audit("getwallethistory", "error", "invalid wallet_address_id")
            return _err("VALIDATION_ERROR", "wallet_address_id must match ^mor_addr_[0-9A-Z]{3,}$")

        if from_block is not None and (not isinstance(from_block, int) or from_block < 0):
            _audit("getwallethistory", "error", "invalid from_block")
            return _err("VALIDATION_ERROR", "from_block must be an integer >= 0")
        if to_block is not None and (not isinstance(to_block, int) or to_block < 0):
            _audit("getwallethistory", "error", "invalid to_block")
            return _err("VALIDATION_ERROR", "to_block must be an integer >= 0")
        if from_block is not None and to_block is not None and from_block > to_block:
            _audit("getwallethistory", "error", "from_block>to_block")
            return _err("VALIDATION_ERROR", "from_block cannot be greater than to_block")

        fd = _parse_dt(from_date)
        if from_date is not None and fd is None:
            _audit("getwallethistory", "error", "invalid from_date")
            return _err("VALIDATION_ERROR", "from_date must be ISO-8601 date-time")
        td = _parse_dt(to_date)
        if to_date is not None and td is None:
            _audit("getwallethistory", "error", "invalid to_date")
            return _err("VALIDATION_ERROR", "to_date must be ISO-8601 date-time")
        if fd is not None and td is not None and fd > td:
            _audit("getwallethistory", "error", "from_date>to_date")
            return _err("VALIDATION_ERROR", "from_date cannot be greater than to_date")

        if include_internal_transfers is None:
            include_internal_transfers = False
        if include_nft_transfers is None:
            include_nft_transfers = True
        if include_token_transfers is None:
            include_token_transfers = True
        for nm, v in (("include_internal_transfers", include_internal_transfers),
                      ("include_nft_transfers", include_nft_transfers),
                      ("include_token_transfers", include_token_transfers)):
            if not isinstance(v, bool):
                _audit("getwallethistory", "error", f"invalid {nm}")
                return _err("VALIDATION_ERROR", f"{nm} must be boolean")

        if limit is None:
            limit = 100
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            _audit("getwallethistory", "error", "invalid limit")
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

        if order is None:
            order = "desc"
        if not isinstance(order, str) or order not in ("asc", "desc"):
            _audit("getwallethistory", "error", "invalid order")
            return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

        offset = 0
        if cursor is not None:
            if not isinstance(cursor, str) or cursor == "":
                _audit("getwallethistory", "error", "invalid cursor")
                return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
                parts = raw.split(":")
                if len(parts) != 2 or parts[0] != "offset":
                    raise ValueError("bad cursor")
                offset = int(parts[1])
                if offset < 0:
                    raise ValueError("bad offset")
            except Exception:
                _audit("getwallethistory", "error", "malformed cursor")
                return _err("VALIDATION_ERROR", "cursor is malformed")

        chains = _load("chains.json")
        if not any(c.get("id") == chain_id for c in chains):
            _audit("getwallethistory", "error", "chain not found")
            return _err("NOT_FOUND", "chain_id not found")

        addrs = _load("addresses.json")
        wallet = next((a for a in addrs if a.get("id") == wallet_address_id and a.get("chain_id") == chain_id), None)
        if wallet is None:
            _audit("getwallethistory", "error", "wallet not found")
            return _err("NOT_FOUND", "wallet_address_id not found on this chain")
        if wallet.get("address_kind") != "wallet":
            _audit("getwallethistory", "error", "not wallet")
            return _err("VALIDATION_ERROR", "wallet_address_id must refer to an addresses row with address_kind='wallet'")

        events = _load("events.json")

        # Choose event types for history stream:
        types = {"tx"}
        # internal transfers not modeled separately in minimal schema; approximate with native_transfer events
        if include_internal_transfers:
            types.add("native_transfer")
        if include_token_transfers:
            types.add("token_transfer")
        if include_nft_transfers:
            types.add("nft_transfer")

        # Filter to wallet involvement: from/to matches for transfers; for tx also from/to matches (when present)
        hist = []
        for e in events:
            if e.get("chain_id") != chain_id:
                continue
            if e.get("status") != "confirmed":
                continue
            et = e.get("event_type")
            if et not in types:
                continue
            bn = e.get("block_number")
            if not isinstance(bn, int):
                continue
            if from_block is not None and bn < from_block:
                continue
            if to_block is not None and bn > to_block:
                continue
            bt = _parse_dt(e.get("block_timestamp"))
            if bt is None:
                continue
            if fd is not None and bt < fd:
                continue
            if td is not None and bt > td:
                continue

            fa = e.get("from_address_id")
            ta = e.get("to_address_id")

            involved = False
            if et in ("token_transfer", "native_transfer", "nft_transfer"):
                involved = (fa == wallet_address_id or ta == wallet_address_id)
            elif et == "tx":
                involved = (fa == wallet_address_id or ta == wallet_address_id)
            if not involved:
                continue

            hist.append(e)

        # Sort
        def _sort_key(e):
            bn = e.get("block_number")
            bn = bn if isinstance(bn, int) else -1
            li = e.get("log_index")
            li = li if isinstance(li, int) else -1
            bt = _parse_dt(e.get("block_timestamp")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            # For tx, log_index may be null; keep stable order
            return (bn, bt, li, e.get("id") or "")

        reverse = (order == "desc")
        hist.sort(key=_sort_key, reverse=reverse)

        total = len(hist)
        page = hist[offset: offset + limit]
        next_cursor = None
        if offset + limit < total:
            next_cursor = base64.urlsafe_b64encode(f"offset:{offset+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

        addr_map = {a.get("id"): a for a in addrs if a.get("chain_id") == chain_id}

        def _addr_brief(aid):
            if not aid:
                return None
            a = addr_map.get(aid)
            if not a:
                return {"id": aid}
            return {"id": a.get("id"), "address": a.get("address"), "ens_name": a.get("ens_name")}

        out = []
        for e in page:
            et = e.get("event_type")
            rec = {
                "id": e.get("id"),
                "chain_id": e.get("chain_id"),
                "type": et,
                "block_number": e.get("block_number"),
                "block_timestamp": e.get("block_timestamp"),
                "transaction_hash": e.get("transaction_hash"),
                "from_address": _addr_brief(e.get("from_address_id")),
                "to_address": _addr_brief(e.get("to_address_id")),
                "contract_address": _addr_brief(e.get("contract_address_id")),
                "asset_id": e.get("asset_id"),
                "counter_asset_id": e.get("counter_asset_id"),
                "token_id": e.get("token_id"),
                "amount_raw": e.get("amount_raw"),
                "amount_decimal": e.get("amount_decimal"),
                "value_usd": e.get("value_usd"),
                "category": (e.get("metadata") or {}).get("category") if isinstance(e.get("metadata"), dict) else None,
                "summary": (e.get("metadata") or {}).get("summary") if isinstance(e.get("metadata"), dict) else None,
            }
            # include decoded payload in metadata if present
            rec["metadata"] = e.get("metadata")
            out.append(rec)

        _audit("getwallethistory", "ok")
        return {
            "result": out,
            "pagination": {
                "total": total,
                "limit": limit,
                "order": order,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": next_cursor is not None,
            },
        }
    except Exception as ex:
        _audit("getwallethistory", "error", "server_error")
        return _err("VALIDATION_ERROR", "Server error", detail=str(ex))

def getwallettokenbalancesprice(chain_id, wallet_address_id, include_native=None, exclude_spam=None, exclude_low_liquidity=None, exclude_inactive=None, min_liquidity_usd=None, cursor=None, limit=None, **_extra):
