            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"{bname} must be a boolean")
    if min_liquidity_usd is not None:
        if not isinstance(min_liquidity_usd, (int, float)) or isinstance(min_liquidity_usd, bool) or min_liquidity_usd < 0:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "min_liquidity_usd must be a number >= 0")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cursor must be a string")

    include_native = True if include_native is None else include_native
    exclude_spam = False if exclude_spam is None else exclude_spam
    exclude_low_liquidity = False if exclude_low_liquidity is None else exclude_low_liquidity
    exclude_inactive = False if exclude_inactive is None else exclude_inactive
    if min_liquidity_usd is None:
        min_liquidity_usd = 0.0

    chains = _load("chains.json")
    chain = next((c for c in chains if isinstance(c, dict) and c.get("id") == chain_id), None)
    if not chain:
        _log("error", extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "chain_id not found")

    addresses = _load("addresses.json")
    wallet = next((a for a in addresses if isinstance(a, dict) and a.get("id") == wallet_address_id and a.get("chain_id") == chain_id), None)
    if not wallet:
        _log("error", extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "wallet_address_id not found on specified chain_id")
    if wallet.get("address_kind") != "wallet":
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "wallet_address_id must reference an address with address_kind='wallet'")

    assets = _load("assets.json")
    events = _load("events.json")

    # Helper: numeric safe
    def _to_float(x):
        if x is None:
            return None
        if isinstance(x, bool):
            return None
        if isinstance(x, (int, float)):
            return float(x)
        try:
            return float(x)
        except Exception:
            return None

    # Compute balances: for confirmed events only, token_transfer and native_transfer.
    # Convention: to wallet => +amount, from wallet => -amount.
    # We'll use amount_decimal if present; else compute from amount_raw and asset.decimals where possible.
    by_asset = {}  # asset_id -> {"balance": float, "asset": row}
    def _amount_decimal_for_event(ev, asset_row):
        ad = _to_float(ev.get("amount_decimal"))
        if ad is not None:
            return ad
        raw = ev.get("amount_raw")
        if raw is None:
            return None
        try:
            ival = int(str(raw))
        except Exception:
            return None
        dec = asset_row.get("decimals")
        if isinstance(dec, bool):
            dec = None
        if isinstance(dec, int) and dec >= 0:
            return ival / (10 ** dec)
        return float(ival)

    wallet_id = wallet_address_id

    # Pre-filter relevant events for performance
    relevant = []
    for ev in events:
        if not isinstance(ev, dict):
            continue
        if ev.get("chain_id") != chain_id:
            continue
        if ev.get("status") != "confirmed":
            continue
        et = ev.get("event_type")
        if et not in ("token_transfer", "native_transfer"):
            continue
        if ev.get("from_address_id") != wallet_id and ev.get("to_address_id") != wallet_id:
            continue
        relevant.append(ev)

    # Map asset rows by id for chain
    assets_by_id = {a.get("id"): a for a in assets if isinstance(a, dict) and a.get("chain_id") == chain_id and isinstance(a.get("id"), str)}

    # Determine native asset row for the chain if needed
    native_asset = None
    if include_native:
        for a in assets:
            if not isinstance(a, dict):
                continue
            if a.get("chain_id") == chain_id and a.get("asset_type") == "native":
                native_asset = a
                break

    for ev in relevant:
        et = ev.get("event_type")
        asset_id = ev.get("asset_id")
        if et == "native_transfer":
            if not include_native:
                continue
            # Some schemas may not set asset_id for native transfers; if missing, use native_asset.
            if not asset_id and native_asset:
                asset_id = native_asset.get("id")
            if not asset_id:
                # cannot attribute; skip
                continue
        else:
            if not isinstance(asset_id, str):
                continue

        asset_row = assets_by_id.get(asset_id)
        if not asset_row:
            # still could be native asset not in assets_by_id if chain mismatch; skip
            continue

        amt = _amount_decimal_for_event(ev, asset_row)
        if amt is None:
            continue
        sign = 1.0 if ev.get("to_address_id") == wallet_id else -1.0
        by_asset.setdefault(asset_id, {"balance": 0.0, "asset": asset_row})
        by_asset[asset_id]["balance"] += sign * amt

    # Build rows for non-zero balances (Moralis usually returns 0 sometimes; but wallet balances should exclude <=0)
    rows = []
    for aid, info in by_asset.items():
        bal = info["balance"]
        if bal is None:
            continue
        # Exclude near-zero negatives due to rounding; keep exact if meaningfully non-zero
        if abs(bal) < 1e-18:
            continue
        # Exclude negative (shouldn't happen for balances if full history, but in minimal store it can)
        # We'll keep negatives as-is since it's derived from stored events.
        asset_row = info["asset"]

        if exclude_inactive and asset_row.get("status") != "active":
            continue
        ss = asset_row.get("spam_status")
        if exclude_spam and ss in ("suspected_spam", "spam"):
            continue

        liq = _to_float(asset_row.get("liquidity_usd"))
        if exclude_low_liquidity and (liq is None or liq <= 0):
            continue
        if liq is not None and liq < float(min_liquidity_usd):
            continue
        if liq is None and float(min_liquidity_usd) > 0:
            continue

        price_usd = _to_float(asset_row.get("latest_price_usd"))
        value_usd = None
        if price_usd is not None:
            value_usd = bal * price_usd

        rows.append({
            "asset": asset_row,
            "balance": bal,
            "balance_usd": value_usd,
            "price_usd": price_usd,
            "chain_id": chain_id,
            "wallet_address_id": wallet_address_id,
        })

    # Sort: by USD value desc (None last), then symbol/name
    def _sort_key(r):
        v = r.get("balance_usd")
        v_key = -v if isinstance(v, (int, float)) else float("inf")
        sym = (r.get("asset") or {}).get("symbol") or ""
        name = (r.get("asset") or {}).get("name") or ""
        return (v_key, sym.lower(), name.lower(), (r.get("asset") or {}).get("id") or "")
    rows.sort(key=_sort_key)

    # Pagination with cursor = integer offset
    offset = 0
    if cursor:
        try:
            offset = int(cursor)
            if offset < 0:
                raise ValueError()
        except Exception:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor must be an integer offset encoded as a string")
    total = len(rows)
    page = rows[offset: offset + limit]
    next_cursor = None
    if offset + limit < total:
        next_cursor = str(offset + limit)

    resp = {
        "result": page,
        "cursor": next_cursor,
        "has_more": next_cursor is not None,
        "total": total,
    }
    _log("ok", extra={"chain_id": chain_id})
    return resp

def getwalletnetworth(wallet_address_id, chains=None, exclude_spam=None, exclude_low_liquidity=None, exclude_inactive=None, min_liquidity_usd=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getwalletnetworth"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, extra=None):
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                row = {
                    "id": f"mor_req_{int(time.time()*1000)}",
                    "ts": _now(),
                    "endpoint": endpoint,
                    "status": status,
                    "latency_ms": int((time.time() - t0) * 1000),
                }
                if extra:
                    row.update(extra)
                logs.append(row)
                _save(fname, logs)
                break

    if not isinstance(wallet_address_id, str) or not re.match(r"^mor_addr_[0-9A-Z]{3,}$", wallet_address_id):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "wallet_address_id is required and must match ^mor_addr_[0-9A-Z]{3,}$")

    if chains is not None:
        if not isinstance(chains, list) or len(chains) < 1:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "chains must be an array with at least 1 item")
        for c in chains:
            if not isinstance(c, str) or not re.match(r"^mor_chain_[0-9A-Z]{3,}$", c):
                _log("error", extra={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "chains entries must match ^mor_chain_[0-9A-Z]{3,}$")

    for bname, bval in (("exclude_spam", exclude_spam),
                        ("exclude_low_liquidity", exclude_low_liquidity),
                        ("exclude_inactive", exclude_inactive)):
        if bval is not None and not isinstance(bval, bool):
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"{bname} must be a boolean")
    if min_liquidity_usd is not None:
        if not isinstance(min_liquidity_usd, (int, float)) or isinstance(min_liquidity_usd, bool) or min_liquidity_usd < 0:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "min_liquidity_usd must be a number >= 0")

    exclude_spam = False if exclude_spam is None else exclude_spam
    exclude_low_liquidity = False if exclude_low_liquidity is None else exclude_low_liquidity
    exclude_inactive = False if exclude_inactive is None else exclude_inactive
    if min_liquidity_usd is None:
        min_liquidity_usd = 0.0

    addresses = _load("addresses.json")
    wallet_row = next((a for a in addresses if isinstance(a, dict) and a.get("id") == wallet_address_id), None)
    if not wallet_row:
        _log("error", extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "wallet_address_id not found")
    if wallet_row.get("address_kind") != "wallet":
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "wallet_address_id must reference an address with address_kind='wallet'")

    chains_rows = _load("chains.json")
    allowed_chain_ids = None
    if chains is not None:
        allowed_chain_ids = set(chains)
        existing = {c.get("id") for c in chains_rows if isinstance(c, dict)}
        missing = [c for c in chains if c not in existing]
        if missing:
            _log("error", extra={"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "one or more chain ids not found", missing_chain_ids=missing)

    # wallet is chain-scoped in schema; net worth cross-chain expects same wallet address across chains,
    # but we only have wallet_address_id (which is a specific row). We'll:
    # - use this id on its chain
    # - if chains specified include only the chain_id matching wallet row id, unless same address exists as wallet on other chains.
    wallet_address_str = wallet_row.get("address")
    if not isinstance(wallet_address_str, str) or wallet_address_str == "":
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "wallet_address_id row is invalid (missing address)")

    # Build wallet ids per chain by finding addresses rows with same address string and address_kind wallet
    wallet_ids_by_chain = {}
    for a in addresses:
        if not isinstance(a, dict):
            continue
        if a.get("address_kind") != "wallet":
            continue
        if a.get("address") != wallet_address_str:
            continue
        cid = a.get("chain_id")
        if not isinstance(cid, str):
            continue
        if allowed_chain_ids is not None and cid not in allowed_chain_ids:
            continue
        wallet_ids_by_chain[cid] = a.get("id")

    if allowed_chain_ids is None:
        # default to the chain of the provided wallet id
        wallet_ids_by_chain = {wallet_row.get("chain_id"): wallet_address_id}

    assets = _load("assets.json")
    events = _load("events.json")

    def _to_float(x):
        if x is None or isinstance(x, bool):
            return None
        if isinstance(x, (int, float)):
            return float(x)
        try:
            return float(x)
        except Exception:
            return None

    # Build asset index per chain
    assets_by_id = {}
    native_asset_by_chain = {}
    for a in assets:
        if not isinstance(a, dict):
            continue
        aid = a.get("id")
        cid = a.get("chain_id")
        if not isinstance(aid, str) or not isinstance(cid, str):
            continue
        assets_by_id[(cid, aid)] = a
        if a.get("asset_type") == "native":
            native_asset_by_chain[cid] = a

    def _amount_decimal_for_event(ev, asset_row):
        ad = _to_float(ev.get("amount_decimal"))
        if ad is not None:
            return ad
        raw = ev.get("amount_raw")
        if raw is None:
            return None
        try:
            ival = int(str(raw))
        except Exception:
            return None
        dec = asset_row.get("decimals")
        if isinstance(dec, int) and dec >= 0:
            return ival / (10 ** dec)
        return float(ival)

    total_usd = 0.0
    per_chain = []
    per_token = []

    for cid, wid in wallet_ids_by_chain.items():
        # compute balances for this chain
        by_asset = {}
        for ev in events:
            if not isinstance(ev, dict):
                continue
            if ev.get("chain_id") != cid:
                continue
            if ev.get("status") != "confirmed":
                continue
            et = ev.get("event_type")
            if et not in ("token_transfer", "native_transfer"):
                continue
            if ev.get("from_address_id") != wid and ev.get("to_address_id") != wid:
                continue
            asset_id = ev.get("asset_id")
            if et == "native_transfer":
                na = native_asset_by_chain.get(cid)
                if not asset_id and na:
                    asset_id = na.get("id")
            if not isinstance(asset_id, str):
                continue
            asset_row = assets_by_id.get((cid, asset_id))
            if not asset_row:
                continue
            amt = _amount_decimal_for_event(ev, asset_row)
            if amt is None:
                continue
            sign = 1.0 if ev.get("to_address_id") == wid else -1.0
            by_asset.setdefault(asset_id, 0.0)
            by_asset[asset_id] += sign * amt

        chain_usd = 0.0
        # apply filters and price
        for asset_id, bal in by_asset.items():
            if abs(bal) < 1e-18:
                continue
            asset_row = assets_by_id.get((cid, asset_id))
            if not asset_row:
                continue
            if exclude_inactive and asset_row.get("status") != "active":
                continue
            ss = asset_row.get("spam_status")
            if exclude_spam and ss in ("suspected_spam", "spam"):
                continue
            liq = _to_float(asset_row.get("liquidity_usd"))
            if exclude_low_liquidity and (liq is None or liq <= 0):
                continue
            if liq is not None and liq < float(min_liquidity_usd):
                continue
            if liq is None and float(min_liquidity_usd) > 0:
                continue

            price = _to_float(asset_row.get("latest_price_usd"))
            if price is None:
                # no price => counts as 0 networth contribution
                token_usd = 0.0
            else:
                token_usd = bal * price
            chain_usd += token_usd
            per_token.append({
                "chain_id": cid,
                "asset": asset_row,
                "balance": bal,
                "price_usd": price,
                "value_usd": token_usd,
            })

        total_usd += chain_usd
        per_chain.append({"chain_id": cid, "networth_usd": chain_usd})

    # sort tokens by value desc
    per_token.sort(key=lambda r: (-(r.get("value_usd") or 0.0), (r.get("asset") or {}).get("symbol") or "", (r.get("asset") or {}).get("id") or ""))

    resp = {
        "wallet_address_id": wallet_address_id,
        "wallet_address": wallet_address_str,
        "total_networth_usd": total_usd,
        "chains": per_chain,
        "tokens": per_token,
    }
    _log("ok", extra={"wallet_address_id": wallet_address_id})
    return resp

def gettransactionverbose(chain_id, transaction_hash, include_events=None, include_transfers=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "gettransactionverbose"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, extra=None):
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                row = {
                    "id": f"mor_req_{int(time.time()*1000)}",
                    "ts": _now(),
                    "endpoint": endpoint,
                    "status": status,
                    "latency_ms": int((time.time() - t0) * 1000),
                }
                if extra:
                    row.update(extra)
                logs.append(row)
                _save(fname, logs)
                break

    if not isinstance(chain_id, str) or not re.match(r"^mor_chain_[0-9A-Z]{3,}$", chain_id):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "chain_id is required and must match ^mor_chain_[0-9A-Z]{3,}$")
    if not isinstance(transaction_hash, str) or not re.match(r"^(0x)?[A-Fa-f0-9]{64}$", transaction_hash):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "transaction_hash is required and must match ^(0x)?[A-Fa-f0-9]{64}$")
    if include_events is not None and not isinstance(include_events, bool):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_events must be a boolean")
    if include_transfers is not None and not isinstance(include_transfers, bool):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_transfers must be a boolean")
    include_events = False if include_events is None else include_events
    include_transfers = False if include_transfers is None else include_transfers

    chains = _load("chains.json")
    if not any(isinstance(c, dict) and c.get("id") == chain_id for c in chains):
        _log("error", extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "chain_id not found")

    events = _load("events.json")
    addresses = _load("addresses.json")
    assets = _load("assets.json")

    def _addr_row(addr_id):
        if not isinstance(addr_id, str):
            return None
        return next((a for a in addresses if isinstance(a, dict) and a.get("id") == addr_id), None)

    def _asset_row(asset_id):
        if not isinstance(asset_id, str):
            return None
        return next((a for a in assets if isinstance(a, dict) and a.get("id") == asset_id), None)

    # Find tx "header": prefer event_type='tx', else derive from any event with this tx hash.
    tx_events = [e for e in events if isinstance(e, dict) and e.get("chain_id") == chain_id and e.get("transaction_hash") == transaction_hash]
    if not tx_events:
        _log("error", extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "transaction hash not found on specified chain")

    tx_header = None
    for e in tx_events:
        if e.get("event_type") == "tx":
            tx_header = e
            break
    if tx_header is None:
        # pick earliest by log_index, else first
        def _li(e):
            li = e.get("log_index")
            return li if isinstance(li, int) else 10**18
        tx_header = sorted(tx_events, key=_li)[0]

    # Base tx response
    base = {
        "chain_id": chain_id,
        "transaction_hash": transaction_hash,
        "status": tx_header.get("status"),
        "block_number": tx_header.get("block_number"),
        "block_timestamp": tx_header.get("block_timestamp"),
        "from_address": None,
        "to_address": None,
        "contract_address": None,
        "decoded_call": None,
        "metadata": tx_header.get("metadata"),
    }

    fa = _addr_row(tx_header.get("from_address_id"))
    ta = _addr_row(tx_header.get("to_address_id"))
    ca = _addr_row(tx_header.get("contract_address_id"))
    if fa:
        base["from_address"] = {"id": fa.get("id"), "address": fa.get("address"), "ens_name": fa.get("ens_name")}
    if ta:
        base["to_address"] = {"id": ta.get("id"), "address": ta.get("address"), "ens_name": ta.get("ens_name")}
    if ca:
        base["contract_address"] = {"id": ca.get("id"), "address": ca.get("address")}

    # ABI decoded view: stored vendor-specific in metadata.decoded_* if present
    md = tx_header.get("metadata") if isinstance(tx_header.get("metadata"), dict) else {}
    decoded = None
    if isinstance(md, dict):
        decoded = md.get("decoded_call") or md.get("decoded") or md.get("abi_decoded") or md.get("function")
    base["decoded_call"] = decoded

    out = {"transaction": base}

    if include_events:
        # Include all events for this tx (confirmed + others)
        def _event_repr(e):
            rr = dict(e)
            # Attach resolved address strings for convenience
            for k in ("from_address_id", "to_address_id", "contract_address_id"):
                ar = _addr_row(e.get(k))
                if ar:
                    rr[k.replace("_id", "")] = {"id": ar.get("id"), "address": ar.get("address"), "ens_name": ar.get("ens_name")}
            asr = _asset_row(e.get("asset_id"))
            if asr:
                rr["asset"] = asr
            casr = _asset_row(e.get("counter_asset_id"))
            if casr:
                rr["counter_asset"] = casr
            return rr

        # Order by log_index then event_type
        def _k(e):
            li = e.get("log_index")
            li = li if isinstance(li, int) else 10**18
            return (li, e.get("event_type") or "")
        out["events"] = [_event_repr(e) for e in sorted(tx_events, key=_k)]

    if include_transfers:
        transfers = []
        for e in tx_events:
            if not isinstance(e, dict):
                continue
            if e.get("event_type") not in ("native_transfer", "token_transfer", "nft_transfer"):
                continue
            if e.get("status") != "confirmed":
                # transfers derived from logs typically care about confirmed; keep consistent with business rules
                continue
            tr = {
                "type": e.get("event_type"),
                "block_number": e.get("block_number"),
                "block_timestamp": e.get("block_timestamp"),
                "log_index": e.get("log_index"),
                "from_address": None,
                "to_address": None,
                "contract_address": None,
                "asset": None,
                "token_id": e.get("token_id"),
                "amount_raw": e.get("amount_raw"),
                "amount_decimal": e.get("amount_decimal"),
                "value_usd": e.get("value_usd"),
                "metadata": e.get("metadata"),
            }
            fa = _addr_row(e.get("from_address_id"))
            ta = _addr_row(e.get("to_address_id"))
            ca = _addr_row(e.get("contract_address_id"))
            if fa:
                tr["from_address"] = {"id": fa.get("id"), "address": fa.get("address"), "ens_name": fa.get("ens_name")}
            if ta:
                tr["to_address"] = {"id": ta.get("id"), "address": ta.get("address"), "ens_name": ta.get("ens_name")}
            if ca:
                tr["contract_address"] = {"id": ca.get("id"), "address": ca.get("address")}
            ar = _asset_row(e.get("asset_id"))
            if ar:
                tr["asset"] = ar
            transfers.append(tr)
        # order by log_index
        transfers.sort(key=lambda r: (r.get("log_index") if isinstance(r.get("log_index"), int) else 10**18))
        out["transfers"] = transfers

    _log("ok", extra={"chain_id": chain_id})
    return out

