    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(val):
        if isinstance(val, datetime.datetime):
            return val if val.tzinfo else val.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(val, str) or not val:
            return None
        s = val.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    t0 = time.time()
    status = 200

    usage_file = "request_logs.json"
    usage = _load(usage_file)

    # Rate limit: 120/min global for this endpoint (common lightweight resolver)
    try:
        now = datetime.datetime.now(datetime.timezone.utc)
        window = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in usage[-3000:]:
            if r.get("endpoint") != "resolveaddress":
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= window:
                recent += 1
        if recent >= 120:
            status = 429
            usage.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "resolveaddress",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save(usage_file, usage)
            return _err("RATE_LIMIT", "Too many requests")
    except Exception:
        pass

    if address is None or not isinstance(address, str) or not address.strip():
        status = 400
        resp = _err("VALIDATION_ERROR", "Parameter 'address' is required and must be a non-empty string.")
        try:
            usage.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "resolveaddress",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save(usage_file, usage)
        except Exception:
            pass
        return resp

    addr = address.strip()
    if not re.fullmatch(r"0x[a-fA-F0-9]{40}", addr):
        status = 400
        resp = _err("VALIDATION_ERROR", "Invalid EVM address format. Expected 0x-prefixed 40-hex address.")
        try:
            usage.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "resolveaddress",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save(usage_file, usage)
        except Exception:
            pass
        return resp

    addr_lc = addr.lower()

    # Must resolve on EVM chains only; scan EVM chain address rows for a reverse ENS name.
    chains = _load("chains.json")
    evm_chain_ids = {c.get("id") for c in chains if c.get("chain_type") == "evm" and c.get("status") != "disabled"}

    if not evm_chain_ids:
        status = 401
        resp = _err("UNAUTHORIZED", "No available EVM chains to serve this request.")
        try:
            usage.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "resolveaddress",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save(usage_file, usage)
        except Exception:
            pass
        return resp

    addresses = _load("addresses.json")

    # Business rule: return addresses.ens_name where chain is EVM and addresses.address matches input;
    # if no ENS exists, return NOT_FOUND and do not create anything.
    match_row = None
    for a in addresses:
        if a.get("chain_id") in evm_chain_ids and a.get("address") == addr_lc:
            match_row = a
            break

    ens = None
    if match_row:
        ens = match_row.get("ens_name")

    if not ens:
        status = 404
        resp = _err("NOT_FOUND", "No ENS reverse record/domain configured for this address.")
        try:
            usage.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "resolveaddress",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save(usage_file, usage)
        except Exception:
            pass
        return resp

    body = {"address": addr_lc, "ens_name": ens}

    try:
        usage.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "resolveaddress",
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(usage_file, usage)
    except Exception:
        pass

    return body

