            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None,
            "error": error,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    if timeframe is None:
        timeframe = "24h"
    if not isinstance(timeframe, str) or timeframe != "24h":
        e = _err("VALIDATION_ERROR", "timeframe must be '24h'", field="timeframe")
        _log("error", e["error"])
        return e

    if limit is None:
        limit = 25
    if not isinstance(limit, int) or not (1 <= limit <= 100):
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100", field="limit")
        _log("error", e["error"])
        return e

    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "order must be 'asc' or 'desc'", field="order")
        _log("error", e["error"])
        return e

    def _decode_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        s = cur.strip()
        if s.startswith("offset:"):
            try:
                off = int(s.split(":", 1)[1])
                if off < 0:
                    raise ValueError()
                return off, None
            except ValueError:
                return None, _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(s.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            off = int(obj.get("offset", 0))
            if off < 0:
                raise ValueError()
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

    offset, err = _decode_cursor(cursor)
    if err:
        _log("error", err["error"])
        return err

    assets = _load("assets.json")
    if not isinstance(assets, list):
        assets = []
    events = _load("events.json")
    if not isinstance(events, list):
        events = []

    now = datetime.datetime.now(datetime.timezone.utc)
    window_start = now - datetime.timedelta(hours=24)

    def _parse_ts(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
