            continue
        if ev.get("event_type") != "nft_trade":
            continue
        ts = _parse_ts(ev.get("block_timestamp"))
        if ts is None or ts < window_start or ts > now:
            continue
        cid = ev.get("contract_address_id")
        if not isinstance(cid, str):
            continue
        v = ev.get("value_usd")
        if isinstance(v, (int, float)) and v >= 0:
            vol_by_collection[cid] = vol_by_collection.get(cid, 0.0) + float(v)
        else:
            md = ev.get("metadata")
