            wallet_row = r
            break
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    if wallet_row is None:
        # create new wallet address row
        new_id = f"addr_{int(time.time()*1000)}_{len(addresses)+1}"
        wallet_row = {
            "id": new_id,
            "chain_id": chain_id,
            "address": canonical,
            "address_kind": "wallet",
            "ens_name": None,
            "ens_resolved_address": None,
            "first_seen_at": None,
            "last_seen_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        # enforce unique(chain_id,address)
        addresses.append(wallet_row)
        _save("addresses.json", addresses)

    wallet_id = wallet_row.get("id")

    # Minimal DeFi summary inference from swap/liquidity events with protocol in metadata
    events = _load("events.json")
    assets = _load("assets.json")
    asset_by_id = {a.get("id"): a for a in assets if isinstance(a.get("id"), str)}

    protocol_value = {}  # protocol -> usd
    protocol_positions = {}  # protocol -> count
    protocol_last_active = {}  # protocol -> latest timestamp

    def _get_protocol(ev):
        md = ev.get("metadata")
        if isinstance(md, dict):
            p = md.get("protocol") or md.get("protocol_slug") or md.get("dex")
            if isinstance(p, str) and p.strip():
                return p.strip()
        return None

    def _value_usd_for_event(ev):
        v = ev.get("value_usd")
        if isinstance(v, (int, float)) and v >= 0:
            return float(v)
        # fallback: amount_decimal * latest_price_usd if asset available
        aid = ev.get("asset_id")
        amt = ev.get("amount_decimal")
        if isinstance(amt, (int, float)) and isinstance(aid, str):
            a = asset_by_id.get(aid)
            if a:
                p = a.get("latest_price_usd")
                if isinstance(p, (int, float)) and p >= 0:
                    if exclude_spam and a.get("spam_status") in ("suspected_spam", "spam"):
                        return 0.0
                    return float(amt) * float(p)
        return 0.0

    for ev in events:
        if ev.get("status") != "confirmed":
            continue
        if ev.get("chain_id") != chain_id:
            continue
        et = ev.get("event_type")
        if et not in ("swap", "liquidity_add", "liquidity_remove"):
            continue
        if ev.get("from_address_id") != wallet_id and ev.get("to_address_id") != wallet_id:
            continue
        p = _get_protocol(ev) or "unknown"
        usd = _value_usd_for_event(ev)
        protocol_value[p] = protocol_value.get(p, 0.0) + usd
        protocol_positions[p] = protocol_positions.get(p, 0) + 1
        ts = ev.get("block_timestamp")
        if isinstance(ts, str):
            prev = protocol_last_active.get(p)
            if prev is None or ts > prev:
                protocol_last_active[p] = ts

    total_usd = sum(protocol_value.values())

    protocols = []
    for p in sorted(protocol_value.keys(), key=lambda k: protocol_value.get(k, 0.0), reverse=True):
        protocols.append({
            "protocol": p,
            "estimated_usd_value": protocol_value.get(p, 0.0),
            "position_count": protocol_positions.get(p, 0),
            "last_active_at": protocol_last_active.get(p),
        })

    rewards = None
    if include_rewards:
        # No rewards table in minimal schema; return empty but present
        rewards = {"total_unclaimed_usd": 0.0, "items": []}

    resp = {
        "address": canonical,
        "chain": chain.strip(),
        "chain_id": chain_id,
        "total_usd_value": total_usd,
        "protocols": protocols,
        "rewards": rewards,
        "data_source": "inferred_from_events",
        "updated_at": now,
    }
    _log("ok", chain_id=chain_id)
    return resp

def getdefipositionsbyprotocol(address, chain, protocol, limit=None, cursor=None, exclude_spam=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getdefipositionsbyprotocol"

    def _log(status, chain_id=None, detail=None):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        rec = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "chain": chain,
            "chain_id": chain_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if detail is not None:
            rec["detail"] = detail
        logs.append(rec)
        _save("request_logs.json", logs)

    def _enforce_limits():
        limits = _load("service_limits.json")
        if not limits:
            return None
        cfg = limits[0] if isinstance(limits, list) else limits
        now = datetime.datetime.utcnow()
        logs = _load("request_logs.json")
        rpm = cfg.get("rate_limit_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            window_start = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= window_start:
                    cnt += 1
            if cnt >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        qpd = cfg.get("quota_per_day")
        if isinstance(qpd, int) and qpd >= 0:
            day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
            cnt = 0
            for r in logs:
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= day_start:
                    cnt += 1
            if cnt >= qpd:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    limerr = _enforce_limits()
    if limerr:
        _log("error", detail=limerr["error"])
        return limerr

    # Validate inputs
    if not isinstance(chain, str) or not chain.strip():
        e = _err("VALIDATION_ERROR", "chain must be a non-empty string")
        _log("error", detail=e["error"])
        return e
    if not isinstance(address, str) or not address.strip():
        e = _err("VALIDATION_ERROR", "address must be a non-empty string")
        _log("error", detail=e["error"])
        return e
    if not isinstance(protocol, str) or not protocol.strip():
        e = _err("VALIDATION_ERROR", "protocol must be a non-empty string")
        _log("error", detail=e["error"])
        return e
    protocol_q = protocol.strip()

    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        e = _err("VALIDATION_ERROR", "limit must be an integer")
        _log("error", detail=e["error"])
        return e
    if limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit out of range (1..200)")
        _log("error", detail=e["error"])
        return e

    if exclude_spam is None:
        exclude_spam = True
    if not isinstance(exclude_spam, bool):
        e = _err("VALIDATION_ERROR", "exclude_spam must be a boolean")
        _log("error", detail=e["error"])
        return e

    # Cursor format: base64 of "offset:<int>"
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            e = _err("VALIDATION_ERROR", "cursor must be a string")
            _log("error", detail=e["error"])
            return e
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                raise ValueError("bad cursor")
            offset = int(s.split(":", 1)[1])
            if offset < 0:
                raise ValueError("bad cursor")
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is malformed")
            _log("error", detail=e["error"])
            return e

    chains = _load("chains.json")
    chain_row = None
    for c in chains:
        if c.get("chain_key") == chain.strip():
            chain_row = c
            break
    if not chain_row:
        e = _err("VALIDATION_ERROR", "chain key is not recognized", chain=chain)
        _log("error", detail=e["error"])
        return e
    if chain_row.get("status") == "disabled":
        e = _err("CONFLICT", "chain is disabled", chain=chain)
        _log("error", chain_id=chain_row.get("id"), detail=e["error"])
        return e
    chain_id = chain_row.get("id")
    chain_type = chain_row.get("chain_type")

    addr_in = address.strip()
    if chain_type == "evm":
        if not re.fullmatch(r"0x[a-fA-F0-9]{40}", addr_in):
            e = _err("VALIDATION_ERROR", "invalid EVM address format")
            _log("error", chain_id=chain_id, detail=e["error"])
            return e
        canonical = addr_in.lower()
    elif chain_type == "solana":
        if not (32 <= len(addr_in) <= 44) or not re.fullmatch(r"[1-9A-HJ-NP-Za-km-z]+", addr_in):
            e = _err("VALIDATION_ERROR", "invalid Solana address format")
            _log("error", chain_id=chain_id, detail=e["error"])
            return e
        canonical = addr_in
    else:
        canonical = addr_in

    # Ensure wallet address exists (create-on-read allowed for addresses only)
    addresses = _load("addresses.json")
    wallet_row = None
    for r in addresses:
        if r.get("chain_id") == chain_id and r.get("address") == canonical:
            wallet_row = r
            break
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    if wallet_row is None:
        new_id = f"addr_{int(time.time()*1000)}_{len(addresses)+1}"
        wallet_row = {
            "id": new_id,
            "chain_id": chain_id,
            "address": canonical,
            "address_kind": "wallet",
            "ens_name": None,
            "ens_resolved_address": None,
            "first_seen_at": None,
            "last_seen_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        addresses.append(wallet_row)
        _save("addresses.json", addresses)
    wallet_id = wallet_row.get("id")

    events = _load("events.json")
    assets = _load("assets.json")
    asset_by_id = {a.get("id"): a for a in assets if isinstance(a.get("id"), str)}

    def _get_protocol(ev):
        md = ev.get("metadata")
        if isinstance(md, dict):
            p = md.get("protocol") or md.get("protocol_slug") or md.get("dex")
            if isinstance(p, str) and p.strip():
                return p.strip()
        return None

    # Build "positions" as event-derived entries for this protocol
    positions = []
    for ev in events:
        if ev.get("status") != "confirmed":
            continue
        if ev.get("chain_id") != chain_id:
            continue
        if ev.get("event_type") not in ("swap", "liquidity_add", "liquidity_remove"):
            continue
        if ev.get("from_address_id") != wallet_id and ev.get("to_address_id") != wallet_id:
            continue
        p = _get_protocol(ev) or "unknown"
        if p != protocol_q:
            continue

        aid = ev.get("asset_id")
        asset = asset_by_id.get(aid) if isinstance(aid, str) else None
        if asset is not None:
            if asset.get("status") == "hidden":
                continue
            if exclude_spam and asset.get("spam_status") in ("suspected_spam", "spam"):
                continue

        positions.append({
            "event_id": ev.get("id"),
            "protocol": p,
            "position_type": ev.get("event_type"),
            "block_number": ev.get("block_number"),
            "block_timestamp": ev.get("block_timestamp"),
            "transaction_hash": ev.get("transaction_hash"),
            "contract_address_id": ev.get("contract_address_id"),
            "asset": {
                "id": asset.get("id") if asset else aid,
                "name": asset.get("name") if asset else None,
                "symbol": asset.get("symbol") if asset else None,
                "asset_type": asset.get("asset_type") if asset else None,
                "spam_status": asset.get("spam_status") if asset else None,
            } if (asset is not None or aid is not None) else None,
            "amount_raw": ev.get("amount_raw"),
            "amount_decimal": ev.get("amount_decimal"),
            "value_usd": ev.get("value_usd"),
            "metadata": ev.get("metadata") if isinstance(ev.get("metadata"), dict) else None,
        })

    # Sort newest first
    def _ts_key(x):
        ts = x.get("block_timestamp")
        return ts if isinstance(ts, str) else ""
    positions.sort(key=_ts_key, reverse=True)

    total = len(positions)
    page = positions[offset:offset + limit]
    has_more = offset + limit < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{offset+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "address": canonical,
        "chain": chain.strip(),
        "chain_id": chain_id,
        "protocol": protocol_q,
        "result": page,
        "cursor": next_cursor,
        "has_more": has_more,
        "total": total,
        "page_size": limit,
        "data_source": "inferred_from_events",
        "updated_at": now,
    }
    _log("ok", chain_id=chain_id)
    return resp

def getdefipositionssummary(address, chain, exclude_spam=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, chain_id=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "tool": "getdefipositionssummary",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
            "chain_id": chain_id,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        # If there is any quota/rate-limit config present, enforce it.
        subs = _load("subscriptions.json")
        creds = _load("credentials.json")
        logs = _load("request_logs.json")

        # Find any combination that can serve the request (ambient auth).
        for sub in subs if isinstance(subs, list) else []:
            if isinstance(sub, dict) and sub.get("status") in (None, "active"):
                plan = sub.get("plan") or {}
                # Allow if no limits specified.
                rpm = plan.get("rate_limit_per_minute")
                daily = plan.get("quota_per_day")
                cred_id = sub.get("credential_id")
                if cred_id and isinstance(creds, list):
                    if not any(isinstance(c, dict) and c.get("id") == cred_id and c.get("status") in (None, "active") for c in creds):
                        continue
                # Enforce
                if isinstance(rpm, int) and rpm > 0:
                    cutoff = (datetime.datetime.utcnow() - datetime.timedelta(minutes=1)).replace(microsecond=0).isoformat() + "Z"
                    used = 0
                    for r in logs if isinstance(logs, list) else []:
                        if isinstance(r, dict) and r.get("timestamp") and r.get("timestamp") >= cutoff:
                            if cred_id is None or r.get("credential_id") == cred_id:
                                used += 1
                    if used >= rpm:
                        return _err("RATE_LIMIT", "Rate limit exceeded.")
                if isinstance(daily, int) and daily > 0:
                    cutoff = (datetime.datetime.utcnow() - datetime.timedelta(days=1)).replace(microsecond=0).isoformat() + "Z"
                    used = 0
                    for r in logs if isinstance(logs, list) else []:
                        if isinstance(r, dict) and r.get("timestamp") and r.get("timestamp") >= cutoff:
                            if cred_id is None or r.get("credential_id") == cred_id:
                                used += 1
                    if used >= daily:
                        return _err("QUOTA_EXCEEDED", "Quota exceeded.")
                return {"ok": True, "credential_id": cred_id}
        # If no subscription model exists, treat as allowed.
        return {"ok": True, "credential_id": None}

    # Validate inputs
    if not isinstance(address, str) or not address.strip():
        _log("error")
        return _err("VALIDATION_ERROR", "address must be a non-empty string.")
    if not isinstance(chain, str) or not chain.strip():
        _log("error")
        return _err("VALIDATION_ERROR", "chain must be a non-empty string.")
    if exclude_spam is not None and not isinstance(exclude_spam, bool):
        _log("error")
        return _err("VALIDATION_ERROR", "exclude_spam must be a boolean.")

    chains = _load("chains.json")
    chain_row = None
    for c in chains if isinstance(chains, list) else []:
        if isinstance(c, dict) and c.get("chain_key") == chain:
            chain_row = c
            break
    if not chain_row:
        _log("error")
        return _err("VALIDATION_ERROR", "chain key is not recognized.", chain=chain)
    chain_id = chain_row.get("id")
    chain_type = chain_row.get("chain_type")

    addr = address.strip()
    if chain_type == "evm":
        if not re.fullmatch(r"0x[a-fA-F0-9]{40}", addr):
            _log("error", chain_id=chain_id)
            return _err("VALIDATION_ERROR", "Invalid EVM address format for selected chain.", address=address, chain=chain)
        addr = addr.lower()
    elif chain_type == "solana":
        # Basic base58 validation (length and alphabet)
        if not re.fullmatch(r"[1-9A-HJ-NP-Za-km-z]{32,44}", addr):
            _log("error", chain_id=chain_id)
            return _err("VALIDATION_ERROR", "Invalid Solana address format for selected chain.", address=address, chain=chain)
    else:
        if not addr:
            _log("error", chain_id=chain_id)
            return _err("VALIDATION_ERROR", "Invalid address format for selected chain.", address=address, chain=chain)

    lim = _enforce_limits()
    if lim.get("error"):
        _log("error", chain_id=chain_id)
        return lim
    credential_id = lim.get("credential_id")

    # This minimal schema has no protocol/position tables. Return a concise empty-but-valid summary derived from events/assets.
    # We interpret "positions" as any token transfers/swaps involving the wallet, aggregated by "protocol" inferred from contract address.
    addresses = _load("addresses.json")
    assets = _load("assets.json")
    events = _load("events.json")

    # Create-on-read for wallet address row (business rule for wallet endpoints; apply here too as wallet-based endpoint)
    wallet_row = None
    for a in addresses if isinstance(addresses, list) else []:
        if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("address") == addr:
            wallet_row = a
            break
    if not wallet_row:
        # Create wallet address row
        new_id = f"addr_{int(time.time()*1000)}_{len(addresses)+1}"
        wallet_row = {
            "id": new_id,
            "chain_id": chain_id,
            "address": addr,
            "address_kind": "wallet",
            "ens_name": None,
            "ens_resolved_address": None,
            "first_seen_at": None,
            "last_seen_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        addresses.append(wallet_row)
        _save("addresses.json", addresses)

    wallet_id = wallet_row["id"]

    # Build quick lookup
    addr_by_id = {a.get("id"): a for a in addresses if isinstance(a, dict)}
    asset_by_id = {x.get("id"): x for x in assets if isinstance(x, dict)}

    # Filter confirmed events touching wallet on this chain
    touched = []
    for e in events if isinstance(events, list) else []:
        if not isinstance(e, dict): 
            continue
        if e.get("chain_id") != chain_id or e.get("status") != "confirmed":
            continue
        if e.get("from_address_id") == wallet_id or e.get("to_address_id") == wallet_id:
            touched.append(e)

    # Aggregate by inferred protocol: use contract_address_id (swaps/approvals/transfers) else "unknown"
    protos = {}
    for e in touched:
        et = e.get("event_type")
        if et not in ("swap", "liquidity_add", "liquidity_remove", "token_transfer", "native_transfer", "approval", "nft_trade"):
            continue
        caid = e.get("contract_address_id")
        proto_key = caid or "unknown"
        if proto_key not in protos:
            protos[proto_key] = {
                "protocol_id": proto_key if proto_key != "unknown" else None,
                "protocol_address": (addr_by_id.get(caid) or {}).get("address") if caid else None,
                "position_count": 0,
                "events_count": 0,
                "usd_value_estimate": 0.0,
                "assets": set(),
            }
        protos[proto_key]["events_count"] += 1
        if e.get("asset_id"):
            protos[proto_key]["assets"].add(e["asset_id"])
        if et in ("swap", "nft_trade", "token_transfer", "native_transfer") and isinstance(e.get("value_usd"), (int, float)):
            protos[proto_key]["usd_value_estimate"] += float(e["value_usd"])

    # Convert assets set to filtered list and approximate "position_count" as distinct assets involved.
    out = []
    for k, v in protos.items():
        asset_ids = list(v["assets"])
        if exclude_spam:
            filtered = []
            for aid in asset_ids:
                ar = asset_by_id.get(aid)
                if not ar:
                    continue
                if ar.get("spam_status") in ("spam", "suspected_spam"):
                    continue
                filtered.append(aid)
            asset_ids = filtered
        v["position_count"] = len(asset_ids)
        v["asset_ids"] = asset_ids
        v["assets"] = None
        out.append({
            "protocol_id": v["protocol_id"],
            "protocol_address": v["protocol_address"],
            "position_count": v["position_count"],
            "events_count": v["events_count"],
            "usd_value_estimate": round(v["usd_value_estimate"], 6),
            "asset_ids": v["asset_ids"],
        })

    # Sort by usd_value_estimate desc
    out.sort(key=lambda r: (r.get("usd_value_estimate") is None, -(r.get("usd_value_estimate") or 0.0)))

    resp = {
        "chain": chain,
        "address": addr,
        "exclude_spam": bool(exclude_spam) if exclude_spam is not None else False,
        "summary": {
            "protocols": out,
            "protocols_count": len(out),
            "events_scanned": len(touched),
        }
    }

    _log("ok", credential_id=credential_id, chain_id=chain_id)
    return resp

def getwalletactivechains(address, chains=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
