    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "tool": "getwalletactivechains",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        subs = _load("subscriptions.json")
        creds = _load("credentials.json")
        logs = _load("request_logs.json")
        for sub in subs if isinstance(subs, list) else []:
            if isinstance(sub, dict) and sub.get("status") in (None, "active"):
                plan = sub.get("plan") or {}
                rpm = plan.get("rate_limit_per_minute")
                daily = plan.get("quota_per_day")
                cred_id = sub.get("credential_id")
                if cred_id and isinstance(creds, list):
                    if not any(isinstance(c, dict) and c.get("id") == cred_id and c.get("status") in (None, "active") for c in creds):
                        continue
                if isinstance(rpm, int) and rpm > 0:
                    cutoff = (datetime.datetime.utcnow() - datetime.timedelta(minutes=1)).replace(microsecond=0).isoformat() + "Z"
                    used = 0
                    for r in logs if isinstance(logs, list) else []:
                        if isinstance(r, dict) and r.get("timestamp") and r.get("timestamp") >= cutoff:
                            if cred_id is None or r.get("credential_id") == cred_id:
                                used += 1
                    if used >= rpm:
                        return _err("RATE_LIMIT", "Rate limit exceeded.")
                if isinstance(daily, int) and daily > 0:
                    cutoff = (datetime.datetime.utcnow() - datetime.timedelta(days=1)).replace(microsecond=0).isoformat() + "Z"
                    used = 0
                    for r in logs if isinstance(logs, list) else []:
                        if isinstance(r, dict) and r.get("timestamp") and r.get("timestamp") >= cutoff:
                            if cred_id is None or r.get("credential_id") == cred_id:
                                used += 1
                    if used >= daily:
                        return _err("QUOTA_EXCEEDED", "Quota exceeded.")
                return {"ok": True, "credential_id": cred_id}
        return {"ok": True, "credential_id": None}

    # Validate inputs
    if not isinstance(address, str) or not address.strip():
        _log("error")
        return _err("VALIDATION_ERROR", "address must be a non-empty string.")
    if chains is not None:
        if not isinstance(chains, list) or any(not isinstance(x, str) or not x.strip() for x in chains):
            _log("error")
            return _err("VALIDATION_ERROR", "chains must be an array of non-empty strings.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error")
        return _err("VALIDATION_ERROR", "limit is out of range (1..200).")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        _log("error")
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")

    # Parse cursor (base64-encoded JSON: {"offset": int})
    offset = 0
    if cursor is not None:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
                _log("error")
                return _err("VALIDATION_ERROR", "cursor is malformed.")
            offset = obj["offset"]
        except Exception:
            _log("error")
            return _err("VALIDATION_ERROR", "cursor is malformed.")

    # Validate chain keys in chains filter
    chain_rows = _load("chains.json")
    by_key = {}
    for c in chain_rows if isinstance(chain_rows, list) else []:
        if isinstance(c, dict) and c.get("chain_key"):
            by_key[c["chain_key"]] = c
    if chains is not None:
        bad = [k for k in chains if k not in by_key]
        if bad:
            _log("error")
            return _err("VALIDATION_ERROR", "One or more chain keys are not recognized.", unknown_chains=bad)

    lims = _enforce_limits()
    if lims.get("error"):
        _log("error")
        return lims
    credential_id = lims.get("credential_id")

    # Compute active chains by scanning events and matching wallet address rows per chain (create-on-read allowed for addresses only).
    addresses = _load("addresses.json")
    events = _load("events.json")

    addr_input = address.strip()
    active = []  # list of (chain_key, chain_id, first_seen, last_seen, events_count)

    # For each candidate chain, validate address format for that chain and then find/create address row and scan.
    candidate_keys = chains if chains is not None else list(by_key.keys())

    # Build index: addresses by (chain_id, address)
    addr_index = {}
    for a in addresses if isinstance(addresses, list) else []:
        if isinstance(a, dict):
            addr_index[(a.get("chain_id"), a.get("address"))] = a

    # Ensure zero/burn address rows might exist; irrelevant here.

    def _valid_for_chain(chain_type, s):
        if chain_type == "evm":
            return bool(re.fullmatch(r"0x[a-fA-F0-9]{40}", s))
        if chain_type == "solana":
            return bool(re.fullmatch(r"[1-9A-HJ-NP-Za-km-z]{32,44}", s))
        return bool(s)

    mutated = False
    for ck in candidate_keys:
        crow = by_key.get(ck)
        if not crow:
            continue
        cid = crow.get("id")
        ctype = crow.get("chain_type")
        norm = addr_input
        if ctype == "evm":
            if not _valid_for_chain(ctype, norm):
                # Per tool: invalid address => VALIDATION_ERROR (not per-chain partial).
                _log("error", credential_id=credential_id)
                return _err("VALIDATION_ERROR", "Invalid address format for selected chain.", address=address, chain=ck)
            norm = norm.lower()
        else:
            if not _valid_for_chain(ctype, norm):
                _log("error", credential_id=credential_id)
                return _err("VALIDATION_ERROR", "Invalid address format for selected chain.", address=address, chain=ck)

        arow = addr_index.get((cid, norm))
        if not arow:
            # create-on-read wallet address row
            new_id = f"addr_{int(time.time()*1000)}_{len(addresses)+1}"
            arow = {
                "id": new_id,
                "chain_id": cid,
                "address": norm,
                "address_kind": "wallet",
                "ens_name": None,
                "ens_resolved_address": None,
                "first_seen_at": None,
                "last_seen_at": None,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            addresses.append(arow)
            addr_index[(cid, norm)] = arow
            mutated = True

        wid = arow["id"]
        first = None
        last = None
        cnt = 0
        for e in events if isinstance(events, list) else []:
            if not isinstance(e, dict): 
                continue
            if e.get("chain_id") != cid or e.get("status") != "confirmed":
                continue
            if e.get("from_address_id") == wid or e.get("to_address_id") == wid:
                ts = e.get("block_timestamp")
                if isinstance(ts, str):
                    if first is None or ts < first:
                        first = ts
                    if last is None or ts > last:
                        last = ts
                cnt += 1
        if cnt > 0:
            active.append({
                "chain": ck,
                "chain_id": cid,
                "first_seen_at": first,
                "last_seen_at": last,
                "events_count": cnt,
            })

    if mutated:
        _save("addresses.json", addresses)

    # Sort by last_seen desc then chain key
    active.sort(key=lambda r: ((r.get("last_seen_at") is None), r.get("last_seen_at") or "", r.get("chain")), reverse=True)

    total = len(active)
    page = active[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    resp = {
        "result": [
            {
                "chain": r["chain"],
                "first_seen_at": r["first_seen_at"],
                "last_seen_at": r["last_seen_at"],
                "events_count": r["events_count"],
            } for r in page
        ],
        "total": total,
        "page_size": len(page),
        "has_more": has_more,
        "cursor": next_cursor,
    }

    _log("ok", credential_id=credential_id)
    return resp

def getwalletstats(address, chain, from_date=None, to_date=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, chain_id=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "tool": "getwalletstats",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
            "chain_id": chain_id,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        subs = _load("subscriptions.json")
        creds = _load("credentials.json")
        logs = _load("request_logs.json")
        for sub in subs if isinstance(subs, list) else []:
            if isinstance(sub, dict) and sub.get("status") in (None, "active"):
                plan = sub.get("plan") or {}
                rpm = plan.get("rate_limit_per_minute")
                daily = plan.get("quota_per_day")
                cred_id = sub.get("credential_id")
                if cred_id and isinstance(creds, list):
                    if not any(isinstance(c, dict) and c.get("id") == cred_id and c.get("status") in (None, "active") for c in creds):
                        continue
                if isinstance(rpm, int) and rpm > 0:
                    cutoff = (datetime.datetime.utcnow() - datetime.timedelta(minutes=1)).replace(microsecond=0).isoformat() + "Z"
                    used = 0
                    for r in logs if isinstance(logs, list) else []:
                        if isinstance(r, dict) and r.get("timestamp") and r.get("timestamp") >= cutoff:
                            if cred_id is None or r.get("credential_id") == cred_id:
                                used += 1
                    if used >= rpm:
                        return _err("RATE_LIMIT", "Rate limit exceeded.")
                if isinstance(daily, int) and daily > 0:
                    cutoff = (datetime.datetime.utcnow() - datetime.timedelta(days=1)).replace(microsecond=0).isoformat() + "Z"
                    used = 0
                    for r in logs if isinstance(logs, list) else []:
                        if isinstance(r, dict) and r.get("timestamp") and r.get("timestamp") >= cutoff:
                            if cred_id is None or r.get("credential_id") == cred_id:
                                used += 1
                    if used >= daily:
                        return _err("QUOTA_EXCEEDED", "Quota exceeded.")
                return {"ok": True, "credential_id": cred_id}
        return {"ok": True, "credential_id": None}

    def _parse_rfc3339(s):
        # Accept Z or offset; normalize to aware datetime in UTC
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1])
                return dt.replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                # treat naive as UTC
                return dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    # Validate
    if not isinstance(address, str) or not address.strip():
        _log("error")
        return _err("VALIDATION_ERROR", "address must be a non-empty string.")
    if not isinstance(chain, str) or not chain.strip():
        _log("error")
        return _err("VALIDATION_ERROR", "chain must be a non-empty string.")

    chain_rows = _load("chains.json")
    chain_row = None
    for c in chain_rows if isinstance(chain_rows, list) else []:
        if isinstance(c, dict) and c.get("chain_key") == chain:
            chain_row = c
            break
    if not chain_row:
        _log("error")
        return _err("VALIDATION_ERROR", "chain key is not recognized.", chain=chain)
    chain_id = chain_row.get("id")
    chain_type = chain_row.get("chain_type")

    addr = address.strip()
    if chain_type == "evm":
        if not re.fullmatch(r"0x[a-fA-F0-9]{40}", addr):
            _log("error", chain_id=chain_id)
            return _err("VALIDATION_ERROR", "Invalid EVM address format for selected chain.", address=address, chain=chain)
        addr = addr.lower()
    elif chain_type == "solana":
        if not re.fullmatch(r"[1-9A-HJ-NP-Za-km-z]{32,44}", addr):
            _log("error", chain_id=chain_id)
            return _err("VALIDATION_ERROR", "Invalid Solana address format for selected chain.", address=address, chain=chain)

    fdt = _parse_rfc3339(from_date)
    if from_date is not None and fdt is None:
        _log("error", chain_id=chain_id)
        return _err("VALIDATION_ERROR", "from_date must be a valid RFC3339 date-time.")
    tdt = _parse_rfc3339(to_date)
    if to_date is not None and tdt is None:
        _log("error", chain_id=chain_id)
        return _err("VALIDATION_ERROR", "to_date must be a valid RFC3339 date-time.")
    if fdt is not None and tdt is not None and fdt > tdt:
        _log("error", chain_id=chain_id)
        return _err("VALIDATION_ERROR", "from_date must be <= to_date.")

    lims = _enforce_limits()
    if lims.get("error"):
        _log("error", chain_id=chain_id)
        return lims
    credential_id = lims.get("credential_id")

    addresses = _load("addresses.json")
    events = _load("events.json")

    # create-on-read wallet row
    wallet_row = None
    for a in addresses if isinstance(addresses, list) else []:
        if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("address") == addr:
            wallet_row = a
            break
    if not wallet_row:
        new_id = f"addr_{int(time.time()*1000)}_{len(addresses)+1}"
        wallet_row = {
            "id": new_id,
            "chain_id": chain_id,
            "address": addr,
            "address_kind": "wallet",
            "ens_name": None,
            "ens_resolved_address": None,
            "first_seen_at": None,
            "last_seen_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        addresses.append(wallet_row)
        _save("addresses.json", addresses)

    wid = wallet_row["id"]

    def _in_window(ts_str):
        if not isinstance(ts_str, str):
            return False
        # compare via datetime for correctness across formats
        dt = _parse_rfc3339(ts_str if ts_str.endswith("Z") or "+" in ts_str or "-" in ts_str[10:] else ts_str + "Z")
        if dt is None:
            return False
        if fdt is not None and dt < fdt:
            return False
        if tdt is not None and dt >= tdt:
            return False
        return True

    # Stats over confirmed events only
    tx_hashes = set()
    events_in = 0
    first_ts = None
    last_ts = None
    approvals = 0
    token_transfers = 0
    native_transfers = 0
    nft_transfers = 0
    swaps = 0

    for e in events if isinstance(events, list) else []:
        if not isinstance(e, dict):
            continue
        if e.get("chain_id") != chain_id or e.get("status") != "confirmed":
            continue
        if e.get("from_address_id") != wid and e.get("to_address_id") != wid:
            continue
        ts = e.get("block_timestamp")
        if fdt is not None or tdt is not None:
            if not _in_window(ts):
                continue

        events_in += 1
        if isinstance(ts, str):
            if first_ts is None or ts < first_ts:
                first_ts = ts
            if last_ts is None or ts > last_ts:
                last_ts = ts

        th = e.get("transaction_hash")
        if isinstance(th, str) and th:
            tx_hashes.add(th)

        et = e.get("event_type")
        if et == "approval":
            approvals += 1
        elif et == "token_transfer":
            token_transfers += 1
        elif et == "native_transfer":
            native_transfers += 1
        elif et == "nft_transfer":
            nft_transfers += 1
        elif et == "swap":
            swaps += 1

    resp = {
        "chain": chain,
        "address": addr,
        "window": {
            "from_date": from_date,
            "to_date": to_date,
        },
        "stats": {
            "transactions_count": len(tx_hashes),
            "events_count": events_in,
            "first_activity_at": first_ts,
            "last_activity_at": last_ts,
            "approvals_count": approvals,
            "token_transfers_count": token_transfers,
            "native_transfers_count": native_transfers,
            "nft_transfers_count": nft_transfers,
            "swaps_count": swaps,
        }
    }

    _log("ok", credential_id=credential_id, chain_id=chain_id)
    return resp

