        else:
            # If we don't have an address row id, we cannot match this contract reliably.
            # Fall back: if assets contain nft_collection with matching contract row, use that id; else no match.
            continue

        tid = e.get("token_id")
        if token_id is not None and tid != token_id:
            continue
        if tid is None:
            continue

        total_transfers += 1
        ts = e.get("block_timestamp") or ""
        bn = e.get("block_number")
        to_id = e.get("to_address_id")

        prev = latest_by_token.get(tid)
        # Compare by timestamp then block_number then keep latest
        if prev is None:
            latest_by_token[tid] = (ts, bn, to_id)
        else:
            pts, pbn, _ = prev
            newer = False
            if isinstance(ts, str) and isinstance(pts, str):
                if ts > pts:
                    newer = True
                elif ts == pts:
                    if isinstance(bn, int) and isinstance(pbn, int) and bn > pbn:
                        newer = True
            else:
                if isinstance(bn, int) and isinstance(pbn, int) and bn > pbn:
                    newer = True
            if newer:
                latest_by_token[tid] = (ts, bn, to_id)

    total_tokens = len(latest_by_token)

    owners = {}
    burned = 0
    for tid, (_ts, _bn, to_id) in latest_by_token.items():
        if to_id in burn_ids:
            burned += 1
            continue
        if to_id is None:
            continue
        owners[to_id] = owners.get(to_id, 0) + 1

    total_owners = len(owners)

    # Optionally attach collection asset metadata if present
    collection_asset = None
    if contract_address_id is not None:
        for a in assets if isinstance(assets, list) else []:
            if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("asset_type") == "nft_collection" and a.get("contract_address_id") == contract_address_id:
                collection_asset = a
                break

    resp = {
        "chain": chain,
        "address": ca,
        "token_id": token_id,
        "stats": {
            "total_transfers": total_transfers,
            "total_tokens": total_tokens,
            "total_owners": total_owners,
            "burned_tokens": burned,
        },
        "collection": None if not collection_asset else {
            "asset_id": collection_asset.get("id"),
            "name": collection_asset.get("name"),
            "symbol": collection_asset.get("symbol"),
            "logo_url": collection_asset.get("logo_url"),
            "floor_price_native": collection_asset.get("floor_price_native"),
            "floor_price_usd": collection_asset.get("floor_price_usd"),
            "floor_price_refreshed_at": collection_asset.get("floor_price_refreshed_at"),
            "metadata": collection_asset.get("metadata"),
        }
    }

    _log("ok", credential_id=credential_id, chain_id=chain_id)
    return resp

def getnfthistoricalfloorpricebycontract(chain_id, contract_address_id, start_at=None, end_at=None, interval=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getnfthistoricalfloorpricebycontract"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"mor_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "chain_id": chain_id,
            "credential_id": None,
            "error": error,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    if not isinstance(chain_id, str) or not re.fullmatch(r"^mor_chain_[0-9A-Z]{3,}$", chain_id):
        e = _err("VALIDATION_ERROR", "chain_id must match ^mor_chain_[0-9A-Z]{3,}$", field="chain_id")
        _log("error", e["error"])
        return e
    if not isinstance(contract_address_id, str) or not re.fullmatch(r"^mor_addr_[0-9A-Z]{3,}$", contract_address_id):
        e = _err("VALIDATION_ERROR", "contract_address_id must match ^mor_addr_[0-9A-Z]{3,}$", field="contract_address_id")
        _log("error", e["error"])
        return e

    if interval is None:
        interval = "1d"
    if not isinstance(interval, str) or interval not in ("15m", "30m", "1h", "4h", "1d"):
        e = _err("VALIDATION_ERROR", "interval must be one of 15m,30m,1h,4h,1d", field="interval")
        _log("error", e["error"])
        return e

    if limit is None:
        limit = 200
    if not isinstance(limit, int) or not (1 <= limit <= 2000):
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 2000", field="limit")
        _log("error", e["error"])
        return e

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string", field=field)
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string", field=field)

    start_dt, err = _parse_dt(start_at, "start_at")
    if err:
        _log("error", err["error"])
        return err
    end_dt, err = _parse_dt(end_at, "end_at")
    if err:
        _log("error", err["error"])
        return err
    if start_dt and end_dt and start_dt > end_dt:
        e = _err("VALIDATION_ERROR", "start_at cannot be after end_at", field="start_at")
        _log("error", e["error"])
        return e

    def _decode_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        s = cur.strip()
        if s.startswith("offset:"):
            try:
                off = int(s.split(":", 1)[1])
                if off < 0:
                    raise ValueError()
                return off, None
            except ValueError:
                return None, _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(s.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            off = int(obj.get("offset", 0))
            if off < 0:
                raise ValueError()
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

    offset, err = _decode_cursor(cursor)
    if err:
        _log("error", err["error"])
        return err

    # Ensure collection exists
    assets = _load("assets.json")
    if not isinstance(assets, list):
        assets = []
    col = next((a for a in assets if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("asset_type") == "nft_collection" and a.get("contract_address_id") == contract_address_id), None)
    if not col:
        e = _err("NOT_FOUND", "NFT collection not found for chain_id/contract_address_id", chain_id=chain_id, contract_address_id=contract_address_id)
        _log("error", e["error"])
        return e

    events = _load("events.json")
    if not isinstance(events, list):
        events = []

    # interval seconds
    step = {"15m": 900, "30m": 1800, "1h": 3600, "4h": 14400, "1d": 86400}[interval]

    def _parse_ts(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    # Build buckets from confirmed nft_trade events; use metadata.floor_price_* or infer from value_usd if provided
    points_map = {}  # bucket_start_epoch -> {"timestamp":..., "floor_price_usd":..., "floor_price_native":...}
    for ev in events:
        if not isinstance(ev, dict):
            continue
        if ev.get("chain_id") != chain_id or ev.get("status") != "confirmed" or ev.get("event_type") != "nft_trade":
            continue
        if ev.get("contract_address_id") != contract_address_id:
            continue
        ts = _parse_ts(ev.get("block_timestamp"))
        if ts is None:
            continue
        if start_dt and ts < start_dt:
            continue
        if end_dt and ts > end_dt:
            continue
        epoch = int(ts.timestamp())
        bucket = epoch - (epoch % step)
        md = ev.get("metadata") if isinstance(ev.get("metadata"), dict) else {}
        fp_usd = md.get("floor_price_usd")
        fp_nat = md.get("floor_price_native")
        if not isinstance(fp_usd, (int, float)):
            fp_usd = md.get("floor_usd")
        if not isinstance(fp_nat, (int, float)):
            fp_nat = md.get("floor_native")

        # if still not available, skip (historical derived only from available observations)
        if not isinstance(fp_usd, (int, float)) and not isinstance(fp_nat, (int, float)):
            continue
        cur = points_map.get(bucket)
        # take min floor within bucket if multiple
        def _better(newv, oldv):
            if newv is None:
                return oldv
            if oldv is None:
                return newv
            return newv if float(newv) < float(oldv) else oldv
        if cur is None:
            points_map[bucket] = {
                "timestamp": datetime.datetime.fromtimestamp(bucket, tz=datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
                "floor_price_usd": float(fp_usd) if isinstance(fp_usd, (int, float)) else None,
                "floor_price_native": float(fp_nat) if isinstance(fp_nat, (int, float)) else None,
            }
        else:
            cur["floor_price_usd"] = _better(float(fp_usd) if isinstance(fp_usd, (int, float)) else None, cur.get("floor_price_usd"))
            cur["floor_price_native"] = _better(float(fp_nat) if isinstance(fp_nat, (int, float)) else None, cur.get("floor_price_native"))

    points = list(points_map.values())
    points.sort(key=lambda p: p.get("timestamp") or "")

    total = len(points)
    page = points[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_off}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    resp = {
        "chain_id": chain_id,
        "contract_address_id": contract_address_id,
        "interval": interval,
        "result": page,
        "total": total,
        "page_size": limit,
        "cursor": next_cursor,
        "has_more": has_more,
    }
    _log("ok", meta={"returned": len(page), "total": total, "offset": offset, "interval": interval})
    return resp

def getfilteredtokens(chain_id=None, asset_type=None, spam_status=None, status=None, q=None, min_liquidity_usd=None, max_liquidity_usd=None, min_market_cap_usd=None, max_market_cap_usd=None, min_price_usd=None, max_price_usd=None, sort_by=None, sort_dir=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_s, latency_ms, detail=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": f"mor_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
                "endpoint": endpoint,
                "status": status_s,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
                "detail": detail
            })
            _save("request_logs.json", logs)

    def _enc_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _dec_cursor(s):
        try:
            if not isinstance(s, str) or not s:
                return None
            pad = "=" * ((4 - (len(s) % 4)) % 4)
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _num(v, field):
        if v is None:
            return None, None
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", f"{field} must be a number.", field=field)
        if not isinstance(v, (int, float)):
            return None, _err("VALIDATION_ERROR", f"{field} must be a number.", field=field)
        return float(v), None

    t0 = time.time()
    endpoint = "getfilteredtokens"

    # Validate chain_id if provided
    if chain_id is not None:
        if not isinstance(chain_id, str) or not re.match(r"^mor_chain_[0-9A-Z]{3,}$", chain_id):
            resp = _err("VALIDATION_ERROR", "Invalid chain_id format.", field="chain_id")
            _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
            return resp

    if asset_type is not None and asset_type not in ("native", "erc20"):
        resp = _err("VALIDATION_ERROR", "Invalid asset_type.", field="asset_type", allowed=["native", "erc20"])
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
        return resp

    if spam_status is not None and spam_status not in ("unknown", "not_spam", "suspected_spam", "spam"):
        resp = _err("VALIDATION_ERROR", "Invalid spam_status.", field="spam_status")
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
        return resp

    if status is not None and status not in ("active", "deprecated", "hidden"):
        resp = _err("VALIDATION_ERROR", "Invalid status.", field="status")
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
        return resp

    if q is not None and not isinstance(q, str):
        resp = _err("VALIDATION_ERROR", "q must be a string.", field="q")
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
        return resp

    min_liq, e = _num(min_liquidity_usd, "min_liquidity_usd")
    if e:
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=e["error"])
        return e
    max_liq, e = _num(max_liquidity_usd, "max_liquidity_usd")
    if e:
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=e["error"])
        return e
    min_mc, e = _num(min_market_cap_usd, "min_market_cap_usd")
    if e:
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=e["error"])
        return e
    max_mc, e = _num(max_market_cap_usd, "max_market_cap_usd")
    if e:
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=e["error"])
        return e
    min_p, e = _num(min_price_usd, "min_price_usd")
    if e:
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=e["error"])
        return e
    max_p, e = _num(max_price_usd, "max_price_usd")
    if e:
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=e["error"])
        return e

    if sort_by is None:
        sort_by = "market_cap_usd"
    if sort_by not in ("market_cap_usd", "liquidity_usd", "latest_price_usd", "created_at", "updated_at"):
        resp = _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by")
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
        return resp

    if sort_dir is None:
        sort_dir = "desc"
    if sort_dir not in ("asc", "desc"):
        resp = _err("VALIDATION_ERROR", "Invalid sort_dir.", field="sort_dir")
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
        return resp

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        resp = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
        return resp

    cur = None
    if cursor is not None:
        cur = _dec_cursor(cursor)
        if cur is None:
            resp = _err("VALIDATION_ERROR", "Invalid cursor.")
            _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
            return resp
        if cur.get("sort_by") != sort_by or cur.get("sort_dir") != sort_dir:
            resp = _err("VALIDATION_ERROR", "Cursor does not match sorting parameters.")
            _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
            return resp
        if chain_id is not None and cur.get("chain_id") not in (None, chain_id):
            resp = _err("VALIDATION_ERROR", "Cursor does not match chain_id.")
            _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
            return resp

    # Validate chain exists if provided
    if chain_id is not None:
        chains = _load("chains.json")
        if not any(isinstance(c, dict) and c.get("id") == chain_id for c in chains):
            resp = _err("NOT_FOUND", "Chain not found.", chain_id=chain_id)
            _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
            return resp

    assets = _load("assets.json")
    rows = []
    qn = q.strip().lower() if isinstance(q, str) and q.strip() else None

    for a in assets:
        if not isinstance(a, dict):
            continue
        at = a.get("asset_type")
        if at not in ("native", "erc20"):
            continue
        if chain_id is not None and a.get("chain_id") != chain_id:
            continue
        if asset_type is not None and at != asset_type:
            continue
        if spam_status is not None and a.get("spam_status") != spam_status:
            continue
        if status is not None:
            if a.get("status") != status:
                continue
        else:
            # Business rule: do not return hidden by default
            if a.get("status") == "hidden":
                continue

        if qn is not None:
            name = a.get("name") or ""
            sym = a.get("symbol") or ""
            if not (isinstance(name, str) and qn in name.lower()) and not (isinstance(sym, str) and qn in sym.lower()):
                continue

        liq = a.get("liquidity_usd")
        mc = a.get("market_cap_usd")
        pr = a.get("latest_price_usd")

        if min_liq is not None and (liq is None or not isinstance(liq, (int, float)) or float(liq) < min_liq):
            continue
        if max_liq is not None and (liq is None or not isinstance(liq, (int, float)) or float(liq) > max_liq):
            continue
        if min_mc is not None and (mc is None or not isinstance(mc, (int, float)) or float(mc) < min_mc):
            continue
        if max_mc is not None and (mc is None or not isinstance(mc, (int, float)) or float(mc) > max_mc):
            continue
        if min_p is not None and (pr is None or not isinstance(pr, (int, float)) or float(pr) < min_p):
            continue
        if max_p is not None and (pr is None or not isinstance(pr, (int, float)) or float(pr) > max_p):
            continue

        rows.append(a)

    # Sorting
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _sort_key(a):
        v = a.get(sort_by)
        if sort_by in ("created_at", "updated_at"):
            dt = _parse_dt(v)
            return dt or datetime.datetime(1970, 1, 1)
        if isinstance(v, (int, float)):
            return float(v)
        # Treat missing metric as -inf for desc, +inf for asc to push to end.
        return float("-inf") if sort_dir == "desc" else float("inf")

    reverse = (sort_dir == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    # Cursor paging by offset (opaque)
    offset = 0
    if cur and isinstance(cur.get("offset"), int) and cur["offset"] >= 0:
        offset = cur["offset"]

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total

    next_cursor = None
    if has_more:
        next_cursor = _enc_cursor({
            "chain_id": chain_id,
            "sort_by": sort_by,
            "sort_dir": sort_dir,
            "offset": next_offset
        })

    out = {
        "result": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "cursor": next_cursor
    }

    latency = int((time.time() - t0) * 1000)
    _log(endpoint, "ok", latency)
    return out

