            if not isinstance(s, str) or not s:
                return None
            pad = "=" * ((4 - (len(s) % 4)) % 4)
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _num(v, field):
        if v is None:
            return None, None
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", f"{field} must be a number.", field=field)
        if not isinstance(v, (int, float)):
            return None, _err("VALIDATION_ERROR", f"{field} must be a number.", field=field)
        return float(v), None

    t0 = time.time()
    endpoint = "getrisingliquiditytokens"

    if not isinstance(chain_id, str) or not re.match(r"^mor_chain_[0-9A-Z]{3,}$", chain_id):
        resp = _err("VALIDATION_ERROR", "Invalid chain_id format.", field="chain_id")
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
        return resp

    if window is None:
        window = "24h"
    if window not in ("1h", "4h", "24h", "7d"):
        resp = _err("VALIDATION_ERROR", "Invalid window.", field="window", allowed=["1h", "4h", "24h", "7d"])
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
        return resp

    min_liq, e = _num(min_liquidity_usd, "min_liquidity_usd")
    if e:
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=e["error"])
        return e

    if spam_status is not None and spam_status not in ("unknown", "not_spam", "suspected_spam", "spam"):
        resp = _err("VALIDATION_ERROR", "Invalid spam_status.", field="spam_status")
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
        return resp

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        resp = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
        return resp

    cur = None
    if cursor is not None:
        cur = _dec_cursor(cursor)
        if cur is None:
            resp = _err("VALIDATION_ERROR", "Invalid cursor.")
            _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
            return resp
        if cur.get("chain_id") != chain_id or cur.get("window") != window:
            resp = _err("VALIDATION_ERROR", "Cursor does not match request parameters.")
            _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
            return resp

    chains = _load("chains.json")
    if not any(isinstance(c, dict) and c.get("id") == chain_id for c in chains):
        resp = _err("NOT_FOUND", "Chain not found.", chain_id=chain_id)
        _log(endpoint, "error", int((time.time() - t0) * 1000), detail=resp["error"])
        return resp

    # Window seconds
    win_sec = {"1h": 3600, "4h": 14400, "24h": 86400, "7d": 604800}[window]
    now = datetime.datetime.utcnow()
    cutoff = now - datetime.timedelta(seconds=win_sec)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    assets = _load("assets.json")
    # Candidate tokens: erc20 only (liquidity metric relevant); exclude hidden by default
    candidates = []
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("chain_id") != chain_id:
            continue
        if a.get("asset_type") != "erc20":
            continue
        if a.get("status") == "hidden":
            continue
        if spam_status is not None and a.get("spam_status") != spam_status:
            continue
        cur_liq = a.get("liquidity_usd")
        if min_liq is not None:
            if cur_liq is None or not isinstance(cur_liq, (int, float)) or float(cur_liq) < min_liq:
                continue
        candidates.append(a)

    events = _load("events.json")

    # Compute liquidity change using swap/liquidity_add/liquidity_remove events referencing asset_id.
    # Use metadata.liquidity_usd snapshot if present; else approximate by summing liquidity deltas metadata.liquidity_delta_usd.
    liquidity_change = {}  # asset_id -> delta
    latest_liq = {}        # asset_id -> (ts, liq_snapshot)
    base_liq = {}          # asset_id -> (ts, liq_snapshot)

    for ev in events:
        if not isinstance(ev, dict):
            continue
        if ev.get("chain_id") != chain_id:
            continue
        if ev.get("status") != "confirmed":
            continue
        if ev.get("event_type") not in ("swap", "liquidity_add", "liquidity_remove"):
            continue
        aid = ev.get("asset_id")
        if not isinstance(aid, str):
            continue
        bt = _parse_dt(ev.get("block_timestamp"))
        if bt is None:
            continue
        md = ev.get("metadata") if isinstance(ev.get("metadata"), dict) else {}

        # snapshots
        snap = md.get("liquidity_usd") if isinstance(md, dict) else None
        if isinstance(snap, (int, float)):
            if bt >= cutoff:
                prev = latest_liq.get(aid)
                if prev is None or bt > prev[0]:
                    latest_liq[aid] = (bt, float(snap))
            # baseline: most recent snapshot at/before cutoff
            if bt <= cutoff:
                prevb = base_liq.get(aid)
                if prevb is None or bt > prevb[0]:
                    base_liq[aid] = (bt, float(snap))
            continue

        # deltas
        delta = md.get("liquidity_delta_usd") if isinstance(md, dict) else None
        if isinstance(delta, (int, float)) and bt >= cutoff:
            liquidity_change[aid] = liquidity_change.get(aid, 0.0) + float(delta)

    # For assets with both baseline & latest snapshot: delta = latest - baseline. Otherwise: delta from deltas.
    results = []
    for a in candidates:
        aid = a.get("id")
        cur_liq = a.get("liquidity_usd")
        delta = None
        if aid in latest_liq and aid in base_liq:
            delta = latest_liq[aid][1] - base_liq[aid][1]
        elif aid in liquidity_change:
            delta = liquidity_change[aid]
        else:
            delta = 0.0

        # Only rising (strictly > 0)
        if delta is None or delta <= 0:
            continue

        results.append({
            "asset": a,
            "liquidity_change_usd": delta,
            "current_liquidity_usd": float(cur_liq) if isinstance(cur_liq, (int, float)) else None,
            "window": window
        })

    # Sort by largest increase desc
    results.sort(key=lambda r: (r.get("liquidity_change_usd") if isinstance(r.get("liquidity_change_usd"), (int, float)) else float("-inf")), reverse=True)

    offset = 0
    if cur and isinstance(cur.get("offset"), int) and cur["offset"] >= 0:
        offset = cur["offset"]

    total = len(results)
    page = results[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _enc_cursor({"chain_id": chain_id, "window": window, "offset": next_offset}) if has_more else None

    out = {
        "chain_id": chain_id,
        "window": window,
        "result": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "cursor": next_cursor
    }

    latency = int((time.time() - t0) * 1000)
    _log(endpoint, "ok", latency)
    return out

def getbuyingpressuretokens(chain_id, window=None, min_value_usd=None, min_tx_count=None, spam_status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    status_code = "OK"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(float(v))
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str):
            return None
        if cur == "":
            return 0
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            off = obj.get("offset", 0)
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        payload = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    def _log_call(endpoint, status, latency_ms, meta=None):
        # Best-effort request logging if a collection file exists; do not fail the call if logging fails.
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                if not isinstance(rows, list):
                    rows = []
                rows.append({
                    "id": f"mor_req_{int(time.time()*1000)}",
                    "endpoint": endpoint,
                    "status": status,
                    "latency_ms": latency_ms,
                    "timestamp": _now_iso(),
                    "meta": meta or {}
                })
                _save(fname, rows)
                break

    # Validate inputs
    if not isinstance(chain_id, str) or not re.match(r"^mor_chain_[0-9A-Z]{3,}$", chain_id):
        status_code = "VALIDATION_ERROR"
        resp = _err("VALIDATION_ERROR", "Invalid chain_id format.")
        _log_call("getbuyingpressuretokens", status_code, int((time.time() - _t0) * 1000), {"chain_id": chain_id})
        return resp

    if window is None:
        window = "1h"
    if not isinstance(window, str) or window not in ("15m", "1h", "4h", "24h"):
        status_code = "VALIDATION_ERROR"
        resp = _err("VALIDATION_ERROR", "Invalid window. Must be one of: 15m, 1h, 4h, 24h.")
        _log_call("getbuyingpressuretokens", status_code, int((time.time() - _t0) * 1000), {"chain_id": chain_id, "window": window})
        return resp

    if min_value_usd is not None and not isinstance(min_value_usd, (int, float)):
        status_code = "VALIDATION_ERROR"
        resp = _err("VALIDATION_ERROR", "min_value_usd must be a number.")
        _log_call("getbuyingpressuretokens", status_code, int((time.time() - _t0) * 1000), {"chain_id": chain_id})
        return resp
    if isinstance(min_value_usd, bool):
        status_code = "VALIDATION_ERROR"
        resp = _err("VALIDATION_ERROR", "min_value_usd must be a number.")
        _log_call("getbuyingpressuretokens", status_code, int((time.time() - _t0) * 1000), {"chain_id": chain_id})
        return resp
    if min_value_usd is not None and float(min_value_usd) < 0:
        status_code = "VALIDATION_ERROR"
        resp = _err("VALIDATION_ERROR", "min_value_usd must be >= 0.")
        _log_call("getbuyingpressuretokens", status_code, int((time.time() - _t0) * 1000), {"chain_id": chain_id})
        return resp

    if min_tx_count is not None:
        if not isinstance(min_tx_count, int) or isinstance(min_tx_count, bool) or min_tx_count < 0:
            status_code = "VALIDATION_ERROR"
            resp = _err("VALIDATION_ERROR", "min_tx_count must be an integer >= 0.")
            _log_call("getbuyingpressuretokens", status_code, int((time.time() - _t0) * 1000), {"chain_id": chain_id})
            return resp

    if spam_status is not None:
        if not isinstance(spam_status, str) or spam_status not in ("unknown", "not_spam", "suspected_spam", "spam"):
            status_code = "VALIDATION_ERROR"
            resp = _err("VALIDATION_ERROR", "Invalid spam_status.")
            _log_call("getbuyingpressuretokens", status_code, int((time.time() - _t0) * 1000), {"chain_id": chain_id})
            return resp

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 200:
        status_code = "VALIDATION_ERROR"
        resp = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        _log_call("getbuyingpressuretokens", status_code, int((time.time() - _t0) * 1000), {"chain_id": chain_id, "limit": limit})
        return resp

    off = _decode_cursor(cursor)
    if off is None:
        status_code = "VALIDATION_ERROR"
        resp = _err("VALIDATION_ERROR", "Invalid cursor.")
        _log_call("getbuyingpressuretokens", status_code, int((time.time() - _t0) * 1000), {"chain_id": chain_id})
        return resp

    chains = _load("chains.json")
    chain_row = next((c for c in chains if isinstance(c, dict) and c.get("id") == chain_id), None)
    if chain_row is None:
        status_code = "NOT_FOUND"
        resp = _err("NOT_FOUND", "Chain not found.", chain_id=chain_id)
        _log_call("getbuyingpressuretokens", status_code, int((time.time() - _t0) * 1000), {"chain_id": chain_id})
        return resp
    if chain_row.get("status") == "disabled":
        status_code = "NOT_FOUND"
        resp = _err("NOT_FOUND", "Chain is disabled.", chain_id=chain_id)
        _log_call("getbuyingpressuretokens", status_code, int((time.time() - _t0) * 1000), {"chain_id": chain_id})
        return resp

    # Compute window start
    sec = {"15m": 15 * 60, "1h": 60 * 60, "4h": 4 * 60 * 60, "24h": 24 * 60 * 60}[window]
    now = datetime.datetime.utcnow()
    start = now - datetime.timedelta(seconds=sec)

    assets = _load("assets.json")
    events = _load("events.json")
    addr_rows = _load("addresses.json")

    # candidate ERC20 tokens on chain, excluding hidden
    token_rows = []
    token_by_id = {}
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("chain_id") != chain_id:
            continue
        if a.get("asset_type") != "erc20":
            continue
        if a.get("status") == "hidden":
            continue
        if spam_status is not None and a.get("spam_status") != spam_status:
            continue
        aid = a.get("id")
        if isinstance(aid, str):
            token_rows.append(a)
            token_by_id[aid] = a

    token_ids = set(token_by_id.keys())

    # Derive "buy-side" activity from swaps: treat value_usd where asset_id is present as buy-side for that token.
    # (Minimal schema; vendor semantics are richer, but we only have events rows.)
    agg = {}  # asset_id -> {"value_usd":..., "txs": set()}
    for e in events:
        if not isinstance(e, dict):
            continue
        if e.get("chain_id") != chain_id:
            continue
        if e.get("status") != "confirmed":
            continue
        if e.get("event_type") != "swap":
            continue
        ts = _parse_dt(e.get("block_timestamp"))
        if ts is None or ts < start or ts > now + datetime.timedelta(minutes=5):
            continue
        aid = e.get("asset_id")
        if aid not in token_ids:
            continue
        v = e.get("value_usd")
        if v is None:
            continue
        if not isinstance(v, (int, float)) or isinstance(v, bool) or v < 0:
            continue
        txh = e.get("transaction_hash") or e.get("id")
        if aid not in agg:
            agg[aid] = {"value_usd": 0.0, "txs": set(), "event_count": 0}
        agg[aid]["value_usd"] += float(v)
        if isinstance(txh, str):
            agg[aid]["txs"].add(txh)
        agg[aid]["event_count"] += 1

    min_v = float(min_value_usd) if min_value_usd is not None else None
    min_c = int(min_tx_count) if min_tx_count is not None else None

    rows = []
    for aid, m in agg.items():
        tx_count = len(m["txs"]) if m["txs"] else m["event_count"]
        if min_v is not None and m["value_usd"] < min_v:
            continue
        if min_c is not None and tx_count < min_c:
            continue
        a = token_by_id.get(aid)
        if not a:
            continue
        rows.append({
            "asset": a,
            "buy_value_usd": m["value_usd"],
            "tx_count": tx_count,
            "window": window
        })

    rows.sort(key=lambda r: (r.get("buy_value_usd", 0.0), r.get("tx_count", 0)), reverse=True)

    total = len(rows)
    page = rows[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    resp = {
        "result": page,
        "cursor": next_cursor,
        "has_more": has_more,
        "total": total,
        "chain_id": chain_id,
        "window": window,
        "generated_at": _now_iso()
    }
    _log_call("getbuyingpressuretokens", status_code, int((time.time() - _t0) * 1000),
              {"chain_id": chain_id, "window": window, "returned": len(page), "total": total})
    return resp

