        resp = _err("VALIDATION_ERROR", "Invalid cursor.")
        _log_call("getexperiencedbuyerstokens", status_code, int((time.time() - _t0) * 1000), {"chain_id": chain_id})
        return resp

    chains = _load("chains.json")
    chain_row = next((c for c in chains if isinstance(c, dict) and c.get("id") == chain_id), None)
    if chain_row is None:
        status_code = "NOT_FOUND"
        resp = _err("NOT_FOUND", "Chain not found.", chain_id=chain_id)
        _log_call("getexperiencedbuyerstokens", status_code, int((time.time() - _t0) * 1000), {"chain_id": chain_id})
        return resp
    if chain_row.get("status") == "disabled":
        status_code = "NOT_FOUND"
        resp = _err("NOT_FOUND", "Chain is disabled.", chain_id=chain_id)
        _log_call("getexperiencedbuyerstokens", status_code, int((time.time() - _t0) * 1000), {"chain_id": chain_id})
        return resp

    sec = {"1h": 60 * 60, "4h": 4 * 60 * 60, "24h": 24 * 60 * 60, "7d": 7 * 24 * 60 * 60}[window]
    now = datetime.datetime.utcnow()
    start = now - datetime.timedelta(seconds=sec)

    assets = _load("assets.json")
    events = _load("events.json")
    addresses = _load("addresses.json")

    token_by_id = {}
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("chain_id") != chain_id or a.get("asset_type") != "erc20" or a.get("status") == "hidden":
            continue
        if spam_status is not None and a.get("spam_status") != spam_status:
            continue
        aid = a.get("id")
        if isinstance(aid, str):
            token_by_id[aid] = a
    token_ids = set(token_by_id.keys())

    # Define "experienced buyers" as wallet addresses that participated in >= N swaps in the window.
    # N is chosen as a fixed heuristic given minimal schema.
    EXP_SWAP_MIN = 5

    buyer_swap_counts = {}
    buyer_swap_value = {}
    # For attribution to token: count value_usd for swaps where asset_id is token and to_address_id is buyer.
    token_exp_value = {}
    token_exp_buyers = {}

    for e in events:
        if not isinstance(e, dict):
            continue
        if e.get("chain_id") != chain_id or e.get("status") != "confirmed" or e.get("event_type") != "swap":
            continue
        ts = _parse_dt(e.get("block_timestamp"))
        if ts is None or ts < start or ts > now + datetime.timedelta(minutes=5):
            continue
        buyer = e.get("to_address_id")
        if not isinstance(buyer, str):
            continue
        buyer_swap_counts[buyer] = buyer_swap_counts.get(buyer, 0) + 1
        v = e.get("value_usd")
        if isinstance(v, (int, float)) and not isinstance(v, bool) and v >= 0:
            buyer_swap_value[buyer] = buyer_swap_value.get(buyer, 0.0) + float(v)

    experienced = {b for b, c in buyer_swap_counts.items() if c >= EXP_SWAP_MIN}

    for e in events:
        if not isinstance(e, dict):
            continue
        if e.get("chain_id") != chain_id or e.get("status") != "confirmed" or e.get("event_type") != "swap":
            continue
        ts = _parse_dt(e.get("block_timestamp"))
        if ts is None or ts < start or ts > now + datetime.timedelta(minutes=5):
            continue
        buyer = e.get("to_address_id")
        if buyer not in experienced:
            continue
        aid = e.get("asset_id")
        if aid not in token_ids:
            continue
        v = e.get("value_usd")
        if not isinstance(v, (int, float)) or isinstance(v, bool) or v < 0:
            continue
        token_exp_value[aid] = token_exp_value.get(aid, 0.0) + float(v)
        token_exp_buyers.setdefault(aid, set()).add(buyer)

    min_v = float(min_value_usd) if min_value_usd is not None else None
    min_b = int(min_buyer_count) if min_buyer_count is not None else None

    out = []
    for aid, val in token_exp_value.items():
        buyers = token_exp_buyers.get(aid, set())
        buyer_count = len(buyers)
        if min_v is not None and val < min_v:
            continue
        if min_b is not None and buyer_count < min_b:
            continue
        out.append({
            "asset": token_by_id[aid],
            "experienced_buy_value_usd": val,
            "experienced_buyer_count": buyer_count,
            "window": window
        })

    out.sort(key=lambda r: (r.get("experienced_buy_value_usd", 0.0), r.get("experienced_buyer_count", 0)), reverse=True)

    total = len(out)
    page = out[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    resp = {
        "result": page,
        "cursor": next_cursor,
        "has_more": has_more,
        "total": total,
        "chain_id": chain_id,
        "window": window,
        "generated_at": _now_iso()
    }
    _log_call("getexperiencedbuyerstokens", status_code, int((time.time() - _t0) * 1000),
              {"chain_id": chain_id, "window": window, "returned": len(page), "total": total})
    return resp

