            continue
        if ss == "suspected_spam" and not include_suspected_spam:
            continue
        if min_liq is not None:
            liq = a.get("liquidity_usd")
            if liq is None or not isinstance(liq, (int, float)) or isinstance(liq, bool) or float(liq) < min_liq:
                continue
        aid = a.get("id")
        if isinstance(aid, str):
            token_rows[aid] = a

    token_ids = set(token_rows.keys())

    stats = {}  # aid -> {swap_count, total_value, max_value}
    for e in events:
        if not isinstance(e, dict):
