        if prev_last_ts is None or ts > prev_last_ts:
            last_price[aid] = (ts, p)
        # first observed within window
        if ts >= cutoff_iso:
            prev_first_ts, prev_first_p = first_price.get(aid, (None, None))
            if prev_first_ts is None or ts < prev_first_ts:
                first_price[aid] = (ts, p)
            v = ev.get("value_usd")
            if v is None:
                v = md.get("volume_usd")
