        pct = None
        if isinstance(aid, str) and aid in first_price and aid in last_price:
            fp = first_price[aid][1]
            lp = last_price[aid][1]
            if fp and fp > 0:
                pct = (lp - fp) / fp * 100.0
        if pct is None:
            md = a.get("metadata") if isinstance(a.get("metadata"), dict) else {}
            key = f"price_change_percent_{days}d"
            if key in md:
                try:
                    pct = float(md.get(key))
