                    pct = None
            if pct is None and "price_change_percent" in md:
                try:
                    pct = float(md.get("price_change_percent"))
                except Exception:
                    pct = None

        # If still unknown, skip from gainers list (can't rank)
        if pct is None:
            continue

        row = dict(a)
        row["price_change_percent"] = pct
        row["volume_usd"] = float(volume_usd.get(aid, 0.0)) if isinstance(aid, str) else 0.0
        rows.append(row)

    def _key(r):
        v = r.get(sortBy)
        if v is None:
            return (1, 0.0)
        try:
            return (0, float(v))
        except Exception:
            return (0, 0.0)

    reverse = (sortDirection == "desc")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
