        v = r.get(sortBy)
        if v is None:
            return (1, 0.0)
        try:
            return (0, float(v))
        except Exception:
            return (0, 0.0)

    reverse = (sortDirection == "desc")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "result": page,
        "page": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }
    _log("ok", {"returned": len(page), "total": total, "days": days})
    return resp

