        except Exception:
            pass

    # --- validate inputs ---
    if chain is None or wallet_address is None or days is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "chain, wallet_address, and days are required")
    if not isinstance(chain, str) or not re.match(r"^mor_chain_[A-Za-z0-9]+$", chain):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid chain format")
    if not isinstance(wallet_address, str) or not re.match(r"^0x[a-fA-F0-9]{40}$", wallet_address):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid wallet_address format")
    if not isinstance(days, int) or days < 1 or days > 3650:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid days; must be integer between 1 and 3650")

    # --- resolve chain ---
    chains = _load("chains.json")
    if not isinstance(chains, list): chains = []
    chain_row = None
    for c in chains:
        if isinstance(c, dict) and c.get("chain_key") == chain:
            chain_row = c
            break
    if not chain_row:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Chain not found")
    if chain_row.get("status") == "disabled":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Chain is not available")

    chain_id = chain_row.get("id")

    # --- ensure wallet address row exists (create-on-read allowed for addresses only) ---
    addresses = _load("addresses.json")
    if not isinstance(addresses, list): addresses = []
    waddr = wallet_address.lower()
    wallet_row = None
    for a in addresses:
        if isinstance(a, dict) and a.get("chain_id") == chain_id and (a.get("address") or "").lower() == waddr:
            wallet_row = a
            break
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    if wallet_row is None:
        # id convention: addr_<24hex>
        new_id = "addr_" + hashlib.sha256(f"{chain_id}|{waddr}|{time.time_ns()}".encode()).hexdigest()[:24]
        wallet_row = {
            "id": new_id,
            "chain_id": chain_id,
            "address": waddr,
            "address_kind": "wallet",
            "ens_name": None,
            "ens_resolved_address": None,
            "first_seen_at": None,
            "last_seen_at": None,
            "status": "active",
            "created_at": now_iso,
            "updated_at": now_iso
        }
        addresses.append(wallet_row)
        try:
            _save("addresses.json", addresses)
        except Exception:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Failed to persist wallet address record")

    wallet_id = wallet_row.get("id")

    # --- load assets and events ---
    events = _load("events.json")
    if not isinstance(events, list): events = []
    assets = _load("assets.json")
    if not isinstance(assets, list): assets = []

    # --- time window ---
    now_dt = datetime.datetime.utcnow()
    start_dt = now_dt - datetime.timedelta(days=days)

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            # accept ISO with Z
            if s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # --- confirmed wallet-involving events within window (token_transfer/native_transfer/swap) ---
    # NOTE: Minimal schema doesn't define trade direction/price; we approximate profitability:
    # - volume_usd: sum(value_usd) of swaps involving wallet (as from/to)
    # - realized_pnl_usd: sum(value_usd) for swaps where wallet is 'to' minus where wallet is 'from' (heuristic)
    # - unrealized_pnl_usd: 0 (no holdings valuation source in schema beyond assets.latest_price_usd; per-token handled in other endpoint)
    # This is an approximation consistent with datastore limitations.
    realized = 0.0
    volume = 0.0
    swap_count = 0
    transfer_count = 0

    for e in events:
        if not isinstance(e, dict): 
            continue
        if e.get("chain_id") != chain_id:
            continue
        if e.get("status") != "confirmed":
            continue
        ts = _parse_dt(e.get("block_timestamp"))
        if ts is None or ts < start_dt or ts > now_dt:
            continue
        et = e.get("event_type")
        if et not in ("swap", "token_transfer", "native_transfer"):
            continue
        if e.get("from_address_id") != wallet_id and e.get("to_address_id") != wallet_id:
            continue

        v = e.get("value_usd")
        vnum = float(v) if isinstance(v, (int, float)) else None
        if et == "swap":
            swap_count += 1
            if vnum is not None and vnum >= 0:
                volume += vnum
                # heuristic: treat incoming swap value as profit, outgoing as cost
                if e.get("to_address_id") == wallet_id:
                    realized += vnum
                elif e.get("from_address_id") == wallet_id:
                    realized -= vnum
        else:
            transfer_count += 1

    unrealized = 0.0
    total = realized + unrealized
    roi = None
    if volume > 0:
        roi = (total / volume) * 100.0

    resp = {
        "chain": chain,
        "wallet_address": waddr,
        "days": days,
        "window": {
            "from": start_dt.replace(microsecond=0).isoformat() + "Z",
            "to": now_dt.replace(microsecond=0).isoformat() + "Z"
        },
        "totals": {
            "realized_pnl_usd": realized,
            "unrealized_pnl_usd": unrealized,
            "total_pnl_usd": total,
            "roi_percent": roi,
            "volume_usd": volume,
            "swap_count": swap_count,
            "transfer_count": transfer_count
        }
    }

    _log("ok")
    return resp

def getwalletprofitability(chain, wallet_address, days, token_addresses=None, limit=None, cursor=None, sortBy=None, sortDirection=None, **_extra):
