        return _err("VALIDATION_ERROR", "Invalid wallet_address format")
    if not isinstance(days, int) or days < 1 or days > 3650:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid days; must be integer between 1 and 3650")

    if token_addresses is not None:
        if not isinstance(token_addresses, list):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "token_addresses must be an array of addresses")
        for ta in token_addresses:
            if not isinstance(ta, str) or not re.match(r"^0x[a-fA-F0-9]{40}$", ta):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid token address in token_addresses")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid limit; must be integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sortBy is None:
        sortBy = "total_pnl_usd"
    if sortBy not in ("realized_pnl_usd", "unrealized_pnl_usd", "total_pnl_usd", "roi_percent", "volume_usd"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sortBy")
    if sortDirection is None:
        sortDirection = "desc"
    if sortDirection not in ("asc", "desc"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sortDirection")

    # cursor decode => offset
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
            if not raw.startswith("off:"):
                raise ValueError("bad cursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError("bad offset")
        except Exception:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # resolve chain
    chains = _load("chains.json")
    if not isinstance(chains, list): chains = []
    chain_row = next((c for c in chains if isinstance(c, dict) and c.get("chain_key") == chain), None)
    if not chain_row:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Chain not found")
    if chain_row.get("status") == "disabled":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Chain is not available")
    chain_id = chain_row.get("id")

    # ensure wallet address row exists
    addresses = _load("addresses.json")
    if not isinstance(addresses, list): addresses = []
    waddr = wallet_address.lower()
    wallet_row = None
    for a in addresses:
        if isinstance(a, dict) and a.get("chain_id") == chain_id and (a.get("address") or "").lower() == waddr:
            wallet_row = a
            break
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    if wallet_row is None:
        new_id = "addr_" + hashlib.sha256(f"{chain_id}|{waddr}|{time.time_ns()}".encode()).hexdigest()[:24]
        wallet_row = {
            "id": new_id,
            "chain_id": chain_id,
            "address": waddr,
            "address_kind": "wallet",
            "ens_name": None,
            "ens_resolved_address": None,
            "first_seen_at": None,
            "last_seen_at": None,
            "status": "active",
            "created_at": now_iso,
            "updated_at": now_iso
        }
        addresses.append(wallet_row)
        try:
            _save("addresses.json", addresses)
        except Exception:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Failed to persist wallet address record")
    wallet_id = wallet_row.get("id")

    assets = _load("assets.json")
    if not isinstance(assets, list): assets = []
    events = _load("events.json")
    if not isinstance(events, list): events = []

    # build token contract address filter => contract_address_id set
    contract_addr_to_id = {}
    for a in addresses:
        if isinstance(a, dict) and a.get("chain_id") == chain_id and isinstance(a.get("address"), str):
            contract_addr_to_id[a["address"].lower()] = a.get("id")

    wanted_contract_ids = None
    if token_addresses:
        wanted_contract_ids = set()
        for ta in token_addresses:
            cid = contract_addr_to_id.get(ta.lower())
            if cid:
                wanted_contract_ids.add(cid)
            else:
                # token contract not in datastore => no rows, but not an error
                wanted_contract_ids.add("__missing__:" + ta.lower())

    # map asset_id -> asset row (erc20 only)
    erc20_assets = {}
    for asr in assets:
        if not isinstance(asr, dict): 
            continue
        if asr.get("chain_id") != chain_id:
            continue
        if asr.get("asset_type") != "erc20":
            continue
        if asr.get("status") == "hidden":
            continue
        caid = asr.get("contract_address_id")
        if wanted_contract_ids is not None and caid not in wanted_contract_ids:
            continue
        erc20_assets[asr.get("id")] = asr

    # time window
    now_dt = datetime.datetime.utcnow()
    start_dt = now_dt - datetime.timedelta(days=days)

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # compute per-token net flows and volume_usd from confirmed token_transfer involving wallet
    # realized/unrealized approximations:
    # - realized_pnl_usd: 0 (no cost-basis/trade info in minimal schema for token transfers)
    # - unrealized_pnl_usd: net_amount * latest_price_usd (using asset.latest_price_usd)
    # - total_pnl_usd = realized + unrealized
    stats = {}  # asset_id -> dict
    for e in events:
        if not isinstance(e, dict): 
            continue
        if e.get("chain_id") != chain_id or e.get("status") != "confirmed":
            continue
        if e.get("event_type") != "token_transfer":
            continue
        ts = _parse_dt(e.get("block_timestamp"))
        if ts is None or ts < start_dt or ts > now_dt:
            continue
        if e.get("from_address_id") != wallet_id and e.get("to_address_id") != wallet_id:
            continue
        aid = e.get("asset_id")
        if aid not in erc20_assets:
            continue
        amount = e.get("amount_decimal")
        if not isinstance(amount, (int, float)):
            # try parse raw if present; without decimals we can't humanize; skip
            continue
        v = e.get("value_usd")
        vnum = float(v) if isinstance(v, (int, float)) else None

        s = stats.get(aid)
        if s is None:
            s = {
                "asset_id": aid,
                "net_amount": 0.0,
                "in_amount": 0.0,
                "out_amount": 0.0,
                "volume_usd": 0.0,
                "transfer_count": 0
            }
            stats[aid] = s
        s["transfer_count"] += 1
        if vnum is not None and vnum >= 0:
            s["volume_usd"] += vnum
        if e.get("to_address_id") == wallet_id:
            s["net_amount"] += float(amount)
            s["in_amount"] += float(amount)
        elif e.get("from_address_id") == wallet_id:
            s["net_amount"] -= float(amount)
            s["out_amount"] += float(amount)

    # build response rows with pricing
    rows = []
    for aid, s in stats.items():
        asr = erc20_assets.get(aid)
        price = asr.get("latest_price_usd")
        price_num = float(price) if isinstance(price, (int, float)) else None
        unrealized = (s["net_amount"] * price_num) if price_num is not None else None
        realized = 0.0
        total = (realized + unrealized) if unrealized is not None else None
        roi = None
        if s["volume_usd"] > 0 and total is not None:
            roi = (total / s["volume_usd"]) * 100.0

        # include contract address string if available
        contract_address = None
        caid = asr.get("contract_address_id")
        if caid:
            ar = next((x for x in addresses if isinstance(x, dict) and x.get("id") == caid), None)
            if ar and isinstance(ar.get("address"), str):
                contract_address = ar["address"]

        rows.append({
            "chain": chain,
            "wallet_address": waddr,
            "token_address": contract_address,
            "asset_id": aid,
            "name": asr.get("name"),
            "symbol": asr.get("symbol"),
            "decimals": asr.get("decimals"),
            "latest_price_usd": price_num,
            "metrics": {
                "realized_pnl_usd": realized,
                "unrealized_pnl_usd": unrealized if unrealized is not None else 0.0,
                "total_pnl_usd": total if total is not None else 0.0,
                "roi_percent": roi,
                "volume_usd": s["volume_usd"],
                "net_amount": s["net_amount"],
                "in_amount": s["in_amount"],
                "out_amount": s["out_amount"],
                "transfer_count": s["transfer_count"]
            }
        })

    # sorting
    def _k(r):
        m = r.get("metrics", {})
        v = m.get(sortBy)
        if v is None:
            return float("-inf") if sortDirection == "desc" else float("inf")
        try:
            return float(v)
        except Exception:
            return float("-inf") if sortDirection == "desc" else float("inf")

    rows.sort(key=_k, reverse=(sortDirection == "desc"))

    total_count = len(rows)
    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total_count
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"off:{next_off}".encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "result": page,
        "pagination": {
            "total": total_count,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        },
        "sort": {"sortBy": sortBy, "sortDirection": sortDirection},
        "window": {
            "days": days,
            "from": (now_dt - datetime.timedelta(days=days)).replace(microsecond=0).isoformat() + "Z",
            "to": now_dt.replace(microsecond=0).isoformat() + "Z"
        }
    }

    _log("ok")
    return resp

