    if chain_row.get("status") == "disabled":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Chain is not available")
    chain_id = chain_row.get("id")

    addresses = _load("addresses.json")
    if not isinstance(addresses, list): addresses = []
    addr_row = next((a for a in addresses if isinstance(a, dict) and a.get("chain_id") == chain_id and (a.get("address") or "").lower() == token_address.lower()), None)
    if not addr_row:
        # token contract address doesn't exist in store => empty results, not error
        resp = {
            "result": [],
            "pagination": {"total": 0, "limit": limit, "cursor": cursor, "next_cursor": None, "has_more": False},
            "sort": {"sortBy": sortBy, "sortDirection": sortDirection},
            "token_address": token_address.lower(),
            "chain": chain
        }
        _log("ok")
        return resp
    contract_address_id = addr_row.get("id")

    assets = _load("assets.json")
    if not isinstance(assets, list): assets = []
    token_asset = next((a for a in assets if isinstance(a, dict) and a.get("chain_id") == chain_id and a.get("asset_type") == "erc20" and a.get("contract_address_id") == contract_address_id and a.get("status") != "hidden"), None)
    if not token_asset:
        resp = {
            "result": [],
            "pagination": {"total": 0, "limit": limit, "cursor": cursor, "next_cursor": None, "has_more": False},
            "sort": {"sortBy": sortBy, "sortDirection": sortDirection},
            "token_address": token_address.lower(),
            "chain": chain
        }
        _log("ok")
        return resp
    token_asset_id = token_asset.get("id")

    events = _load("events.json")
    if not isinstance(events, list): events = []
    entity_addresses = _load("entity_addresses.json")
    if not isinstance(entity_addresses, list): entity_addresses = []
    entities = _load("entities.json")
    if not isinstance(entities, list): entities = []

    # label map: address_id -> best entity/name
    ent_by_id = {e.get("id"): e for e in entities if isinstance(e, dict)}
    label_by_addr_id = {}
    for ea in entity_addresses:
        if not isinstance(ea, dict): 
            continue
        aid = ea.get("address_id")
        eid = ea.get("entity_id")
        ent = ent_by_id.get(eid)
        if not aid or not ent:
            continue
        # choose the highest confidence label if multiple
        conf = ea.get("confidence")
        conf = float(conf) if isinstance(conf, (int, float)) else 0.0
        existing = label_by_addr_id.get(aid)
        if existing is None or conf > existing.get("_confidence", -1):
            label_by_addr_id[aid] = {
                "_confidence": conf,
                "entity_id": eid,
                "entity_name": ent.get("name"),
                "entity_category": ent.get("category"),
                "label": ea.get("label")
            }

    now_dt = datetime.datetime.utcnow()
    start_dt = now_dt - datetime.timedelta(days=days)

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # compute per wallet net_amount and "unrealized pnl" from net * latest_price_usd
    # realized pnl not computable from transfer-only data; set 0. total = unrealized
    price = token_asset.get("latest_price_usd")
    price_num = float(price) if isinstance(price, (int, float)) else None

    per_wallet = {}  # wallet_address_id -> {net_amount, volume_usd, transfers}
    for e in events:
        if not isinstance(e, dict): 
            continue
        if e.get("chain_id") != chain_id or e.get("status") != "confirmed":
            continue
        if e.get("event_type") != "token_transfer":
            continue
        if e.get("asset_id") != token_asset_id:
            continue
        ts = _parse_dt(e.get("block_timestamp"))
        if ts is None or ts < start_dt or ts > now_dt:
            continue

        amt = e.get("amount_decimal")
        if not isinstance(amt, (int, float)):
            continue
        v = e.get("value_usd")
        vnum = float(v) if isinstance(v, (int, float)) else None

        fa = e.get("from_address_id")
        ta = e.get("to_address_id")

        # from wallet decreases holdings
        if fa:
            s = per_wallet.get(fa)
            if s is None:
                s = {"wallet_address_id": fa, "net_amount": 0.0, "volume_usd": 0.0, "transfer_count": 0}
                per_wallet[fa] = s
            s["net_amount"] -= float(amt)
            s["transfer_count"] += 1
            if vnum is not None and vnum >= 0:
                s["volume_usd"] += vnum

        # to wallet increases holdings
        if ta:
            s = per_wallet.get(ta)
            if s is None:
                s = {"wallet_address_id": ta, "net_amount": 0.0, "volume_usd": 0.0, "transfer_count": 0}
                per_wallet[ta] = s
            s["net_amount"] += float(amt)
            s["transfer_count"] += 1
            if vnum is not None and vnum >= 0:
                s["volume_usd"] += vnum

    # build rows
    addr_by_id = {a.get("id"): a for a in addresses if isinstance(a, dict)}
    rows = []
    for wid, s in per_wallet.items():
        ar = addr_by_id.get(wid)
        # only consider wallets
        if not ar or ar.get("address_kind") != "wallet":
            continue
        waddr = ar.get("address")
        if not isinstance(waddr, str):
            continue
        realized = 0.0
        unrealized = (s["net_amount"] * price_num) if price_num is not None else 0.0
        total = realized + unrealized
        roi = None
        if s["volume_usd"] > 0:
            roi = (total / s["volume_usd"]) * 100.0

        lbl = label_by_addr_id.get(wid)
        rows.append({
            "chain": chain,
            "token_address": token_address.lower(),
            "wallet_address": waddr,
            "wallet_address_id": wid,
            "label": (lbl.get("label") if lbl else None),
            "entity": ({
                "id": lbl.get("entity_id"),
                "name": lbl.get("entity_name"),
                "category": lbl.get("entity_category"),
                "confidence": lbl.get("_confidence")
            } if lbl else None),
            "metrics": {
                "realized_pnl_usd": realized,
                "total_pnl_usd": total,
                "roi_percent": roi,
                "volume_usd": s["volume_usd"],
                "net_amount": s["net_amount"],
                "transfer_count": s["transfer_count"]
            }
        })

    # sorting
    def _k(r):
        m = r.get("metrics", {})
        v = m.get(sortBy)
        if v is None:
            return float("-inf") if sortDirection == "desc" else float("inf")
        try:
            return float(v)
        except Exception:
            return float("-inf") if sortDirection == "desc" else float("inf")

    rows.sort(key=_k, reverse=(sortDirection == "desc"))

    total_count = len(rows)
    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total_count
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"off:{next_off}".encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "result": page,
        "pagination": {
            "total": total_count,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        },
        "sort": {"sortBy": sortBy, "sortDirection": sortDirection},
        "window": {
            "days": days,
            "from": start_dt.replace(microsecond=0).isoformat() + "Z",
            "to": now_dt.replace(microsecond=0).isoformat() + "Z"
        }
    }

    _log("ok")
    return resp

def searchtokens(query, chains=None, limit=None, cursor=None, sortBy=None, sortDirection=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "searchtokens"

    def _log(status, error_code=None):
        try:
            logs = _load("request_log.json")
            if not isinstance(logs, list): logs = []
            now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            logs.append({
                "id": "req_" + hashlib.sha256(f"{endpoint}|{now}|{time.time_ns()}".encode()).hexdigest()[:24],
                "ts": now,
                "endpoint": endpoint,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("request_log.json", logs)
        except Exception:
            pass

    if query is None or not isinstance(query, str) or len(query.strip()) < 1:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    q = query.strip()

    if chains is not None:
        if not isinstance(chains, list):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "chains must be an array of chain IDs")
        for ch in chains:
            if not isinstance(ch, str) or not re.match(r"^mor_chain_[A-Za-z0-9]+$", ch):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid chain ID in chains")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid limit; must be integer between 1 and 100")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sortBy is None:
        sortBy = "market_cap_usd"
    if sortBy not in ("market_cap_usd", "liquidity_usd", "fdv_usd", "latest_price_usd", "volume_usd"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sortBy")
    if sortDirection is None:
        sortDirection = "desc"
    if sortDirection not in ("asc", "desc"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sortDirection")

    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
            if not raw.startswith("off:"):
                raise ValueError("bad cursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError("bad offset")
        except Exception:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    chain_rows = _load("chains.json")
    if not isinstance(chain_rows, list): chain_rows = []
    chainkey_to_id = {c.get("chain_key"): c.get("id") for c in chain_rows if isinstance(c, dict)}
    chainid_to_key = {c.get("id"): c.get("chain_key") for c in chain_rows if isinstance(c, dict)}

    allowed_chain_ids = None
    if chains:
        allowed_chain_ids = set()
        for ch in chains:
            cid = chainkey_to_id.get(ch)
            if not cid:
                _log("error", "NOT_FOUND")
                return _err("NOT_FOUND", f"Chain not found: {ch}")
            # only allow active/degraded
            crow = next((c for c in chain_rows if isinstance(c, dict) and c.get("id") == cid), None)
            if crow and crow.get("status") == "disabled":
                _log("error", "UNAUTHORIZED")
                return _err("UNAUTHORIZED", f"Chain is not available: {ch}")
            allowed_chain_ids.add(cid)

    assets = _load("assets.json")
    if not isinstance(assets, list): assets = []
    addresses = _load("addresses.json")
    if not isinstance(addresses, list): addresses = []
    addr_by_id = {a.get("id"): a for a in addresses if isinstance(a, dict)}

    q_low = q.lower()
    is_addr = bool(re.match(r"^0x[a-fA-F0-9]{40}$", q))

    # Search over ERC20 and pair assets; do not return hidden.
    # volume_usd is not stored in schema; compute as 0.
    results = []
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("status") == "hidden":
            continue
        if a.get("asset_type") not in ("erc20", "pair"):
            continue
        if allowed_chain_ids is not None and a.get("chain_id") not in allowed_chain_ids:
            continue

        caid = a.get("contract_address_id")
        contract_addr = None
        if caid and caid in addr_by_id:
            contract_addr = addr_by_id[caid].get("address")

        name = a.get("name") or ""
        sym = a.get("symbol") or ""
        match = False
        if is_addr and contract_addr and isinstance(contract_addr, str) and contract_addr.lower() == q_low:
            match = True
        else:
            if isinstance(contract_addr, str) and q_low in contract_addr.lower():
                match = True
            elif isinstance(name, str) and q_low in name.lower():
                match = True
            elif isinstance(sym, str) and q_low in sym.lower():
                match = True

        if not match:
            continue

        chain_key = chainid_to_key.get(a.get("chain_id"))
        results.append({
            "asset_id": a.get("id"),
            "chain": chain_key,
            "asset_type": a.get("asset_type"),
            "token_address": contract_addr,
            "name": a.get("name"),
            "symbol": a.get("symbol"),
            "decimals": a.get("decimals"),
            "logo_url": a.get("logo_url"),
            "spam_status": a.get("spam_status"),
            "metrics": {
                "market_cap_usd": a.get("market_cap_usd"),
                "liquidity_usd": a.get("liquidity_usd"),
                "fdv_usd": a.get("fdv_usd"),
                "latest_price_usd": a.get("latest_price_usd"),
                "volume_usd": 0.0
            }
        })

    def _sort_key(r):
        v = (r.get("metrics", {}) or {}).get(sortBy)
        if v is None:
            return float("-inf") if sortDirection == "desc" else float("inf")
        try:
            return float(v)
        except Exception:
            return float("-inf") if sortDirection == "desc" else float("inf")

    # Secondary tie-break: symbol/name for deterministic order
    results.sort(key=lambda r: (_sort_key(r), (r.get("symbol") or ""), (r.get("name") or ""), (r.get("token_address") or "")),
                 reverse=(sortDirection == "desc"))

    total_count = len(results)
    page = results[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total_count
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"off:{next_off}".encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "result": page,
        "pagination": {
            "total": total_count,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        },
        "sort": {"sortBy": sortBy, "sortDirection": sortDirection},
        "query": q,
        "chains": chains
    }

    _log("ok")
    return resp

def searchentities(q, chainId=None, category=None, addressKind=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, status, latency_ms, credential=None, meta=None):
        fn = _ensure_logs()
        logs = _load(fn)
        logs.append(
            {
                "id": f"mor_req_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": endpoint,
                "status": status,
                "latency_ms": int(latency_ms),
                "timestamp": _now(),
                "credential": credential,
                "meta": meta or {},
            }
        )
        _save(fn, logs)

    def _parse_cursor(c):
        if not c:
            return {"entities": 0, "addresses": 0, "categories": 0}
        if not isinstance(c, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return None
            out = {"entities": 0, "addresses": 0, "categories": 0}
            for k in out:
                v = obj.get(k, 0)
                if isinstance(v, int) and v >= 0:
                    out[k] = v
                else:
                    return None
            return out
        except Exception:
            return None

    def _make_cursor(state):
        raw = json.dumps(state, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    t0 = time.time()
    endpoint = "searchentities"

    # Validate
    if not isinstance(q, str) or not q.strip():
        _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000, meta={"q": q})
        return _err("VALIDATION_ERROR", "q is required and must be a non-empty string")

    if chainId is not None:
        if not isinstance(chainId, str) or not re.match(r"^mor_chain_[0-9A-Z]+$", chainId):
            _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "chainId must match ^mor_chain_[0-9A-Z]+$")

    allowed_categories = {
        "exchange",
        "cex",
        "dex",
        "market_maker",
        "protocol",
        "bridge",
        "lending",
        "nft_marketplace",
        "staking",
        "custodian",
        "fund",
        "team",
        "whale",
        "scam",
        "mixer",
        "unknown",
    }
    if category is not None:
        if not isinstance(category, str) or category not in allowed_categories:
            _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "category is invalid")

    allowed_address_kinds = {"wallet", "contract", "pair", "program", "other"}
    if addressKind is not None:
        if not isinstance(addressKind, str) or addressKind not in allowed_address_kinds:
            _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "addressKind is invalid")

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

    cur = _parse_cursor(cursor)
    if cursor is not None and cur is None:
        _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "cursor is invalid")

    # Load data
    entities = _load("entities.json")
    entity_addresses = _load("entity_addresses.json")
    addresses = _load("addresses.json")
    chains = _load("chains.json")

    chain_row = None
    chain_id = None
    if chainId is not None:
        for c in chains:
            if c.get("id") == chainId:
                chain_row = c
                chain_id = c.get("id")
                break
        if chain_row is None:
            _log(endpoint, "NOT_FOUND", (time.time() - t0) * 1000)
            return _err("NOT_FOUND", "chainId not found")

    qn = q.strip().lower()

    # Indexes
    ent_by_id = {e.get("id"): e for e in entities if isinstance(e, dict) and isinstance(e.get("id"), str)}
    addr_by_id = {a.get("id"): a for a in addresses if isinstance(a, dict) and isinstance(a.get("id"), str)}
    eas_by_ent = {}
    eas_by_addr = {}
    for ea in entity_addresses:
        if not isinstance(ea, dict):
            continue
        eid = ea.get("entity_id")
        aid = ea.get("address_id")
        if isinstance(eid, str) and isinstance(aid, str):
            eas_by_ent.setdefault(eid, []).append(ea)
            eas_by_addr.setdefault(aid, []).append(ea)

    def _addr_matches(a):
        if not isinstance(a, dict):
            return False
        if chain_id is not None and a.get("chain_id") != chain_id:
            return False
        if addressKind is not None and a.get("address_kind") != addressKind:
            return False
        # search across raw address + ENS name
        addr = (a.get("address") or "")
        ens = (a.get("ens_name") or "")
        return (isinstance(addr, str) and qn in addr.lower()) or (isinstance(ens, str) and qn in ens.lower())

    def _entity_matches(e):
        if not isinstance(e, dict):
            return False
        if category is not None and e.get("category") != category:
            return False
        name = (e.get("name") or "")
        desc = (e.get("description") or "")
        return (isinstance(name, str) and qn in name.lower()) or (isinstance(desc, str) and qn in desc.lower())

    def _label_matches(ea):
        if not isinstance(ea, dict):
            return False
        lab = (ea.get("label") or "")
        return isinstance(lab, str) and qn in lab.lower()

    # Build candidates
    matched_entity_ids = set()
    matched_address_ids = set()
    matched_categories = set()

    # Entity name/description match
    for e in entities:
        if _entity_matches(e):
            eid = e.get("id")
            if isinstance(eid, str):
                matched_entity_ids.add(eid)
                cat = e.get("category")
                if isinstance(cat, str):
                    matched_categories.add(cat)

    # Address matches (raw/ens), map to entities via entity_addresses
    for a in addresses:
        if _addr_matches(a):
            aid = a.get("id")
            if isinstance(aid, str):
                matched_address_ids.add(aid)
                for ea in eas_by_addr.get(aid, []):
                    eid = ea.get("entity_id")
                    if isinstance(eid, str) and eid in ent_by_id:
                        e = ent_by_id[eid]
                        if category is None or e.get("category") == category:
                            matched_entity_ids.add(eid)
                            cat = e.get("category")
                            if isinstance(cat, str):
                                matched_categories.add(cat)

    # Label matches (entity_addresses.label), optionally chain-scoped via address join
    for ea in entity_addresses:
        if _label_matches(ea):
            aid = ea.get("address_id")
            if isinstance(aid, str) and aid in addr_by_id:
                a = addr_by_id[aid]
                if chain_id is not None and a.get("chain_id") != chain_id:
                    continue
                if addressKind is not None and a.get("address_kind") != addressKind:
                    continue
                matched_address_ids.add(aid)
            eid = ea.get("entity_id")
            if isinstance(eid, str) and eid in ent_by_id:
                e = ent_by_id[eid]
                if category is None or e.get("category") == category:
                    matched_entity_ids.add(eid)
                    cat = e.get("category")
                    if isinstance(cat, str):
                        matched_categories.add(cat)

    # Materialize and sort
    def _safe_str(x):
        return x if isinstance(x, str) else ""

    ent_rows = []
    for eid in matched_entity_ids:
        e = ent_by_id.get(eid)
        if not e:
            continue
        if category is not None and e.get("category") != category:
            continue
        ent_rows.append(
            {
                "id": e.get("id"),
                "name": e.get("name"),
                "description": e.get("description"),
                "logo_url": e.get("logo_url"),
                "external_links": e.get("external_links"),
                "category": e.get("category"),
                "status": e.get("status"),
                "created_at": e.get("created_at"),
                "updated_at": e.get("updated_at"),
            }
        )
    ent_rows.sort(key=lambda r: (_safe_str(r.get("name")).lower(), _safe_str(r.get("id"))))

    addr_rows = []
    for aid in matched_address_ids:
        a = addr_by_id.get(aid)
        if not a:
            continue
        if chain_id is not None and a.get("chain_id") != chain_id:
            continue
        if addressKind is not None and a.get("address_kind") != addressKind:
            continue

        # attach entity if any (pick highest confidence)
        best = None
        for ea in eas_by_addr.get(aid, []):
            conf = ea.get("confidence")
            if not isinstance(conf, (int, float)):
                conf = -1
            if best is None or conf > best[0]:
                best = (conf, ea)
        ent = None
        if best and isinstance(best[1], dict):
            eid = best[1].get("entity_id")
            if isinstance(eid, str):
                ent = ent_by_id.get(eid)

        addr_rows.append(
            {
                "id": a.get("id"),
                "chain_id": a.get("chain_id"),
                "address": a.get("address"),
                "address_kind": a.get("address_kind"),
                "ens_name": a.get("ens_name"),
                "entity": (
                    None
                    if not ent
                    else {"id": ent.get("id"), "name": ent.get("name"), "category": ent.get("category")}
                ),
                "label": None if not best else best[1].get("label"),
                "confidence": None if not best else best[1].get("confidence"),
                "status": a.get("status"),
                "created_at": a.get("created_at"),
                "updated_at": a.get("updated_at"),
            }
        )
    addr_rows.sort(key=lambda r: (_safe_str(r.get("ens_name")).lower(), _safe_str(r.get("address")).lower(), _safe_str(r.get("id"))))

    cat_rows = [{"category": c} for c in sorted(matched_categories)]

    # Apply per-group pagination using independent offsets in cursor
    e_off, a_off, c_off = cur["entities"], cur["addresses"], cur["categories"]

    ent_page = ent_rows[e_off : e_off + limit]
    addr_page = addr_rows[a_off : a_off + limit]
    cat_page = cat_rows[c_off : c_off + limit]

    next_state = {"entities": e_off + len(ent_page), "addresses": a_off + len(addr_page), "categories": c_off + len(cat_page)}
    has_more = next_state["entities"] < len(ent_rows) or next_state["addresses"] < len(addr_rows) or next_state["categories"] < len(cat_rows)
    next_cursor = _make_cursor(next_state) if has_more else None

    out = {
        "q": q,
        "chainId": chainId,
        "category": category,
        "addressKind": addressKind,
        "result": {
            "entities": ent_page,
            "addresses": addr_page,
            "categories": cat_page,
        },
        "page": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": bool(has_more),
            "totals": {"entities": len(ent_rows), "addresses": len(addr_rows), "categories": len(cat_rows)},
        },
    }

    _log(endpoint, "OK", (time.time() - t0) * 1000, meta={"has_more": has_more})
    return out

def getentity(entityId, includeAddresses=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getentity"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"mor_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None,
            "error": error,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    if not isinstance(entityId, str) or not re.fullmatch(r"^mor_ent_[0-9A-Z]+$", entityId):
        e = _err("VALIDATION_ERROR", "entityId must match ^mor_ent_[0-9A-Z]+$", field="entityId")
        _log("error", e["error"])
        return e

    if includeAddresses is not None and not isinstance(includeAddresses, bool):
        e = _err("VALIDATION_ERROR", "includeAddresses must be boolean", field="includeAddresses")
        _log("error", e["error"])
        return e
    includeAddresses = bool(includeAddresses) if includeAddresses is not None else False

    if includeAddresses:
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or not (1 <= limit <= 200):
            e = _err("VALIDATION_ERROR", "limit must be between 1 and 200 when includeAddresses is true", field="limit")
            _log("error", e["error"])
            return e
    else:
        if limit is not None or cursor is not None:
            e = _err("VALIDATION_ERROR", "limit/cursor can only be provided when includeAddresses is true", field="includeAddresses")
            _log("error", e["error"])
            return e

    def _decode_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        s = cur.strip()
        if s.startswith("offset:"):
            try:
                off = int(s.split(":", 1)[1])
                if off < 0:
                    raise ValueError()
                return off, None
            except ValueError:
                return None, _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(s.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            off = int(obj.get("offset", 0))
            if off < 0:
                raise ValueError()
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

    off = 0
    if includeAddresses:
        off, err = _decode_cursor(cursor)
        if err:
            _log("error", err["error"])
            return err

    entities = _load("entities.json")
    if not isinstance(entities, list):
        entities = []
    ent = next((e for e in entities if isinstance(e, dict) and e.get("id") == entityId), None)
    if not ent:
        e = _err("NOT_FOUND", "entityId not found", entityId=entityId)
        _log("error", e["error"])
        return e

    resp = {
        "id": ent.get("id"),
        "name": ent.get("name"),
        "description": ent.get("description"),
        "logo_url": ent.get("logo_url"),
        "external_links": ent.get("external_links"),
        "category": ent.get("category"),
        "status": ent.get("status"),
        "created_at": ent.get("created_at"),
        "updated_at": ent.get("updated_at"),
    }

    if includeAddresses:
        entity_addresses = _load("entity_addresses.json")
        if not isinstance(entity_addresses, list):
            entity_addresses = []
        addresses = _load("addresses.json")
        if not isinstance(addresses, list):
            addresses = []

        links = [ea for ea in entity_addresses if isinstance(ea, dict) and ea.get("entity_id") == entityId]
        # deterministic order by confidence desc then created_at/id
        def _k(ea):
            c = ea.get("confidence")
            conf = float(c) if isinstance(c, (int, float)) else -1.0
            return (-conf, ea.get("created_at") or "", ea.get("id") or "")
        links.sort(key=_k)

        total = len(links)
        page_links = links[off:off + limit]
        out = []
        for ea in page_links:
            aid = ea.get("address_id")
            addr = next((a for a in addresses if isinstance(a, dict) and a.get("id") == aid), None)
            out.append({
                "entity_address_id": ea.get("id"),
                "address_id": aid,
                "chain_id": addr.get("chain_id") if addr else None,
                "address": addr.get("address") if addr else None,
                "address_kind": addr.get("address_kind") if addr else None,
                "label": ea.get("label"),
                "role": ea.get("role"),
                "confidence": ea.get("confidence"),
            })

        next_off = off + len(page_links)
        has_more = next_off < total
        next_cursor = None
        if has_more:
            payload = json.dumps({"offset": next_off}, separators=(",", ":")).encode("utf-8")
            next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

        resp["addresses"] = {
            "result": out,
            "total": total,
            "page_size": limit,
            "cursor": next_cursor,
            "has_more": has_more,
        }

    _log("ok", meta={"includeAddresses": includeAddresses})
    return resp

