                "latency_ms": int(latency_ms),
                "timestamp": _now(),
                "credential": credential,
                "meta": meta or {},
            }
        )
        _save(fn, logs)

    def _parse_cursor(c):
        if not c:
            return 0
        if not isinstance(c, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"]
            if isinstance(obj, int) and obj >= 0:
                return obj
            return None
        except Exception:
            return None

    def _make_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    t0 = time.time()
    endpoint = "getentitiesbycategory"

    allowed_categories = {
        "exchange",
        "cex",
        "dex",
        "market_maker",
        "protocol",
        "bridge",
        "lending",
