                "updated_at": e.get("updated_at"),
            }
        )

    def _safe_str(x):
        return x if isinstance(x, str) else ""

    sort_reverse = sortOrder == "desc"
    if sortBy == "name":
        rows.sort(key=lambda r: (_safe_str(r.get("name")).lower(), _safe_str(r.get("id"))), reverse=sort_reverse)
    else:
        # ISO 8601 strings sort lexicographically for UTC "Z" format; fallback to empty
        rows.sort(key=lambda r: (_safe_str(r.get(sortBy)), _safe_str(r.get("id"))), reverse=sort_reverse)

    total = len(rows)
    page_off = off if isinstance(off, int) else 0
    page = rows[page_off : page_off + limit]
