        "sortBy": sortBy,
        "sortOrder": sortOrder,
        "result": page,
        "page": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": _make_cursor(next_off) if has_more else None,
            "has_more": bool(has_more),
            "total": total,
        },
    }

    _log(endpoint, "OK", (time.time() - t0) * 1000, meta={"returned": len(page), "total": total})
    return out

