            "credential_id": None,
            "error": error,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _parse_rfc3339(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp", field=field)
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp", field=field)

    if not isinstance(pairAddress, str) or not pairAddress.strip():
        e = _err("VALIDATION_ERROR", "pairAddress must be a non-empty string", field="pairAddress")
        _log("error", e["error"])
