        e = _err("VALIDATION_ERROR", "chainId must match ^mor_chain_[0-9A-Z]+$", field="chainId")
        _log("error", e["error"])
        return e

    tf_allowed = {"1m": 60, "5m": 300, "15m": 900, "30m": 1800, "1h": 3600, "4h": 14400, "1d": 86400, "1w": 604800}
    if not isinstance(timeframe, str) or timeframe not in tf_allowed:
        e = _err("VALIDATION_ERROR", "timeframe is invalid", field="timeframe")
        _log("error", e["error"])
        return e
    step = tf_allowed[timeframe]

