        limit = 200
    if not isinstance(limit, int) or not (1 <= limit <= 1000):
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 1000", field="limit")
        _log("error", e["error"])
        return e

    start_dt, err = _parse_rfc3339(from_, "from")
    if err:
        _log("error", err["error"])
        return err
    end_dt, err = _parse_rfc3339(to, "to")
    if err:
        _log("error", err["error"])
        return err
    if start_dt and end_dt and start_dt >= end_dt:
        e = _err("VALIDATION_ERROR", "`from` must be before `to`", field="from")
        _log("error", e["error"])
        return e

    def _decode_cursor(cur):
        if cur is None:
