    if not isinstance(assets, list):
        assets = []
    events = _load("events.json")
    if not isinstance(events, list):
        events = []

    # Resolve pair contract id from pairAddress (id or raw address)
    pa = pairAddress.strip()
    pair_contract_id = None
    if pa.startswith("mor_addr_"):
        pair_contract_id = pa
    else:
        # try resolve by address string on chain
        pa_norm = pa.lower()
        pair_addr_row = next((a for a in addresses if isinstance(a, dict) and a.get("chain_id") == chainId and isinstance(a.get("address"), str) and a.get("address").lower() == pa_norm), None)
        if pair_addr_row:
            pair_contract_id = pair_addr_row.get("id")

    pair_asset = next((a for a in assets if isinstance(a, dict) and a.get("chain_id") == chainId and a.get("asset_type") == "pair" and a.get("contract_address_id") == pair_contract_id), None) if pair_contract_id else None
    if not pair_asset:
        e = _err("NOT_FOUND", "pairAddress unknown for the given chainId", pairAddress=pairAddress, chainId=chainId)
        _log("error", e["error"])
        return e

    # Collect swap/liquidity events for this pair
    def _parse_ts(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    pair_events = []
    for ev in events:
        if not isinstance(ev, dict):
            continue
        if ev.get("chain_id") != chainId or ev.get("status") != "confirmed":
            continue
        if ev.get("event_type") not in ("swap", "liquidity_add", "liquidity_remove"):
            continue
        if ev.get("contract_address_id") != pair_contract_id:
            continue
        ts = _parse_ts(ev.get("block_timestamp"))
        if ts is None:
            continue
        if start_dt and ts < start_dt:
            continue
        if end_dt and ts >= end_dt:
            continue
        pair_events.append((ts, ev))
    pair_events.sort(key=lambda x: x[0])

    # Build buckets; use metadata fields when available: price_usd, price, volume_usd, volume
    buckets = {}
    for ts, ev in pair_events:
        epoch = int(ts.timestamp())
        b = epoch - (epoch % step)
        md = ev.get("metadata") if isinstance(ev.get("metadata"), dict) else {}
        price = md.get("price_usd")
        if not isinstance(price, (int, float)):
            price = md.get("price")
        vol = md.get("volume_usd")
        if not isinstance(vol, (int, float)):
            vol = md.get("volume")
        if not isinstance(price, (int, float)) or (isinstance(price, float) and (math.isnan(price) or math.isinf(price))):
            # without price, can't do OHLC; skip
            continue
        price = float(price)
        if vol is None or not isinstance(vol, (int, float)) or (isinstance(vol, float) and (math.isnan(vol) or math.isinf(vol))):
            vol = 0.0
        else:
            vol = float(vol)
        o = buckets.get(b)
        if o is None:
            buckets[b] = {"open": price, "high": price, "low": price, "close": price, "volume": vol, "count": 1}
        else:
            o["high"] = max(o["high"], price)
            o["low"] = min(o["low"], price)
            o["close"] = price
            o["volume"] += vol
            o["count"] += 1

    points = []
    for b, agg in buckets.items():
        points.append({
            "timestamp": datetime.datetime.fromtimestamp(b, tz=datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
            "open": agg["open"],
            "high": agg["high"],
            "low": agg["low"],
            "close": agg["close"],
            "volume": agg["volume"],
            "trades": agg["count"],
        })
    points.sort(key=lambda p: p["timestamp"])

    total = len(points)
    page = points[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_off}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    resp = {
        "pairAddress": pairAddress,
        "chainId": chainId,
        "timeframe": timeframe,
        "result": page,
        "total": total,
        "page_size": limit,
        "cursor": next_cursor,
        "has_more": has_more,
    }
    _log("ok", meta={"returned": len(page), "total": total, "offset": offset})
    return resp

def getpairstats(pairAddress, chainId, **_extra):
    import json, os, datetime, time, re, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getpairstats"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"mor_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None,
            "error": error,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    if not isinstance(pairAddress, str) or not pairAddress.strip():
        e = _err("VALIDATION_ERROR", "pairAddress must be a non-empty string", field="pairAddress")
        _log("error", e["error"])
        return e
    if not isinstance(chainId, str) or not re.fullmatch(r"^mor_chain_[0-9A-Z]+$", chainId):
        e = _err("VALIDATION_ERROR", "chainId must match ^mor_chain_[0-9A-Z]+$", field="chainId")
        _log("error", e["error"])
        return e

    chains = _load("chains.json")
    if not isinstance(chains, list):
        chains = []
    if not any(isinstance(c, dict) and c.get("id") == chainId for c in chains):
        e = _err("NOT_FOUND", "chainId not found", chainId=chainId)
        _log("error", e["error"])
        return e

    addresses = _load("addresses.json")
    if not isinstance(addresses, list):
        addresses = []
    assets = _load("assets.json")
    if not isinstance(assets, list):
        assets = []
    events = _load("events.json")
    if not isinstance(events, list):
        events = []

    # Resolve pair contract address id
    pa = pairAddress.strip()
    pair_contract_id = None
    if pa.startswith("mor_addr_"):
        pair_contract_id = pa
    else:
        pa_norm = pa.lower()
        row = next((a for a in addresses if isinstance(a, dict) and a.get("chain_id") == chainId and isinstance(a.get("address"), str) and a.get("address").lower() == pa_norm), None)
        if row:
            pair_contract_id = row.get("id")

    pair_asset = next((a for a in assets if isinstance(a, dict) and a.get("chain_id") == chainId and a.get("asset_type") == "pair" and a.get("contract_address_id") == pair_contract_id), None) if pair_contract_id else None
    if not pair_asset:
        e = _err("NOT_FOUND", "pairAddress unknown for the given chainId", pairAddress=pairAddress, chainId=chainId)
        _log("error", e["error"])
        return e

    # Compute stats from confirmed swap events for the pair
    def _parse_ts(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    swap_events = []
    for ev in events:
        if not isinstance(ev, dict):
            continue
        if ev.get("chain_id") != chainId or ev.get("status") != "confirmed":
            continue
        if ev.get("event_type") != "swap":
            continue
        if ev.get("contract_address_id") != pair_contract_id:
            continue
        swap_events.append(ev)

    # Latest price from most recent swap metadata
    swap_events.sort(key=lambda e: (e.get("block_number") if isinstance(e.get("block_number"), int) else -1, e.get("log_index") if isinstance(e.get("log_index"), int) else -1), reverse=True)
    latest_price = None
    latest_price_usd = None
    if swap_events:
        md = swap_events[0].get("metadata") if isinstance(swap_events[0].get("metadata"), dict) else {}
        p = md.get("price")
        pu = md.get("price_usd")
        if isinstance(p, (int, float)) and not (isinstance(p, float) and (math.isnan(p) or math.isinf(p))):
            latest_price = float(p)
        if isinstance(pu, (int, float)) and not (isinstance(pu, float) and (math.isnan(pu) or math.isinf(pu))):
            latest_price_usd = float(pu)

    # Buyers/sellers counts (unique wallets) and 24h volume
    now = datetime.datetime.now(datetime.timezone.utc)
    start_24h = now - datetime.timedelta(hours=24)
    buyers = set()
    sellers = set()
    volume_usd_24h = 0.0
    swaps_24h = 0
    for ev in swap_events:
        ts = _parse_ts(ev.get("block_timestamp"))
        if ts and ts >= start_24h:
            swaps_24h += 1
            f = ev.get("from_address_id")
            t = ev.get("to_address_id")
            if isinstance(t, str):
                buyers.add(t)
            if isinstance(f, str):
                sellers.add(f)
            v = ev.get("value_usd")
            if isinstance(v, (int, float)) and v >= 0:
                volume_usd_24h += float(v)
            else:
                md = ev.get("metadata") if isinstance(ev.get("metadata"), dict) else {}
                vv = md.get("volume_usd")
                if isinstance(vv, (int, float)) and vv >= 0:
                    volume_usd_24h += float(vv)

    # Liquidity from asset.liquidity_usd if present
    liquidity_usd = pair_asset.get("liquidity_usd") if isinstance(pair_asset.get("liquidity_usd"), (int, float)) else None

    resp = {
        "pair": {
            "asset_id": pair_asset.get("id"),
            "chain_id": chainId,
            "contract_address_id": pair_asset.get("contract_address_id"),
            "name": pair_asset.get("name"),
            "symbol": pair_asset.get("symbol"),
            "status": pair_asset.get("status"),
        },
        "stats": {
            "latest_price": latest_price,
            "latest_price_usd": latest_price_usd,
            "liquidity_usd": float(liquidity_usd) if isinstance(liquidity_usd, (int, float)) else None,
            "volume_usd_24h": volume_usd_24h,
            "swaps_24h": swaps_24h,
            "buyers_24h": len(buyers),
            "sellers_24h": len(sellers),
        }
    }
    _log("ok", meta={"swaps_total": len(swap_events), "swaps_24h": swaps_24h})
    return resp

def gettokenpairs(tokenAddress, chainId, sortBy=None, sortOrder=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "gettokenpairs",
            "status": status,
            "timestamp": now_iso,
            "latency_ms": int((time.time() - start) * 1000),
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _chain_row_for_moralis_chain_id(mor_chain_id, chains):
        if not isinstance(mor_chain_id, str):
            return None
        key = mor_chain_id
        key2 = key[len("mor_chain_") :] if key.startswith("mor_chain_") else key
        for c in chains:
            if c.get("chain_key") == key:
                return c
        for c in chains:
            if c.get("chain_key") == key2:
                return c
        for c in chains:
            if c.get("id") == key:
                return c
        return None

    def _decode_cursor(cur):
        if not cur:
            return 0
        if not isinstance(cur, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4)).decode("utf-8")
            obj = json.loads(raw)
            if obj.get("v") != 1 or obj.get("endpoint") != "gettokenpairs":
                return None
            off = obj.get("offset")
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _encode_cursor(off):
        obj = {"v": 1, "endpoint": "gettokenpairs", "offset": off}
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # ---- validate
    if not isinstance(tokenAddress, str) or not tokenAddress.strip():
        _log("VALIDATION_ERROR", {"field": "tokenAddress"})
        return _err("VALIDATION_ERROR", "tokenAddress must be a non-empty string", field="tokenAddress")
    if not isinstance(chainId, str) or not re.match(r"^mor_chain_[0-9A-Z]+$", chainId):
        _log("VALIDATION_ERROR", {"field": "chainId"})
        return _err("VALIDATION_ERROR", "chainId must match ^mor_chain_[0-9A-Z]+$", field="chainId")

    if sortBy is None:
        sortBy = "liquidity_usd"
    if sortOrder is None:
        sortOrder = "desc"
    if sortBy not in ("liquidity_usd", "volume_usd", "price_usd", "created_at"):
        _log("VALIDATION_ERROR", {"field": "sortBy"})
        return _err("VALIDATION_ERROR", "sortBy is invalid", field="sortBy")
    if sortOrder not in ("asc", "desc"):
        _log("VALIDATION_ERROR", {"field": "sortOrder"})
        return _err("VALIDATION_ERROR", "sortOrder is invalid", field="sortOrder")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("VALIDATION_ERROR", {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit out of range (1..100)", field="limit")

    offset = _decode_cursor(cursor)
    if cursor is not None and offset is None:
        _log("VALIDATION_ERROR", {"field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    chains = _load("chains.json")
    addresses = _load("addresses.json")
    assets = _load("assets.json")
    events = _load("events.json")

    chain = _chain_row_for_moralis_chain_id(chainId, chains)
    if not chain or chain.get("status") == "disabled":
        _log("NOT_FOUND", {"field": "chainId"})
        return _err("NOT_FOUND", "chainId not found or disabled", field="chainId")
    chain_pk = chain.get("id")

    token_addr_norm = tokenAddress.strip().lower()
    token_address_row = None
    for a in addresses:
        if a.get("chain_id") == chain_pk and isinstance(a.get("address"), str) and a.get("address").lower() == token_addr_norm:
            token_address_row = a
            break
    if not token_address_row:
        # token itself unknown => empty list (read filter match nothing)
        resp = {"chainId": chainId, "tokenAddress": tokenAddress, "result": [], "pagination": {"total": 0, "has_more": False, "cursor": None}}
        _log("OK", {"returned": 0, "total": 0})
        return resp

    token_address_id = token_address_row.get("id")
    token_asset = None
    for asst in assets:
        if asst.get("chain_id") == chain_pk and asst.get("asset_type") == "erc20" and asst.get("contract_address_id") == token_address_id and asst.get("status") != "hidden":
            token_asset = asst
            break
    if not token_asset:
        # token exists as address but not as served ERC20 asset: empty list
        resp = {"chainId": chainId, "tokenAddress": tokenAddress, "result": [], "pagination": {"total": 0, "has_more": False, "cursor": None}}
        _log("OK", {"returned": 0, "total": 0})
        return resp

    token_asset_id = token_asset.get("id")

    # Find pair assets on chain that reference token_asset_id in metadata
    def _pair_involves_token(pair_row):
        md = pair_row.get("metadata") if isinstance(pair_row.get("metadata"), dict) else {}
        # support a few possible shapes:
        # - {"token0_asset_id": "...", "token1_asset_id": "..."}
        # - {"token0": {"asset_id": "..."}, ...}
        # - {"assets": ["...", "..."]}
        for k in ("token0_asset_id", "token1_asset_id", "base_asset_id", "quote_asset_id"):
            if md.get(k) == token_asset_id:
                return True
        t0 = md.get("token0")
        if isinstance(t0, dict) and t0.get("asset_id") == token_asset_id:
            return True
        t1 = md.get("token1")
        if isinstance(t1, dict) and t1.get("asset_id") == token_asset_id:
            return True
        arr = md.get("assets")
        if isinstance(arr, list) and token_asset_id in arr:
            return True
        # fallback: pair.asset_id / counter_asset_id usage is on events; use events to discover involvement
        return False

    # Precompute 24h volume per pair from swap events
    def _parse_rfc3339(s):
        if not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    window_start = now_dt - datetime.timedelta(days=1)
    vol24_by_pair_addr = {}
    for ev in events:
        if ev.get("chain_id") != chain_pk or ev.get("status") != "confirmed" or ev.get("event_type") != "swap":
            continue
        dt = _parse_rfc3339(ev.get("block_timestamp"))
        if dt is None or dt < window_start:
            continue
        pair_addr_id = ev.get("contract_address_id")
        if not isinstance(pair_addr_id, str):
            continue
        # optional filter for token involvement if event uses asset_id/counter_asset_id
        if ev.get("asset_id") != token_asset_id and ev.get("counter_asset_id") != token_asset_id:
            # keep counting only if token involvement can't be determined later? We'll skip to avoid false positives.
            continue
        md = ev.get("metadata") if isinstance(ev.get("metadata"), dict) else {}
        v = None
        for k in ("volume_usd", "volumeUSD", "value_usd", "amount_usd"):
            vv = md.get(k)
            if isinstance(vv, (int, float)) and vv >= 0:
                v = float(vv)
                break
        if v is None and isinstance(ev.get("value_usd"), (int, float)) and ev.get("value_usd") >= 0:
            v = float(ev.get("value_usd"))
        if v is None:
            continue
        vol24_by_pair_addr[pair_addr_id] = vol24_by_pair_addr.get(pair_addr_id, 0.0) + v

    pairs = []
    for asst in assets:
        if asst.get("chain_id") != chain_pk:
            continue
        if asst.get("asset_type") != "pair":
            continue
        if asst.get("status") == "hidden":
            continue
        if not isinstance(asst.get("contract_address_id"), str):
            continue
        involves = _pair_involves_token(asst)
        # If metadata doesn't say, allow event-based involvement evidence.
        if not involves and asst.get("contract_address_id") in vol24_by_pair_addr:
            involves = True
        if not involves:
            continue

        pair_row = dict(asst)
        pair_row["volume_usd_24h"] = vol24_by_pair_addr.get(asst.get("contract_address_id"), 0.0)
        pairs.append(pair_row)

    # sorting
    reverse = (sortOrder == "desc")
    if sortBy == "created_at":
        def keyfn(x):
            v = x.get("created_at")
            return v if isinstance(v, str) else ""
    elif sortBy == "volume_usd":
        def keyfn(x):
            v = x.get("volume_usd_24h")
            return float(v) if isinstance(v, (int, float)) else 0.0
    elif sortBy == "price_usd":
        def keyfn(x):
            v = x.get("latest_price_usd")
            return float(v) if isinstance(v, (int, float)) else -1.0
    else:  # liquidity_usd
        def keyfn(x):
            v = x.get("liquidity_usd")
            return float(v) if isinstance(v, (int, float)) else -1.0

    pairs.sort(key=keyfn, reverse=reverse)

    total = len(pairs)
    page = pairs[offset : offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    # minimal response rows: include address string by joining addresses
    addr_by_id = {a.get("id"): a for a in addresses if isinstance(a, dict)}
    out = []
    for p in page:
        caid = p.get("contract_address_id")
        addr = addr_by_id.get(caid, {})
        out.append({
            "id": p.get("id"),
            "pairAddress": addr.get("address"),
            "chain_id": p.get("chain_id"),
            "name": p.get("name"),
            "symbol": p.get("symbol"),
            "latest_price_usd": p.get("latest_price_usd"),
            "liquidity_usd": p.get("liquidity_usd"),
            "volume_usd_24h": p.get("volume_usd_24h"),
            "created_at": p.get("created_at"),
            "updated_at": p.get("updated_at"),
            "metadata": p.get("metadata"),
            "status": p.get("status"),
        })

    resp = {"chainId": chainId, "tokenAddress": tokenAddress, "result": out, "pagination": {"total": total, "has_more": has_more, "cursor": next_cursor}}
    _log("OK", {"returned": len(out), "total": total})
    return resp

def getswapsbywalletaddress(walletAddress, chainId, tokenAddress=None, from_=None, to=None, limit=None, cursor=None, sortOrder=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
