            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _log(status, chain_row_id=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "req_" + hashlib.sha1(f"{time.time_ns()}|getswapsbywalletaddress".encode("utf-8")).hexdigest()[:16],
                "endpoint": "getswapsbywalletaddress",
                "timestamp": datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat(),
                "status": status,
                "chain_id": chain_row_id,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    # ---- validate ----
    if not isinstance(walletAddress, str) or not walletAddress.strip():
        _log("error")
        return _err("VALIDATION_ERROR", "walletAddress must be a non-empty string")
    if not isinstance(chainId, str) or not chainId.startswith("mor_chain_"):
        _log("error")
        return _err("VALIDATION_ERROR", "chainId is invalid")
    if tokenAddress is not None and (not isinstance(tokenAddress, str) or not tokenAddress.strip()):
        _log("error")
        return _err("VALIDATION_ERROR", "tokenAddress must be a non-empty string when provided")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    if cursor is not None and (not isinstance(cursor, str) or cursor == ""):
        _log("error")
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
    if sortOrder is None:
        sortOrder = "desc"
    if sortOrder not in ("asc", "desc"):
        _log("error")
        return _err("VALIDATION_ERROR", "sortOrder must be 'asc' or 'desc'")

    dt_from = _parse_rfc3339(from_) if from_ is not None else None
    dt_to = _parse_rfc3339(to) if to is not None else None
    if from_ is not None and dt_from is None:
        _log("error")
        return _err("VALIDATION_ERROR", "`from` must be an RFC3339 timestamp")
    if to is not None and dt_to is None:
        _log("error")
        return _err("VALIDATION_ERROR", "`to` must be an RFC3339 timestamp")
    if dt_from is not None and dt_to is not None and dt_from > dt_to:
        _log("error")
        return _err("VALIDATION_ERROR", "`from` must be <= `to`")

    # ---- resolve chain ----
    chains = _load("chains.json")
    chain_row = next((c for c in chains if isinstance(c, dict) and c.get("id") == chainId), None)
    if not chain_row:
        _log("error")
        return _err("NOT_FOUND", "chainId not found")
    chain_row_id = chain_row["id"]

    # ---- resolve/create wallet address row (create-on-read allowed for addresses only) ----
    addresses = _load("addresses.json")
    w_norm = walletAddress.strip().lower()
    wallet_row = next(
        (a for a in addresses
         if isinstance(a, dict)
         and a.get("chain_id") == chain_row_id
         and isinstance(a.get("address"), str)
         and a.get("address").lower() == w_norm),
        None
    )
    mutated = False
    if wallet_row is None:
        # create wallet address row
        new_id = "adr_" + hashlib.sha1(f"{time.time_ns()}|{chain_row_id}|{w_norm}".encode("utf-8")).hexdigest()[:18]
        now = _now_iso()
        wallet_row = {
            "id": new_id,
            "chain_id": chain_row_id,
            "address": w_norm,
            "address_kind": "wallet",
            "ens_name": None,
            "ens_resolved_address": None,
            "first_seen_at": None,
            "last_seen_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        addresses.append(wallet_row)
        mutated = True

    # If exists but not wallet_kind, still treat it as wallet per business rule; do not mutate kind.
    wallet_id = wallet_row.get("id")
    if not isinstance(wallet_id, str) or not wallet_id:
        _log("error", chain_row_id=chain_row_id)
        return _err("NOT_FOUND", "wallet address could not be resolved")

    # ---- resolve optional tokenAddress to an asset_id (erc20) if possible; if unknown, return empty result (no swaps can match) ----
    token_asset_ids = None
    if tokenAddress is not None:
        t_norm = tokenAddress.strip().lower()
        token_addr_row = next(
            (a for a in addresses
             if isinstance(a, dict)
             and a.get("chain_id") == chain_row_id
             and isinstance(a.get("address"), str)
             and a.get("address").lower() == t_norm),
            None
        )
        if token_addr_row is None:
            # token unknown => empty set (read should not error)
            if mutated:
                _save("addresses.json", addresses)
            _log("ok", chain_row_id=chain_row_id)
            return {
                "result": [],
                "meta": {"total": 0, "has_more": False, "next_cursor": None, "limit": limit, "cursor": cursor}
            }
        assets = _load("assets.json")
        token_asset_ids = set(
            a.get("id") for a in assets
            if isinstance(a, dict)
            and a.get("chain_id") == chain_row_id
            and a.get("asset_type") == "erc20"
            and a.get("contract_address_id") == token_addr_row.get("id")
            and a.get("status") != "hidden"
        )
        if not token_asset_ids:
            if mutated:
                _save("addresses.json", addresses)
            _log("ok", chain_row_id=chain_row_id)
            return {
                "result": [],
                "meta": {"total": 0, "has_more": False, "next_cursor": None, "limit": limit, "cursor": cursor}
            }

    # ---- decode cursor ----
    # Cursor is opaque; we encode {"offset": n} relative to the filtered, sorted list.
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or "offset" not in payload:
                _log("error", chain_row_id=chain_row_id)
                return _err("VALIDATION_ERROR", "cursor is invalid")
            offset = payload.get("offset")
            if not isinstance(offset, int) or offset < 0:
                _log("error", chain_row_id=chain_row_id)
                return _err("VALIDATION_ERROR", "cursor is invalid")
        except Exception:
            _log("error", chain_row_id=chain_row_id)
            return _err("VALIDATION_ERROR", "cursor is invalid")

    # ---- query swap events ----
    events = _load("events.json")

    def _event_dt(e):
        ts = e.get("block_timestamp")
        if not isinstance(ts, str):
            return None
        return _parse_rfc3339(ts)

    filtered = []
    for e in events:
        if not isinstance(e, dict):
            continue
        if e.get("chain_id") != chain_row_id:
            continue
        if e.get("status") != "confirmed":
            continue
        if e.get("event_type") != "swap":
            continue
        if e.get("from_address_id") != wallet_id and e.get("to_address_id") != wallet_id:
            continue
        dt = _event_dt(e)
        if dt is None:
            continue
        if dt_from is not None and dt < dt_from:
            continue
        if dt_to is not None and dt >= dt_to:
            continue
        if token_asset_ids is not None:
            # swap can involve asset_id or counter_asset_id
            if e.get("asset_id") not in token_asset_ids and e.get("counter_asset_id") not in token_asset_ids:
                continue
        filtered.append((dt, e))

    reverse = (sortOrder == "desc")
    filtered.sort(key=lambda x: x[0], reverse=reverse)

    total = len(filtered)
    page_slice = filtered[offset: offset + limit]
    rows = []
    for dt, e in page_slice:
        # Return a concise swap event object; do not fabricate missing joins.
        rows.append({
            "id": e.get("id"),
            "chainId": chain_row_id,
            "blockNumber": e.get("block_number"),
            "blockTimestamp": e.get("block_timestamp"),
            "transactionHash": e.get("transaction_hash"),
            "logIndex": e.get("log_index"),
            "fromAddressId": e.get("from_address_id"),
            "toAddressId": e.get("to_address_id"),
            "pairAddressId": e.get("contract_address_id"),
            "assetId": e.get("asset_id"),
            "counterAssetId": e.get("counter_asset_id"),
            "amountRaw": e.get("amount_raw"),
            "amountDecimal": e.get("amount_decimal"),
            "valueUsd": e.get("value_usd"),
            "metadata": e.get("metadata"),
        })

    new_offset = offset + len(rows)
    has_more = new_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": new_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    if mutated:
        _save("addresses.json", addresses)

    _log("ok", chain_row_id=chain_row_id)
    return {
        "result": rows,
        "meta": {
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "limit": limit,
            "sort_order": sortOrder
        }
    }

def getswapsbypairaddress(chain, pairAddress, fromBlock=None, toBlock=None, fromDate=None, toDate=None, eventType=None, order=None, cursor=None, limit=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _norm_evm_addr(a):
        if not isinstance(a, str):
            return None
        a = a.strip()
        if len(a) != 42 or not a.startswith("0x"):
            return None
        h = a[2:]
        try:
            int(h, 16)
        except Exception:
            return None
        return "0x" + h.lower()

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4)).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return None
            if obj.get("v") != 1:
                return None
            idx = obj.get("i")
            if not isinstance(idx, int) or idx < 0:
                return None
            return idx
        except Exception:
            return None

    def _encode_cursor(idx):
        raw = json.dumps({"v": 1, "i": idx}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    t0 = time.time()
    endpoint = "getswapsbypairaddress"

    # Validate inputs
    if not isinstance(chain, str) or not chain.strip():
        return _err("VALIDATION_ERROR", "chain must be a non-empty string")
    if order is None:
        order = "DESC"
    if order not in ("ASC", "DESC"):
        return _err("VALIDATION_ERROR", "order must be one of: ASC, DESC")
    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")

    if fromBlock is not None and (not isinstance(fromBlock, int) or fromBlock < 0):
        return _err("VALIDATION_ERROR", "fromBlock must be an integer >= 0")
    if toBlock is not None and (not isinstance(toBlock, int) or toBlock < 0):
        return _err("VALIDATION_ERROR", "toBlock must be an integer >= 0")
    if fromBlock is not None and toBlock is not None and fromBlock > toBlock:
        return _err("VALIDATION_ERROR", "fromBlock must be <= toBlock")

    fdt = _parse_dt(fromDate)
    if fromDate is not None and fdt is None:
        return _err("VALIDATION_ERROR", "fromDate must be an RFC3339 date-time string")
    tdt = _parse_dt(toDate)
    if toDate is not None and tdt is None:
        return _err("VALIDATION_ERROR", "toDate must be an RFC3339 date-time string")
    if fdt is not None and tdt is not None and fdt > tdt:
        return _err("VALIDATION_ERROR", "fromDate must be <= toDate")

    if eventType is not None and eventType not in ("swap", "liquidity_add", "liquidity_remove"):
        return _err("VALIDATION_ERROR", "eventType must be one of: swap, liquidity_add, liquidity_remove")

    pair_norm = _norm_evm_addr(pairAddress)
    if pair_norm is None:
        return _err("VALIDATION_ERROR", "pairAddress must be a 0x-prefixed 40-byte hex string")

    # Load data
    chains = _load("chains.json")
    addresses = _load("addresses.json")
    events = _load("events.json")
    request_logs = _load("request_logs.json")

    # Resolve chain (key or hex numeric id-as-string)
    chain_in = chain.strip().lower()
    chain_row = None
    # accept exact chain_key match or id match; also accept numeric chain id-like strings by mapping to chain_key if stored that way
    for c in chains:
        if not isinstance(c, dict):
            continue
        if str(c.get("chain_key", "")).lower() == chain_in or str(c.get("id", "")).lower() == chain_in:
            chain_row = c
            break
    if chain_row is None:
        # log then return
        request_logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": "NOT_FOUND",
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(_now()),
        })
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Chain not found")
    if chain_row.get("status") == "disabled":
        request_logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": "UNAUTHORIZED",
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(_now()),
        })
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "Chain is disabled")

    chain_id = chain_row.get("id")

    # Resolve pair contract address row (create-on-read allowed only for wallet addresses, not contracts)
    pair_addr_row = None
    for a in addresses:
        if not isinstance(a, dict):
            continue
        if a.get("chain_id") == chain_id and str(a.get("address", "")).lower() == pair_norm:
            pair_addr_row = a
            break
    if pair_addr_row is None:
        request_logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": "NOT_FOUND",
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(_now()),
        })
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Pair address not found on this chain")
    pair_address_id = pair_addr_row.get("id")

    # Cursor
    start_idx = 0
    if cursor is not None:
        start_idx = _decode_cursor(cursor)
        if start_idx is None:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # Filter events
    allowed_types = {"swap", "liquidity_add", "liquidity_remove"}
    want_types = allowed_types if eventType is None else {eventType}

    def _evt_dt(e):
        dt = _parse_dt(e.get("block_timestamp"))
        return dt

    filtered = []
    for e in events:
        if not isinstance(e, dict):
            continue
        if e.get("chain_id") != chain_id:
            continue
        if e.get("status") != "confirmed":
            continue
        et = e.get("event_type")
        if et not in want_types:
            continue
        if e.get("contract_address_id") != pair_address_id:
            continue
        bn = e.get("block_number")
        if not isinstance(bn, int):
            continue
        if fromBlock is not None and bn < fromBlock:
            continue
        if toBlock is not None and bn > toBlock:
            continue
        bt = _evt_dt(e)
        if bt is None:
            continue
        if fdt is not None and bt < fdt:
            continue
        if tdt is not None and bt > tdt:
            continue
        filtered.append(e)

    # Sort by (block_number, block_timestamp, log_index, id) with order
    def _log_index(e):
        li = e.get("log_index")
        return li if isinstance(li, int) else -1

    def _key(e):
        bt = _evt_dt(e)
        bt_ts = int(bt.timestamp()) if bt else 0
        return (e.get("block_number", 0), bt_ts, _log_index(e), str(e.get("id", "")))

    reverse = (order == "DESC")
    filtered.sort(key=_key, reverse=reverse)

    total = len(filtered)
    page = filtered[start_idx:start_idx + limit]
    next_cursor = None
    if start_idx + limit < total:
        next_cursor = _encode_cursor(start_idx + limit)

    # Minimal Moralis-like envelope
    result = {
        "chain": chain_row.get("chain_key"),
        "pair_address": pair_norm,
        "result": page,
        "cursor": next_cursor,
        "page_size": limit,
        "total": total,
        "has_more": next_cursor is not None,
    }

    request_logs.append({
        "id": f"req_{int(time.time()*1000)}",
        "endpoint": endpoint,
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000),
        "ts": _iso(_now()),
        "chain_id": chain_id,
    })
    _save("request_logs.json", request_logs)
    return result

def getsnipersbypairaddress(chain, pairAddress, blocksAfterCreation, minBuyAmountUsd=None, includeSoldStats=None, orderBy=None, order=None, cursor=None, limit=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getsnipersbypairaddress"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error=None, meta=None, chain_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"mor_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "chain_id": chain_id,
            "credential_id": None,
            "error": error,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    # validate inputs
    if not isinstance(chain, str) or not chain.strip():
        e = _err("VALIDATION_ERROR", "chain must be a non-empty string", field="chain")
        _log("error", e["error"])
        return e
    if not isinstance(pairAddress, str) or not re.fullmatch(r"^0x[a-fA-F0-9]{40}$", pairAddress.strip()):
        e = _err("VALIDATION_ERROR", "pairAddress must match ^0x[a-fA-F0-9]{40}$", field="pairAddress")
        _log("error", e["error"])
        return e
    if not isinstance(blocksAfterCreation, int) or blocksAfterCreation < 1:
        e = _err("VALIDATION_ERROR", "blocksAfterCreation must be an integer >= 1", field="blocksAfterCreation")
        _log("error", e["error"])
        return e
    if minBuyAmountUsd is not None and (not isinstance(minBuyAmountUsd, (int, float)) or minBuyAmountUsd < 0):
        e = _err("VALIDATION_ERROR", "minBuyAmountUsd must be a number >= 0", field="minBuyAmountUsd")
        _log("error", e["error"])
        return e
    if includeSoldStats is not None and not isinstance(includeSoldStats, bool):
        e = _err("VALIDATION_ERROR", "includeSoldStats must be boolean", field="includeSoldStats")
        _log("error", e["error"])
        return e
    includeSoldStats = bool(includeSoldStats) if includeSoldStats is not None else False

    if orderBy is None:
        orderBy = "buy_amount_usd"
    if not isinstance(orderBy, str) or orderBy not in ("buy_amount_usd", "sell_amount_usd", "pnl_usd", "first_buy_block"):
        e = _err("VALIDATION_ERROR", "orderBy is invalid", field="orderBy")
        _log("error", e["error"])
        return e
    if order is None:
        order = "DESC"
    if not isinstance(order, str) or order not in ("ASC", "DESC"):
        e = _err("VALIDATION_ERROR", "order is invalid", field="order")
        _log("error", e["error"])
        return e
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 100):
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")
        _log("error", e["error"])
        return e

    def _decode_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        s = cur.strip()
        try:
            raw = base64.urlsafe_b64decode(s.encode("utf-8") + b"=" * (-len(s) % 4)).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return None, _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            off = obj.get("o")
            if not isinstance(off, int) or off < 0:
                return None, _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    def _encode_cursor(off):
        raw = json.dumps({"v": 1, "o": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    offset, err = _decode_cursor(cursor)
    if err:
        _log("error", err["error"])
        return err

    # resolve chain (key or id string)
    chains_rows = _load("chains.json")
    if not isinstance(chains_rows, list):
        chains_rows = []
    c_in = chain.strip()
    chain_row = next((r for r in chains_rows if isinstance(r, dict) and (r.get("id") == c_in or r.get("chain_key") == c_in)), None)
    if not chain_row:
        e = _err("NOT_FOUND", "chain not found", chain=chain)
        _log("error", e["error"])
        return e
    chain_id = chain_row.get("id")

    addresses = _load("addresses.json")
    if not isinstance(addresses, list):
        addresses = []
    pair_norm = "0x" + pairAddress.strip()[2:].lower()
    pair_addr_row = next((a for a in addresses if isinstance(a, dict) and a.get("chain_id") == chain_id and (a.get("address") or "").lower() == pair_norm), None)
    if not pair_addr_row:
        # no data => empty, but spec says analyze pair; treat unknown pair as NOT_FOUND
        e = _err("NOT_FOUND", "pairAddress not found for chain", pairAddress=pairAddress, chain=chain)
        _log("error", e["error"], chain_id=chain_id)
        return e
    pair_contract_address_id = pair_addr_row.get("id")

    events = _load("events.json")
    if not isinstance(events, list):
        events = []

    # infer creation block: earliest event for this pair (swap/liquidity_add/liquidity_remove) confirmed
    pair_ev = [ev for ev in events if isinstance(ev, dict) and ev.get("chain_id") == chain_id and ev.get("status") == "confirmed" and ev.get("contract_address_id") == pair_contract_address_id and ev.get("event_type") in ("swap", "liquidity_add", "liquidity_remove")]
    if not pair_ev:
        # nothing indexed for this pair => return empty
        _log("ok", meta={"returned": 0, "total": 0}, chain_id=chain_id)
        return {"result": [], "total": 0, "page_size": limit, "cursor": None, "has_more": False}

    creation_block = min([ev.get("block_number") for ev in pair_ev if isinstance(ev.get("block_number"), int)] or [0])
    cutoff_block = creation_block + blocksAfterCreation

    # sniper = wallet that bought (to_address_id) in swap events within cutoff
    # buy_amount_usd derived from value_usd; if missing, 0.0
    stats = {}
    for ev in pair_ev:
        if ev.get("event_type") != "swap":
            continue
        bn = ev.get("block_number")
        if not isinstance(bn, int) or bn > cutoff_block:
            continue
        wallet = ev.get("to_address_id")
        if not wallet:
            continue
        s = stats.get(wallet)
        if s is None:
            s = {"wallet_address_id": wallet, "buy_amount_usd": 0.0, "sell_amount_usd": 0.0, "pnl_usd": None, "first_buy_block": bn}
            stats[wallet] = s
        if bn < s["first_buy_block"]:
            s["first_buy_block"] = bn
        v = ev.get("value_usd")
        if isinstance(v, (int, float)) and v >= 0:
            s["buy_amount_usd"] += float(v)

    rows = list(stats.values())
    if minBuyAmountUsd is not None:
        rows = [r for r in rows if r["buy_amount_usd"] >= float(minBuyAmountUsd)]

    # sold stats: very rough, treat swaps where wallet is from_address_id as sells, across all time
    if includeSoldStats:
        for ev in pair_ev:
            if ev.get("event_type") != "swap":
                continue
            wallet = ev.get("from_address_id")
            if not wallet or wallet not in stats:
                continue
            v = ev.get("value_usd")
            if isinstance(v, (int, float)) and v >= 0:
                stats[wallet]["sell_amount_usd"] += float(v)
        for r in rows:
            r["pnl_usd"] = r["sell_amount_usd"] - r["buy_amount_usd"]

    rows.sort(key=lambda r: (r.get(orderBy) if r.get(orderBy) is not None else -1e30, r.get("wallet_address_id") or ""), reverse=(order == "DESC"))

    total = len(rows)
    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    _log("ok", meta={"returned": len(page), "total": total, "creation_block": creation_block, "cutoff_block": cutoff_block}, chain_id=chain_id)
    return {"result": page, "total": total, "page_size": limit, "cursor": next_cursor, "has_more": has_more}

def getvolumestatsbychain(timeframe, includeSolana=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    t0 = time.time()
    endpoint = "getvolumestatsbychain"

    if timeframe not in ("1h", "4h", "24h", "7d", "30d"):
        return _err("VALIDATION_ERROR", "timeframe must be one of: 1h, 4h, 24h, 7d, 30d")

    if includeSolana is None:
        includeSolana = False
    if not isinstance(includeSolana, bool):
        return _err("VALIDATION_ERROR", "includeSolana must be a boolean")

    # Resolve plan/auth: ambient. If includeSolana requested, only allow if there exists an active solana chain.
    chains = _load("chains.json")
    events = _load("events.json")
    request_logs = _load("request_logs.json")

    now = _now()
    delta = {
        "1h": datetime.timedelta(hours=1),
        "4h": datetime.timedelta(hours=4),
        "24h": datetime.timedelta(hours=24),
        "7d": datetime.timedelta(days=7),
        "30d": datetime.timedelta(days=30),
    }[timeframe]
    start = now - delta

    # Determine eligible chains
    eligible = []
    solana_present = False
    for c in chains:
        if not isinstance(c, dict):
            continue
        if c.get("status") == "disabled":
            continue
        if c.get("chain_type") == "solana":
            solana_present = True
            if includeSolana:
                eligible.append(c)
        else:
            eligible.append(c)

    if includeSolana and not solana_present:
        request_logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": "UNAUTHORIZED",
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(now),
        })
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "includeSolana not supported for this account/plan (no Solana access configured)")

    # Aggregate per chain from confirmed events.
    # Volume: sum value_usd over swaps and nft_trade; Transactions: count tx-having events in window.
    # Active wallets: unique from/to addresses observed in financial events (swap, nft_trade, token_transfer, native_transfer).
    per_chain = []
    overall = {
        "timeframe": timeframe,
        "from_date": _iso(start),
        "to_date": _iso(now),
        "volume_usd": 0.0,
        "transactions": 0,
        "active_wallets": 0,
        "chains": [],
    }

    eligible_by_id = {c.get("id"): c for c in eligible if isinstance(c, dict) and c.get("id")}
    active_wallets_overall = set()

    for cid, c in eligible_by_id.items():
        volume = 0.0
        txs = 0
        wallets = set()
        for e in events:
            if not isinstance(e, dict):
                continue
            if e.get("chain_id") != cid:
                continue
            if e.get("status") != "confirmed":
                continue
            bt = _parse_dt(e.get("block_timestamp"))
            if bt is None or bt < start or bt > now:
                continue
            et = e.get("event_type")
            if et in ("swap", "nft_trade"):
                v = e.get("value_usd")
                if isinstance(v, (int, float)) and v >= 0:
                    volume += float(v)
            if e.get("transaction_hash"):
                txs += 1
            if et in ("swap", "nft_trade", "token_transfer", "native_transfer"):
                fa = e.get("from_address_id")
                ta = e.get("to_address_id")
                if fa:
                    wallets.add(fa)
                if ta:
                    wallets.add(ta)

        per_row = {
            "chain": c.get("chain_key"),
            "chain_id": cid,
            "volume_usd": volume,
            "transactions": txs,
            "active_wallets": len(wallets),
        }
        per_chain.append(per_row)
        overall["volume_usd"] += volume
        overall["transactions"] += txs
        active_wallets_overall |= wallets

    overall["active_wallets"] = len(active_wallets_overall)
    overall["chains"] = sorted(per_chain, key=lambda r: (-(r["volume_usd"]), str(r.get("chain", ""))))

    request_logs.append({
        "id": f"req_{int(time.time()*1000)}",
        "endpoint": endpoint,
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000),
        "ts": _iso(now),
    })
    _save("request_logs.json", request_logs)
    return overall

def getvolumestatsbycategory(chain, timeframe, cursor=None, limit=None, orderBy=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4)).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return None
            idx = obj.get("i")
            if not isinstance(idx, int) or idx < 0:
                return None
            return idx
        except Exception:
            return None

    def _encode_cursor(idx):
        raw = json.dumps({"v": 1, "i": idx}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    t0 = time.time()
    endpoint = "getvolumestatsbycategory"

    if not isinstance(chain, str) or not chain.strip():
        return _err("VALIDATION_ERROR", "chain must be a non-empty string")
    if timeframe not in ("1h", "4h", "24h", "7d", "30d"):
        return _err("VALIDATION_ERROR", "timeframe must be one of: 1h, 4h, 24h, 7d, 30d")

    if limit is None:
        limit = 200
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    if orderBy is None:
        orderBy = "volume_usd"
    if orderBy not in ("volume_usd", "buyers", "sellers", "transactions"):
        return _err("VALIDATION_ERROR", "orderBy must be one of: volume_usd, buyers, sellers, transactions")
    if order is None:
        order = "DESC"
    if order not in ("ASC", "DESC"):
        return _err("VALIDATION_ERROR", "order must be one of: ASC, DESC")

    start_idx = 0
    if cursor is not None:
        start_idx = _decode_cursor(cursor)
        if start_idx is None:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    chains = _load("chains.json")
    entities = _load("entities.json")
    entity_addresses = _load("entity_addresses.json")
    events = _load("events.json")
    request_logs = _load("request_logs.json")

    # Resolve chain
    chain_in = chain.strip().lower()
    chain_row = None
    for c in chains:
        if not isinstance(c, dict):
            continue
        if str(c.get("chain_key", "")).lower() == chain_in or str(c.get("id", "")).lower() == chain_in:
            chain_row = c
            break
    if chain_row is None:
        request_logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": "NOT_FOUND",
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(_now()),
        })
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Chain not found")
    if chain_row.get("status") == "disabled":
        request_logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": "UNAUTHORIZED",
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(_now()),
        })
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "Chain is disabled")
    chain_id = chain_row.get("id")

    now = _now()
    delta = {
        "1h": datetime.timedelta(hours=1),
        "4h": datetime.timedelta(hours=4),
        "24h": datetime.timedelta(hours=24),
        "7d": datetime.timedelta(days=7),
        "30d": datetime.timedelta(days=30),
    }[timeframe]
    start = now - delta

    # Build entity_id -> category and address_id -> entity_ids
    ent_by_id = {}
    for e in entities:
        if isinstance(e, dict) and e.get("id"):
            ent_by_id[e["id"]] = e

    addr_to_entity = {}
    for ea in entity_addresses:
        if not isinstance(ea, dict):
            continue
        ent_id = ea.get("entity_id")
        addr_id = ea.get("address_id")
        if not ent_id or not addr_id:
            continue
        if ent_id not in ent_by_id:
            continue
        addr_to_entity.setdefault(addr_id, set()).add(ent_id)

    # Aggregate category stats from swap/nft_trade events by mapping participants to entities/categories.
    # Buyers: unique to_address_id mapped to an entity in category; Sellers: unique from_address_id mapped similarly.
    stats = {}  # category -> accumulators
    for ev in events:
        if not isinstance(ev, dict):
            continue
        if ev.get("chain_id") != chain_id:
            continue
        if ev.get("status") != "confirmed":
            continue
        bt = _parse_dt(ev.get("block_timestamp"))
        if bt is None or bt < start or bt > now:
            continue
        if ev.get("event_type") not in ("swap", "nft_trade"):
            continue

        v = ev.get("value_usd")
        value = float(v) if isinstance(v, (int, float)) and v >= 0 else 0.0

        tx_count = 1 if ev.get("transaction_hash") else 0

        from_id = ev.get("from_address_id")
        to_id = ev.get("to_address_id")

        # For each side, attribute to all linked entities; then to their categories.
        cats_from = set()
        if from_id and from_id in addr_to_entity:
            for ent_id in addr_to_entity[from_id]:
                ent = ent_by_id.get(ent_id)
                if ent and ent.get("status") == "active":
                    cats_from.add(ent.get("category"))
        cats_to = set()
        if to_id and to_id in addr_to_entity:
            for ent_id in addr_to_entity[to_id]:
                ent = ent_by_id.get(ent_id)
                if ent and ent.get("status") == "active":
                    cats_to.add(ent.get("category"))

        # Volume attribution: split to categories present on either side; if none, ignore (unknown wallets)
        cats_volume = cats_from | cats_to
        if cats_volume:
            per_cat_value = value / float(len(cats_volume)) if len(cats_volume) > 0 else 0.0
            for cat in cats_volume:
                if not cat:
                    continue
                s = stats.get(cat)
                if s is None:
                    s = {"category": cat, "volume_usd": 0.0, "buyers_set": set(), "sellers_set": set(), "transactions": 0}
                    stats[cat] = s
                s["volume_usd"] += per_cat_value
                s["transactions"] += tx_count

        for cat in cats_to:
            if not cat:
                continue
            s = stats.get(cat)
            if s is None:
                s = {"category": cat, "volume_usd": 0.0, "buyers_set": set(), "sellers_set": set(), "transactions": 0}
                stats[cat] = s
            if to_id:
                s["buyers_set"].add(to_id)

        for cat in cats_from:
            if not cat:
                continue
            s = stats.get(cat)
            if s is None:
                s = {"category": cat, "volume_usd": 0.0, "buyers_set": set(), "sellers_set": set(), "transactions": 0}
                stats[cat] = s
            if from_id:
                s["sellers_set"].add(from_id)

    rows = []
    for cat, s in stats.items():
        rows.append({
            "category": cat,
            "volume_usd": float(s["volume_usd"]),
            "buyers": len(s["buyers_set"]),
            "sellers": len(s["sellers_set"]),
            "transactions": int(s["transactions"]),
        })

    reverse = (order == "DESC")

    def _key(r):
        v = r.get(orderBy)
        # stable secondary key
        return (v, str(r.get("category", "")))

    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[start_idx:start_idx + limit]
    next_cursor = None
    if start_idx + limit < total:
        next_cursor = _encode_cursor(start_idx + limit)

    resp = {
        "chain": chain_row.get("chain_key"),
        "timeframe": timeframe,
        "from_date": _iso(start),
        "to_date": _iso(now),
        "result": page,
        "cursor": next_cursor,
        "page_size": limit,
        "total": total,
        "has_more": next_cursor is not None,
        "order_by": orderBy,
        "order": order,
    }

    request_logs.append({
        "id": f"req_{int(time.time()*1000)}",
        "endpoint": endpoint,
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000),
        "ts": _iso(now),
        "chain_id": chain_id,
    })
    _save("request_logs.json", request_logs)
    return resp

def gettimeseriesvolume(chain, interval, timeframe=None, fromDate=None, toDate=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_code = "OK"
    used_cred = None

    def _log_and_return(payload):
        nonlocal status_code
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": "gettimeseriesvolume",
                "credential": used_cred,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            })
            _save("request_logs.json", logs)
        except Exception:
            pass
        return payload

    try:
        if not isinstance(chain, str) or not chain.strip():
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "chain must be a non-empty string"))
        if not isinstance(interval, str):
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "interval must be a string"))
        allowed_intervals = {"5m": 300, "15m": 900, "1h": 3600, "4h": 14400, "1d": 86400}
        if interval not in allowed_intervals:
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "Unsupported interval", allowed=list(allowed_intervals.keys())))
        allowed_timeframes = {"1h": 3600, "4h": 14400, "24h": 86400, "7d": 604800, "30d": 2592000, "90d": 7776000, "180d": 15552000, "1y": 31536000}
        if timeframe is not None and timeframe not in allowed_timeframes:
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "Unsupported timeframe", allowed=list(allowed_timeframes.keys())))

        def _parse_dt(s, field):
            if s is None:
                return None
            if not isinstance(s, str):
                raise ValueError(f"{field} must be a date-time string")
            ss = s.strip()
            if not ss:
                raise ValueError(f"{field} must be a non-empty date-time string")
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(ss)
            except ValueError:
                raise ValueError(f"{field} must be ISO-8601 date-time")
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)

        custom_from = None
        custom_to = None
        try:
            custom_from = _parse_dt(fromDate, "fromDate")
            custom_to = _parse_dt(toDate, "toDate")
        except ValueError as ve:
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", str(ve)))

        if (custom_from is None) != (custom_to is None):
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "fromDate and toDate must be provided together for custom range"))

        now = datetime.datetime.now(datetime.timezone.utc)
        if custom_from is not None:
            if custom_to < custom_from:
                status_code = "VALIDATION_ERROR"
                return _log_and_return(_err("VALIDATION_ERROR", "toDate must be >= fromDate"))
            start = custom_from
            end = custom_to
        else:
            if timeframe is None:
                timeframe = "24h"
            end = now
            start = now - datetime.timedelta(seconds=allowed_timeframes[timeframe])

        chains = _load("chains.json")
        if not isinstance(chains, list): chains = []
        chain_row = None
        c_in = chain.strip()
        for r in chains:
            if not isinstance(r, dict): 
                continue
            if r.get("id") == c_in or r.get("chain_key") == c_in:
                chain_row = r
                break
        if not chain_row:
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid chain"))
        chain_id = chain_row.get("id")

        events = _load("events.json")
        if not isinstance(events, list): events = []

        # Aggregate from confirmed swap/liquidity events. Use metadata if present:
        # metadata.volume_usd, metadata.liquidity_usd, metadata.fdv_usd
        step = allowed_intervals[interval]
        start_ts = int(start.timestamp())
        end_ts = int(end.timestamp())
        if end_ts < start_ts:
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid time range"))

        def _bucket_start(ts):
            return (ts // step) * step

        buckets = {}  # bucket_ts -> {"volume_usd":..., "liquidity_usd":..., "fdv_usd":..., "count":...}
        for ev in events:
            if not isinstance(ev, dict):
                continue
            if ev.get("chain_id") != chain_id:
                continue
            if ev.get("status") != "confirmed":
                continue
            et = ev.get("event_type")
            if et not in ("swap", "liquidity_add", "liquidity_remove"):
                continue
            bts = ev.get("block_timestamp")
            if not isinstance(bts, str) or not bts:
                continue
            ss = bts
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(ss)
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc)
            ts = int(dt.timestamp())
            if ts < start_ts or ts > end_ts:
                continue
            bk = _bucket_start(ts)
            b = buckets.get(bk)
            if b is None:
                b = {"volume_usd": 0.0, "liquidity_usd": None, "fdv_usd": None, "events": 0}
                buckets[bk] = b
            md = ev.get("metadata") if isinstance(ev.get("metadata"), dict) else {}
            vol = md.get("volume_usd")
            if isinstance(vol, (int, float)) and vol >= 0:
                b["volume_usd"] += float(vol)
            # liquidity/fdv treated as "latest observation in bucket" when present
            liq = md.get("liquidity_usd")
            if isinstance(liq, (int, float)) and liq >= 0:
                b["liquidity_usd"] = float(liq)
            fdv = md.get("fdv_usd")
            if isinstance(fdv, (int, float)) and fdv >= 0:
                b["fdv_usd"] = float(fdv)
            b["events"] += 1

        points = []
        # Return a continuous series across the requested range (including empty buckets)
        first_bucket = _bucket_start(start_ts)
        last_bucket = _bucket_start(end_ts)
        for bk in range(first_bucket, last_bucket + 1, step):
            b = buckets.get(bk, {"volume_usd": 0.0, "liquidity_usd": None, "fdv_usd": None, "events": 0})
            points.append({
                "timestamp": datetime.datetime.fromtimestamp(bk, tz=datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
                "volume_usd": b["volume_usd"],
                "liquidity_usd": b["liquidity_usd"],
                "fdv_usd": b["fdv_usd"]
            })

        return _log_and_return({
            "chain": chain_row.get("chain_key"),
            "chain_id": chain_id,
            "interval": interval,
            "timeframe": timeframe if custom_from is None else None,
            "fromDate": start.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
            "toDate": end.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
            "result": points
        })
    except Exception as e:
        status_code = "VALIDATION_ERROR" if isinstance(e, ValueError) else "CONFLICT"
        return _log_and_return(_err(status_code, "Unexpected error", detail=str(e)))

