            if chain_id is not None and ev.get("chain_id") != chain_id:
                continue
            et = ev.get("event_type")
            if et not in ("swap", "liquidity_add", "liquidity_remove"):
                continue
            # filter to category: any side touches an attributed address or the contract address is attributed
            if not (
                (ev.get("from_address_id") in address_ids) or
                (ev.get("to_address_id") in address_ids) or
                (ev.get("contract_address_id") in address_ids)
            ):
                continue

            bts = ev.get("block_timestamp")
            if not isinstance(bts, str) or not bts:
                continue
