                    # unknown side -> treat as total volume split evenly (deterministic)
                    b["buy_volume_usd"] += float(vol) / 2.0
                    b["sell_volume_usd"] += float(vol) / 2.0

            if isinstance(liq, (int, float)) and liq >= 0:
                b["liquidity_usd"] = float(liq)
            if isinstance(fdv, (int, float)) and fdv >= 0:
