            points.append({
                "timestamp": datetime.datetime.fromtimestamp(bk, tz=datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
                "buy_volume_usd": b["buy_volume_usd"],
                "sell_volume_usd": b["sell_volume_usd"],
                "liquidity_usd": b["liquidity_usd"],
