            })
            _save("request_logs.json", logs)
        except Exception:
            pass
        return payload

    try:
        if not isinstance(tokens, list) or len(tokens) < 1:
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "tokens must be a non-empty array"))
        if len(tokens) > 200:
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "tokens exceeds maximum of 200"))

        if not isinstance(interval, str):
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "interval must be a string"))
        allowed_intervals = {"5m": 300, "15m": 900, "1h": 3600, "4h": 14400, "1d": 86400}
        if interval not in allowed_intervals:
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "Unsupported interval", allowed=list(allowed_intervals.keys())))
        allowed_timeframes = {"1h": 3600, "4h": 14400, "24h": 86400, "7d": 604800, "30d": 2592000, "90d": 7776000, "180d": 15552000, "1y": 31536000}
        if timeframe is not None and timeframe not in allowed_timeframes:
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "Unsupported timeframe", allowed=list(allowed_timeframes.keys())))

        def _parse_dt(s, field):
            if s is None:
                return None
            if not isinstance(s, str):
                raise ValueError(f"{field} must be a date-time string")
            ss = s.strip()
            if not ss:
                raise ValueError(f"{field} must be a non-empty date-time string")
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)

        try:
            custom_from = _parse_dt(fromDate, "fromDate")
            custom_to = _parse_dt(toDate, "toDate")
        except Exception:
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid fromDate/toDate; must be ISO-8601 date-time"))

        if (custom_from is None) != (custom_to is None):
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "fromDate and toDate must be provided together for custom range"))

        now = datetime.datetime.now(datetime.timezone.utc)
        if custom_from is not None:
            if custom_to < custom_from:
                status_code = "VALIDATION_ERROR"
                return _log_and_return(_err("VALIDATION_ERROR", "toDate must be >= fromDate"))
            start = custom_from
            end = custom_to
        else:
            if timeframe is None:
                timeframe = "24h"
            end = now
            start = now - datetime.timedelta(seconds=allowed_timeframes[timeframe])

        chains = _load("chains.json")
        if not isinstance(chains, list): chains = []
        assets = _load("assets.json")
        if not isinstance(assets, list): assets = []
        addresses = _load("addresses.json")
        if not isinstance(addresses, list): addresses = []
        events = _load("events.json")
        if not isinstance(events, list): events = []

        addr_re = re.compile(r"^0x[a-fA-F0-9]{40}$")

        def _resolve_chain_id(c):
            for r in chains:
                if isinstance(r, dict) and (r.get("id") == c or r.get("chain_key") == c):
                    return r.get("id"), r.get("chain_key")
            return None, None

        def _find_address_id(chain_id, addr):
            a = addr.lower()
            for r in addresses:
                if isinstance(r, dict) and r.get("chain_id") == chain_id and isinstance(r.get("address"), str) and r.get("address").lower() == a:
                    return r.get("id")
            return None

        def _find_erc20_asset_id(chain_id, contract_address_id):
            for r in assets:
                if not isinstance(r, dict):
                    continue
                if r.get("chain_id") == chain_id and r.get("asset_type") == "erc20" and r.get("contract_address_id") == contract_address_id:
                    return r.get("id"), r
            return None, None

        step = allowed_intervals[interval]
        start_ts = int(start.timestamp())
        end_ts = int(end.timestamp())

        def _bucket_start(ts):
            return (ts // step) * step

        # Pre-validate token descriptors and resolve to asset_id (if present)
        resolved = []
        for i, tk in enumerate(tokens):
            if not isinstance(tk, dict):
                status_code = "VALIDATION_ERROR"
                return _log_and_return(_err("VALIDATION_ERROR", f"tokens[{i}] must be an object"))
            c = tk.get("chain")
            a = tk.get("tokenAddress")
            if not isinstance(c, str) or not c.strip():
                status_code = "VALIDATION_ERROR"
                return _log_and_return(_err("VALIDATION_ERROR", f"tokens[{i}].chain must be a non-empty string"))
            if not isinstance(a, str) or not addr_re.match(a):
                status_code = "VALIDATION_ERROR"
                return _log_and_return(_err("VALIDATION_ERROR", f"tokens[{i}].tokenAddress must be a valid 0x address"))
            chain_id, chain_key = _resolve_chain_id(c.strip())
            if not chain_id:
                status_code = "VALIDATION_ERROR"
                return _log_and_return(_err("VALIDATION_ERROR", f"Invalid chain in tokens[{i}]"))
            contract_address_id = _find_address_id(chain_id, a)
            asset_id, asset_row = (None, None)
            if contract_address_id:
                asset_id, asset_row = _find_erc20_asset_id(chain_id, contract_address_id)
            resolved.append({
                "chain": chain_key,
                "chain_id": chain_id,
                "tokenAddress": a.lower(),
                "contract_address_id": contract_address_id,
                "asset_id": asset_id,
                "asset": asset_row
            })

        # Build analytics per token from swap events where metadata includes side and volume_usd and fdv/liquidity
        out = []
        for tk in resolved:
            bucket_map = {}
            for ev in events:
                if not isinstance(ev, dict):
                    continue
                if ev.get("status") != "confirmed":
                    continue
                if ev.get("chain_id") != tk["chain_id"]:
                    continue
                if ev.get("event_type") != "swap":
                    continue
                # match by asset_id if available; else attempt by contract_address_id in event metadata/contract
                if tk["asset_id"] is not None:
                    if ev.get("asset_id") != tk["asset_id"] and ev.get("counter_asset_id") != tk["asset_id"]:
                        continue
                else:
                    # fallback: event.contract_address_id equals token contract is weak; Moralis swaps often have pair contract
                    # so only include if metadata.token_address matches
                    md = ev.get("metadata") if isinstance(ev.get("metadata"), dict) else {}
                    ta = md.get("token_address")
                    if not (isinstance(ta, str) and ta.lower() == tk["tokenAddress"]):
                        continue

                bts = ev.get("block_timestamp")
                if not isinstance(bts, str) or not bts:
                    continue
                ss = bts
                if ss.endswith("Z"):
                    ss = ss[:-1] + "+00:00"
                try:
                    dt = datetime.datetime.fromisoformat(ss)
                except ValueError:
                    continue
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
                ts = int(dt.timestamp())
                if ts < start_ts or ts > end_ts:
                    continue

                md = ev.get("metadata") if isinstance(ev.get("metadata"), dict) else {}
                side = md.get("side")
                vol = md.get("volume_usd")
                liq = md.get("liquidity_usd")
                fdv = md.get("fdv_usd")

                bk = _bucket_start(ts)
                b = bucket_map.get(bk)
                if b is None:
                    b = {"buy_volume_usd": 0.0, "sell_volume_usd": 0.0, "liquidity_usd": None, "fdv_usd": None}
                    bucket_map[bk] = b

                if isinstance(vol, (int, float)) and vol >= 0:
                    if side == "buy":
                        b["buy_volume_usd"] += float(vol)
                    elif side == "sell":
                        b["sell_volume_usd"] += float(vol)
                    else:
                        b["buy_volume_usd"] += float(vol) / 2.0
                        b["sell_volume_usd"] += float(vol) / 2.0

                if isinstance(liq, (int, float)) and liq >= 0:
                    b["liquidity_usd"] = float(liq)
                if isinstance(fdv, (int, float)) and fdv >= 0:
                    b["fdv_usd"] = float(fdv)

            series = []
            first_bucket = _bucket_start(start_ts)
            last_bucket = _bucket_start(end_ts)
            for bk in range(first_bucket, last_bucket + 1, step):
                b = bucket_map.get(bk, {"buy_volume_usd": 0.0, "sell_volume_usd": 0.0, "liquidity_usd": None, "fdv_usd": None})
                series.append({
                    "timestamp": datetime.datetime.fromtimestamp(bk, tz=datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
                    "buy_volume_usd": b["buy_volume_usd"],
                    "sell_volume_usd": b["sell_volume_usd"],
                    "liquidity_usd": b["liquidity_usd"],
                    "fdv_usd": b["fdv_usd"]
                })

            out.append({
                "chain": tk["chain"],
                "chain_id": tk["chain_id"],
                "tokenAddress": tk["tokenAddress"],
                "asset_id": tk["asset_id"],
                "result": series
            })

        return _log_and_return({
            "interval": interval,
            "timeframe": timeframe if custom_from is None else None,
            "fromDate": start.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
            "toDate": end.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
            "result": out
        })
    except Exception as e:
        status_code = "CONFLICT"
        return _log_and_return(_err("CONFLICT", "Unexpected error", detail=str(e)))

