                "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            })
            _save("request_logs.json", logs)
        except Exception:
            pass
        return payload

    try:
        allowed_timeframes = {"1h": 3600, "4h": 14400, "24h": 86400, "7d": 604800}
        if not isinstance(timeframe, str) or timeframe not in allowed_timeframes:
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "Unsupported timeframe", allowed=list(allowed_timeframes.keys())))

        if limit is None:
            limit = 20
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "limit must be an integer between 1 and 100"))

        allowed_order_by = {"trending_score","volume_usd","liquidity_usd","buys","sells","transactions"}
        if orderBy is None:
            orderBy = "trending_score"
        if not isinstance(orderBy, str) or orderBy not in allowed_order_by:
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "Unsupported orderBy", allowed=sorted(list(allowed_order_by))))

        if order is None:
            order = "DESC"
        if not isinstance(order, str) or order not in ("ASC","DESC"):
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "order must be ASC or DESC"))

        if minLiquidityUsd is not None and (not isinstance(minLiquidityUsd, (int, float)) or minLiquidityUsd < 0):
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "minLiquidityUsd must be a non-negative number"))
        if minVolumeUsd is not None and (not isinstance(minVolumeUsd, (int, float)) or minVolumeUsd < 0):
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "minVolumeUsd must be a non-negative number"))
        if spamStatus is not None:
            allowed_spam = {"unknown","not_spam","suspected_spam","spam"}
            if not isinstance(spamStatus, str) or spamStatus not in allowed_spam:
                status_code = "VALIDATION_ERROR"
                return _log_and_return(_err("VALIDATION_ERROR", "Unsupported spamStatus", allowed=sorted(list(allowed_spam))))

        chains = _load("chains.json")
        if not isinstance(chains, list): chains = []
        chain_row = None
        chain_id = None
        if chain is not None:
            if not isinstance(chain, str) or not chain.strip():
                status_code = "VALIDATION_ERROR"
                return _log_and_return(_err("VALIDATION_ERROR", "chain must be a non-empty string when provided"))
            c_in = chain.strip()
            for r in chains:
                if isinstance(r, dict) and (r.get("id") == c_in or r.get("chain_key") == c_in):
                    chain_row = r
                    chain_id = r.get("id")
                    break
            if not chain_row:
                status_code = "VALIDATION_ERROR"
                return _log_and_return(_err("VALIDATION_ERROR", "Invalid chain"))

        assets = _load("assets.json")
        if not isinstance(assets, list): assets = []
        events = _load("events.json")
        if not isinstance(events, list): events = []

        now = datetime.datetime.now(datetime.timezone.utc)
        start = now - datetime.timedelta(seconds=allowed_timeframes[timeframe])
        start_ts = int(start.timestamp())
        end_ts = int(now.timestamp())

        # Build asset map for eligible tokens (erc20, not hidden by default)
        eligible_assets = {}
        for a in assets:
            if not isinstance(a, dict):
                continue
            if a.get("asset_type") != "erc20":
                continue
            if a.get("status") == "hidden":
                continue
            if chain_id is not None and a.get("chain_id") != chain_id:
                continue
            if spamStatus is not None and a.get("spam_status") != spamStatus:
                continue
            if minLiquidityUsd is not None:
                liq = a.get("liquidity_usd")
                if not isinstance(liq, (int, float)) or float(liq) < float(minLiquidityUsd):
                    continue
            eligible_assets[a.get("id")] = a

        # Aggregate trading activity from swap events where asset_id matches the token
        metrics = {}  # asset_id -> dict
        def _parse_ts(bts):
            if not isinstance(bts, str) or not bts:
                return None
            ss = bts
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(ss)
            except ValueError:
                return None
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return int(dt.astimezone(datetime.timezone.utc).timestamp())

        for ev in events:
            if not isinstance(ev, dict):
                continue
            if ev.get("status") != "confirmed":
                continue
            if chain_id is not None and ev.get("chain_id") != chain_id:
                continue
            if ev.get("event_type") != "swap":
                continue
            ts = _parse_ts(ev.get("block_timestamp"))
            if ts is None or ts < start_ts or ts > end_ts:
                continue
            aid = ev.get("asset_id")
            if aid not in eligible_assets:
                continue
            m = metrics.get(aid)
            if m is None:
                m = {"volume_usd": 0.0, "buys": 0, "sells": 0, "transactions": 0}
                metrics[aid] = m
            md = ev.get("metadata") if isinstance(ev.get("metadata"), dict) else {}
            vol = md.get("volume_usd")
            if isinstance(vol, (int, float)) and vol >= 0:
                m["volume_usd"] += float(vol)
            side = md.get("side")
            if side == "buy":
                m["buys"] += 1
            elif side == "sell":
                m["sells"] += 1
            else:
                # unknown side counts as a transaction only
                pass
            m["transactions"] += 1

        # Compose rows; include tokens even if no swaps in window (metrics default 0)
        rows = []
        for aid, a in eligible_assets.items():
            m = metrics.get(aid, {"volume_usd": 0.0, "buys": 0, "sells": 0, "transactions": 0})
            if minVolumeUsd is not None and m["volume_usd"] < float(minVolumeUsd):
                continue
            liq = a.get("liquidity_usd")
            liq_val = float(liq) if isinstance(liq, (int, float)) and liq >= 0 else 0.0
            fdv = a.get("fdv_usd")
            fdv_val = float(fdv) if isinstance(fdv, (int, float)) and fdv >= 0 else 0.0
            # heuristic trending_score
            trending_score = (m["volume_usd"] * 0.6) + (liq_val * 0.2) + (fdv_val * 0.05) + (m["transactions"] * 10.0) + (m["buys"] * 2.0) - (m["sells"] * 1.0)
            rows.append({
                "asset_id": aid,
                "chain_id": a.get("chain_id"),
                "contract_address_id": a.get("contract_address_id"),
                "name": a.get("name"),
                "symbol": a.get("symbol"),
                "logo_url": a.get("logo_url"),
                "spam_status": a.get("spam_status"),
                "latest_price_usd": a.get("latest_price_usd"),
                "liquidity_usd": a.get("liquidity_usd"),
                "fdv_usd": a.get("fdv_usd"),
                "market_cap_usd": a.get("market_cap_usd"),
                "volume_usd": m["volume_usd"],
                "buys": m["buys"],
                "sells": m["sells"],
                "transactions": m["transactions"],
                "trending_score": trending_score
            })

        reverse = (order == "DESC")
        rows.sort(key=lambda r: (r.get(orderBy) is None, r.get(orderBy, 0)), reverse=reverse)

        # Cursor pagination (simple offset cursor)
        offset = 0
        if cursor is not None:
            if not isinstance(cursor, str) or not cursor.startswith("offset:"):
                status_code = "VALIDATION_ERROR"
                return _log_and_return(_err("VALIDATION_ERROR", "Invalid cursor"))
            try:
                offset = int(cursor.split(":", 1)[1])
            except Exception:
                status_code = "VALIDATION_ERROR"
                return _log_and_return(_err("VALIDATION_ERROR", "Invalid cursor"))
            if offset < 0:
                status_code = "VALIDATION_ERROR"
                return _log_and_return(_err("VALIDATION_ERROR", "Invalid cursor"))
        total = len(rows)
        page = rows[offset:offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = f"offset:{next_offset}" if has_more else None

        return _log_and_return({
            "chain": chain_row.get("chain_key") if chain_row else None,
            "timeframe": timeframe,
            "orderBy": orderBy,
            "order": order,
            "cursor": cursor,
            "page_size": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "result": page
        })
    except Exception as e:
        status_code = "CONFLICT"
        return _log_and_return(_err("CONFLICT", "Unexpected error", detail=str(e)))

def getmultipletokenanalytics(tokens, fromDate=None, toDate=None, timeframe=None, cursor=None, limit=None, **_extra):
    import json, os, datetime, time, math, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    ts_now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- request log / rate-limit (best-effort: only if collection exists) ---
    def _log(status, credential=None, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": "getmultipletokenanalytics",
            "credential": credential,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": ts_now,
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    # --- validate inputs ---
    if not isinstance(tokens, list):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "`tokens` must be an array.")
    if len(tokens) == 0:
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "`tokens` must not be empty.")
    if len(tokens) > 200:
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "`tokens` may contain at most 200 entries.")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__err__", _err("VALIDATION_ERROR", f"`{field}` must be an RFC3339 date-time string."))
        try:
            # Accept trailing Z
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return ("__err__", _err("VALIDATION_ERROR", f"`{field}` must be an RFC3339 date-time string."))

    fd = _parse_dt(fromDate, "fromDate")
    if isinstance(fd, tuple) and fd and fd[0] == "__err__":
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return fd[1]
    td = _parse_dt(toDate, "toDate")
    if isinstance(td, tuple) and td and td[0] == "__err__":
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return td[1]

    if fd and td and fd > td:
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "`fromDate` must be <= `toDate`.")

    tf_allowed = {"1h": 3600, "4h": 14400, "1d": 86400, "1w": 604800}
    if timeframe is not None:
        if not isinstance(timeframe, str) or timeframe not in tf_allowed:
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "`timeframe` must be one of: 1h, 4h, 1d, 1w.")

    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "`limit` must be an integer.")
    if limit < 1 or limit > 200:
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "`limit` must be between 1 and 200.")

    if cursor is not None and not isinstance(cursor, str):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "`cursor` must be a string.")

    # --- load core tables ---
    chains = _load("chains.json")
    addresses = _load("addresses.json")
    assets = _load("assets.json")
    events = _load("events.json")

    chain_by_key = {c.get("chain_key"): c for c in chains if isinstance(c, dict)}
    chain_by_id = {c.get("id"): c for c in chains if isinstance(c, dict)}

    # Validate and normalize token requests (must reference known chain_key)
    normalized = []
    for i, tok in enumerate(tokens):
        if not isinstance(tok, dict):
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"`tokens[{i}]` must be an object with `chain` and `tokenAddress`.")
        if set(tok.keys()) != {"chain", "tokenAddress"} and not (set(tok.keys()) <= {"chain", "tokenAddress"}):
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"`tokens[{i}]` contains unsupported fields.")
        ch = tok.get("chain")
        ta = tok.get("tokenAddress")
        if not isinstance(ch, str) or not ch:
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"`tokens[{i}].chain` must be a non-empty string.")
        if not isinstance(ta, str) or not ta:
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"`tokens[{i}].tokenAddress` must be a non-empty string.")
        chain_row = chain_by_key.get(ch)
        if not chain_row:
            _log("error", meta={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", f"Unknown chain key: {ch}", field="chain", value=ch)

        # Minimal EVM-ish normalization (do not over-reject; some chains may use different formats)
        token_addr_norm = ta.strip()
        if chain_row.get("chain_type") == "evm":
            token_addr_norm = token_addr_norm.lower()
        normalized.append({"chain_key": ch, "chain_id": chain_row.get("id"), "token_address": token_addr_norm})

    # pagination cursor as index offset
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("ascii") + b"===")
            start = int(raw.decode("utf-8"))
            if start < 0:
                raise ValueError()
        except Exception:
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid `cursor`.")

    if start >= len(normalized):
        # empty page
        _log("ok")
        return {
            "result": [],
            "cursor": None,
            "has_more": False,
            "total": len(normalized),
        }

    page = normalized[start : start + limit]
    next_start = start + len(page)
    next_cursor = None
    has_more = next_start < len(normalized)
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_start).encode("utf-8")).decode("ascii").rstrip("=")

    # Build indices for address/asset lookup
    # address key unique(chain_id,address)
    addr_by_chain_and_addr = {}
    for a in addresses:
        if not isinstance(a, dict):
            continue
        cid = a.get("chain_id")
        av = a.get("address")
        if isinstance(cid, str) and isinstance(av, str):
            addr_by_chain_and_addr[(cid, av)] = a

    asset_by_chain_and_contract = {}
    for asr in assets:
        if not isinstance(asr, dict):
            continue
        if asr.get("asset_type") != "erc20":
            continue
        if asr.get("status") == "hidden":
            continue
        cid = asr.get("chain_id")
        caid = asr.get("contract_address_id")
        if isinstance(cid, str) and isinstance(caid, str):
            asset_by_chain_and_contract[(cid, caid)] = asr

    # Helpers for bucketing
    def _to_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x
        if isinstance(x, str):
            try:
                ss = x[:-1] if x.endswith("Z") else x
                return datetime.datetime.fromisoformat(ss)
            except Exception:
                return None
        return None

    if fd is None and td is None:
        # Default to last 7 days if timeframe provided; else no time filter
        if timeframe is not None:
            td = datetime.datetime.utcnow()
            fd = td - datetime.timedelta(days=7)

    # Default timeframe if not provided but time window exists
    if timeframe is None and (fd is not None or td is not None):
        timeframe = "1d"

    bucket_seconds = tf_allowed.get(timeframe) if timeframe else None

    def _bucket_key(dt):
        if not bucket_seconds:
            return None
        epoch = int(dt.replace(tzinfo=None).timestamp())
        b = (epoch // bucket_seconds) * bucket_seconds
        return datetime.datetime.utcfromtimestamp(b).replace(microsecond=0).isoformat() + "Z"

    # Filter confirmed swaps only; compute metrics from events.metadata
    # Expected metadata keys (best-effort): side ('buy'/'sell'), volume_usd, liquidity_usd, fdv_usd
    results = []
    for tok in page:
        cid = tok["chain_id"]
        chain_key = tok["chain_key"]
        token_addr = tok["token_address"]

        addr_row = addr_by_chain_and_addr.get((cid, token_addr))
        contract_address_id = addr_row.get("id") if addr_row else None

        asset_row = asset_by_chain_and_contract.get((cid, contract_address_id)) if contract_address_id else None

        # Scan events for swaps where asset_id matches this token (best-effort)
        # If an asset row exists, prefer asset_id match. Otherwise, no analytics (empty).
        token_asset_id = asset_row.get("id") if asset_row else None

        # aggregates
        total_tx = 0
        buy_tx = 0
        sell_tx = 0
        buy_volume_usd = 0.0
        sell_volume_usd = 0.0
        buyers = set()
        sellers = set()

        # latest liquidity/fdv within range (or overall)
        latest_liquidity = None
        latest_fdv = None
        latest_seen_dt = None

        trends = {}  # bucket -> dict aggregates

        if token_asset_id:
            for e in events:
                if not isinstance(e, dict):
                    continue
                if e.get("chain_id") != cid:
                    continue
                if e.get("status") != "confirmed":
                    continue
                if e.get("event_type") != "swap":
                    continue

                # match token involvement via asset_id or counter_asset_id
                if e.get("asset_id") != token_asset_id and e.get("counter_asset_id") != token_asset_id:
                    continue

                bts = _to_dt(e.get("block_timestamp"))
                if bts is None:
                    continue
                if fd and bts < fd:
                    continue
                if td and bts > td:
                    continue

                md = e.get("metadata") if isinstance(e.get("metadata"), dict) else {}
                side = md.get("side")
                vol = md.get("volume_usd")
                liq = md.get("liquidity_usd")
                fdv = md.get("fdv_usd")

                total_tx += 1
                if side == "buy":
                    buy_tx += 1
                    if isinstance(vol, (int, float)) and vol >= 0:
                        buy_volume_usd += float(vol)
                    if isinstance(e.get("to_address_id"), str):
                        buyers.add(e.get("to_address_id"))
                elif side == "sell":
                    sell_tx += 1
                    if isinstance(vol, (int, float)) and vol >= 0:
                        sell_volume_usd += float(vol)
                    if isinstance(e.get("from_address_id"), str):
                        sellers.add(e.get("from_address_id"))
                else:
                    # Unknown side: count as tx, ignore buy/sell specifics
                    pass

                if latest_seen_dt is None or bts > latest_seen_dt:
                    latest_seen_dt = bts
                    if isinstance(liq, (int, float)) and liq >= 0:
                        latest_liquidity = float(liq)
                    if isinstance(fdv, (int, float)) and fdv >= 0:
                        latest_fdv = float(fdv)

                bk = _bucket_key(bts)
                if bk is not None:
                    slot = trends.get(bk)
                    if slot is None:
                        slot = {
                            "timestamp": bk,
                            "buy_volume_usd": 0.0,
                            "sell_volume_usd": 0.0,
                            "buy_tx_count": 0,
                            "sell_tx_count": 0,
                            "tx_count": 0,
                            "buyers": set(),
                            "sellers": set(),
                            "liquidity_usd": None,
                            "fdv_usd": None,
                        }
                        trends[bk] = slot
                    slot["tx_count"] += 1
                    if side == "buy":
                        slot["buy_tx_count"] += 1
                        if isinstance(vol, (int, float)) and vol >= 0:
                            slot["buy_volume_usd"] += float(vol)
                        if isinstance(e.get("to_address_id"), str):
                            slot["buyers"].add(e.get("to_address_id"))
                    elif side == "sell":
                        slot["sell_tx_count"] += 1
                        if isinstance(vol, (int, float)) and vol >= 0:
                            slot["sell_volume_usd"] += float(vol)
                        if isinstance(e.get("from_address_id"), str):
                            slot["sellers"].add(e.get("from_address_id"))
                    # set latest snapshot values inside bucket if present
                    if isinstance(liq, (int, float)) and liq >= 0:
                        slot["liquidity_usd"] = float(liq)
                    if isinstance(fdv, (int, float)) and fdv >= 0:
                        slot["fdv_usd"] = float(fdv)

        # Serialize trends sorted
        trend_list = []
        if trends:
            for k in sorted(trends.keys()):
                slot = trends[k]
                trend_list.append(
                    {
                        "timestamp": slot["timestamp"],
                        "buy_volume_usd": slot["buy_volume_usd"],
                        "sell_volume_usd": slot["sell_volume_usd"],
                        "buy_tx_count": slot["buy_tx_count"],
                        "sell_tx_count": slot["sell_tx_count"],
                        "tx_count": slot["tx_count"],
                        "buyers": len(slot["buyers"]),
                        "sellers": len(slot["sellers"]),
                        "liquidity_usd": slot["liquidity_usd"],
                        "fdv_usd": slot["fdv_usd"],
                    }
                )

        results.append(
            {
                "chain": chain_key,
                "tokenAddress": token_addr,
                "token": (None if not asset_row else {"id": asset_row.get("id"), "name": asset_row.get("name"), "symbol": asset_row.get("symbol"), "decimals": asset_row.get("decimals")}),
                "summary": {
                    "tx_count": total_tx,
                    "buy_tx_count": buy_tx,
                    "sell_tx_count": sell_tx,
                    "buy_volume_usd": buy_volume_usd,
                    "sell_volume_usd": sell_volume_usd,
                    "buyers": len(buyers),
                    "sellers": len(sellers),
                    "liquidity_usd": latest_liquidity if latest_liquidity is not None else (asset_row.get("liquidity_usd") if asset_row else None),
                    "fdv_usd": (asset_row.get("fdv_usd") if asset_row else None),
                },
                "timeframe": timeframe,
                "fromDate": (fd.replace(microsecond=0).isoformat() + "Z") if isinstance(fd, datetime.datetime) else None,
                "toDate": (td.replace(microsecond=0).isoformat() + "Z") if isinstance(td, datetime.datetime) else None,
                "trends": trend_list,
            }
        )

    _log("ok", meta={"returned": len(results), "has_more": has_more})
    return {"result": results, "cursor": next_cursor, "has_more": has_more, "total": len(normalized)}

def getchains(status=None, chainType=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        # Create a request log collection even if not declared, to satisfy observable dynamics.
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])

    def _log(endpoint, status_code, latency_ms, meta=None):
        _ensure_request_log()
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_now()}|{len(logs)}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status_code,
            "latency_ms": int(latency_ms),
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_rate_limit(endpoint):
        # Best-effort rate limiting using request log:
        # default: 120 requests / rolling minute per endpoint.
        _ensure_request_log()
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        window_s = 60
        limit_per_window = 120
        cnt = 0
        for r in reversed(logs):
            if r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                t = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if (now - t).total_seconds() > window_s:
                break
            cnt += 1
            if cnt >= limit_per_window:
                return False
        return True

    t0 = time.time()
    endpoint = "getchains"

    # Rate limit check (pre-log refusal, but still log the refused request)
    if not _check_rate_limit(endpoint):
        latency = (time.time() - t0) * 1000
        _log(endpoint, "RATE_LIMIT", latency, meta={"status": status, "chainType": chainType, "limit": limit})
        return _err("RATE_LIMIT", "Too many requests. Please try again later.")

    # Validate inputs
    allowed_status = {"active", "degraded", "disabled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            latency = (time.time() - t0) * 1000
            _log(endpoint, "VALIDATION_ERROR", latency, meta={"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status filter.", field="status", allowed=sorted(allowed_status))

    # Tool allows more chainType enums than schema; map unknown ones to validation error (unsupported).
    allowed_chain_type_tool = {"evm", "solana", "aptos", "sui", "btc", "other"}
    if chainType is not None:
        if not isinstance(chainType, str) or chainType not in allowed_chain_type_tool:
            latency = (time.time() - t0) * 1000
            _log(endpoint, "VALIDATION_ERROR", latency, meta={"field": "chainType"})
            return _err("VALIDATION_ERROR", "Invalid chainType filter.", field="chainType", allowed=sorted(allowed_chain_type_tool))
        # datastore only supports evm/solana/other per schema
        if chainType not in {"evm", "solana", "other"}:
            latency = (time.time() - t0) * 1000
            _log(endpoint, "VALIDATION_ERROR", latency, meta={"field": "chainType"})
            return _err("VALIDATION_ERROR", "Unsupported chainType in this server schema.", field="chainType", supported=["evm", "solana", "other"])

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        latency = (time.time() - t0) * 1000
        _log(endpoint, "VALIDATION_ERROR", latency, meta={"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
    if limit < 1 or limit > 100:
        latency = (time.time() - t0) * 1000
        _log(endpoint, "VALIDATION_ERROR", latency, meta={"field": "limit"})
        return _err("VALIDATION_ERROR", "limit out of range (1..100).", field="limit", minimum=1, maximum=100)

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            latency = (time.time() - t0) * 1000
            _log(endpoint, "VALIDATION_ERROR", latency, meta={"field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.", field="cursor")
        # Cursor format: base64url(json={"start":int})
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            start = obj.get("start", 0)
        except Exception:
            latency = (time.time() - t0) * 1000
            _log(endpoint, "VALIDATION_ERROR", latency, meta={"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        if not isinstance(start, int) or start < 0:
            latency = (time.time() - t0) * 1000
            _log(endpoint, "VALIDATION_ERROR", latency, meta={"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor value.", field="cursor")

    chains = _load("chains.json")

    # Filter
    out = []
    for c in chains:
        if not isinstance(c, dict):
            continue
        if status is not None and c.get("status") != status:
            continue
        if chainType is not None and c.get("chain_type") != chainType:
            continue
        out.append(c)

    # Sort stable: by display_name then chain_key
    def _key(c):
        return (str(c.get("display_name") or "").lower(), str(c.get("chain_key") or "").lower(), str(c.get("id") or ""))
    out.sort(key=_key)

    total = len(out)
    page = out[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        payload = json.dumps({"start": start + limit}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    latency = (time.time() - t0) * 1000
    _log(endpoint, "OK", latency, meta={"returned": len(page), "total": total})

    return {
        "result": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
    }

