def updatechain(chain, status=None, displayName=None, nativeSymbol=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    ts_now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": "updatechain",
            "credential": None,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": ts_now,
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(chain, str) or not chain:
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "`chain` must be a non-empty string.")

    if status is not None:
        if not isinstance(status, str) or status not in {"active", "degraded", "disabled"}:
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "`status` must be one of: active, degraded, disabled.")
    if displayName is not None and (not isinstance(displayName, str) or displayName.strip() == ""):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "`displayName` must be a non-empty string when provided.")
    if nativeSymbol is not None and (not isinstance(nativeSymbol, str) or nativeSymbol.strip() == ""):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "`nativeSymbol` must be a non-empty string when provided.")

    if status is None and displayName is None and nativeSymbol is None:
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "No mutable fields provided. Supply at least one of: status, displayName, nativeSymbol.")

    chains = _load("chains.json")
    if not isinstance(chains, list):
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Chains store not found.")

    idx = None
    row = None
    for i, c in enumerate(chains):
        if isinstance(c, dict) and c.get("chain_key") == chain:
            idx = i
            row = c
            break
    if row is None:
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", f"Unknown chain key: {chain}", field="chain", value=chain)

    # lifecycle transitions
    transitions = {
        "active": {"degraded", "disabled"},
        "degraded": {"active", "disabled"},
        "disabled": {"active"},
    }
    if status is not None:
        cur = row.get("status")
        if cur not in transitions:
            _log("error", meta={"code": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", f"Current chain status is invalid: {cur}", current=cur, requested=status)
        if status != cur and status not in transitions[cur]:
            _log("error", meta={"code": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", f"Illegal transition: {cur} -> {status}", current=cur, requested=status)

    # constraints
    if displayName is not None and displayName.strip() == "":
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "`displayName` must not be empty.")
    if nativeSymbol is not None and nativeSymbol.strip() == "":
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "`nativeSymbol` must not be empty.")

    # apply updates (idempotent allowed)
    changed = False
    new_row = dict(row)

    if status is not None and status != new_row.get("status"):
        new_row["status"] = status
        changed = True
    if displayName is not None and displayName != new_row.get("display_name"):
        new_row["display_name"] = displayName
        changed = True
    if nativeSymbol is not None and nativeSymbol != new_row.get("native_symbol"):
        new_row["native_symbol"] = nativeSymbol
        changed = True

    if not changed:
        # Realistic: no-op should still return updated resource, but "NO SUCCESS WITHOUT EFFECT" applies to mutations.
        _log("error", meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Update would make no changes.")

    new_row["updated_at"] = ts_now

    # persist
    chains[idx] = new_row
    try:
        _save("chains.json", chains)
    except Exception:
        _log("error", meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Failed to persist chain update.")

    _log("ok")
    return {"result": new_row}

def getentities(query=None, category=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_str(x):
        return isinstance(x, str)

    def _record_log(endpoint, credential_id, status_code, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Ambient auth: find any usable credential context if present; do not fail if store has no auth collections.
    def _resolve_ambient_credential_id():
        for fname in ("api_keys.json", "apikeys.json", "credentials.json", "keys.json"):
            rows = _load(fname)
            if isinstance(rows, list) and rows:
                # pick any row that looks active/valid if such a field exists
                for r in rows:
                    if isinstance(r, dict):
                        st = r.get("status")
                        if st is None or st in ("active", "enabled", "valid"):
                            return r.get("id") or r.get("key_id") or r.get("api_key_id")
                r = rows[0]
                if isinstance(r, dict):
                    return r.get("id") or r.get("key_id") or r.get("api_key_id")
        return None

    # Basic validation
    if query is not None and not _is_str(query):
        _record_log("getentities", _resolve_ambient_credential_id(), 400, "VALIDATION_ERROR", "query must be a string")
        return _err("VALIDATION_ERROR", "query must be a string")
    if category is not None and not _is_str(category):
        _record_log("getentities", _resolve_ambient_credential_id(), 400, "VALIDATION_ERROR", "category must be a string")
        return _err("VALIDATION_ERROR", "category must be a string")
    if status is not None:
        if not _is_str(status) or status not in ("active", "inactive"):
            _record_log("getentities", _resolve_ambient_credential_id(), 400, "VALIDATION_ERROR", "status must be one of: active, inactive")
            return _err("VALIDATION_ERROR", "status must be one of: active, inactive")
    if limit is None:
        limit = 25
    if not isinstance(limit, int):
        _record_log("getentities", _resolve_ambient_credential_id(), 400, "VALIDATION_ERROR", "limit must be an integer")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 100:
        _record_log("getentities", _resolve_ambient_credential_id(), 400, "VALIDATION_ERROR", "limit must be between 1 and 100")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
    if cursor is not None and not _is_str(cursor):
        _record_log("getentities", _resolve_ambient_credential_id(), 400, "VALIDATION_ERROR", "cursor must be a string")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # Decode cursor (offset pagination)
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1 or "offset" not in obj:
                _record_log("getentities", _resolve_ambient_credential_id(), 400, "VALIDATION_ERROR", "Invalid cursor")
                return _err("VALIDATION_ERROR", "Invalid cursor")
            offset = obj["offset"]
            if not isinstance(offset, int) or offset < 0:
                _record_log("getentities", _resolve_ambient_credential_id(), 400, "VALIDATION_ERROR", "Invalid cursor offset")
                return _err("VALIDATION_ERROR", "Invalid cursor")
        except (ValueError, json.JSONDecodeError):
            _record_log("getentities", _resolve_ambient_credential_id(), 400, "VALIDATION_ERROR", "Invalid cursor encoding")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    entities = _load("entities.json")
    if not isinstance(entities, list):
        entities = []

    q = (query or "").strip().lower()
    cat = (category or "").strip()

    def _match(e):
        if not isinstance(e, dict):
            return False
        if status is not None and e.get("status") != status:
            return False
        if category is not None and e.get("category") != cat:
            return False
        if q:
            n = (e.get("name") or "").lower()
            d = (e.get("description") or "").lower()
            return q in n or q in d
        return True

    filtered = [e for e in entities if _match(e)]
    # deterministic order (name asc, then id)
    filtered.sort(key=lambda r: ((r.get("name") or "").lower(), (r.get("id") or "")))

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"v": 1, "offset": next_offset}, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    cred_id = _resolve_ambient_credential_id()
    _record_log("getentities", cred_id, 200)

    return {
        "result": page,
        "total": total,
        "page_size": limit,
        "cursor": next_cursor,
        "has_more": has_more,
    }

