    if idx is None:
        latency = (time.time() - t0) * 1000
        _log(endpoint, "NOT_FOUND", latency, meta={"id": id})
        return _err("NOT_FOUND", "Entity not found.", id=id)

    entity = entities[idx]
    before_status = entity.get("status")

    # Enforce lifecycle transitions if status is changing
    transitions = {
        "active": {"inactive"},
        "inactive": {"active"},
    }
    if status is not None and status != before_status:
        if before_status not in transitions or status not in transitions.get(before_status, set()):
            latency = (time.time() - t0) * 1000
            _log(endpoint, "INVALID_TRANSITION", latency, meta={"id": id, "from": before_status, "to": status})
            return _err(
                "INVALID_TRANSITION",
                "Invalid status transition.",
                from_status=before_status,
                to_status=status,
                allowed=list(sorted(transitions.get(before_status, set()))) if before_status in transitions else []
            )

    # Apply updates (mutable fields)
    changed = False
    if name is not None and name != entity.get("name"):
        entity["name"] = name
        changed = True
    if description is not None and description != entity.get("description"):
        entity["description"] = description
        changed = True
    if logoUrl is not None and logoUrl != entity.get("logo_url"):
        entity["logo_url"] = logoUrl
        changed = True
    if externalLinks is not None and externalLinks != entity.get("external_links"):
        entity["external_links"] = externalLinks
        changed = True
    if category is not None and category != entity.get("category"):
        entity["category"] = category
        changed = True
    if status is not None and status != entity.get("status"):
        entity["status"] = status
        changed = True

    # Enforce uniqueness constraint unique(name, category) if either changed/provided
    # Use resulting values.
    new_name = entity.get("name")
    new_cat = entity.get("category")
    if not isinstance(new_name, str) or new_name.strip() == "":
        latency = (time.time() - t0) * 1000
        _log(endpoint, "VALIDATION_ERROR", latency, meta={"id": id, "field": "name"})
        return _err("VALIDATION_ERROR", "Entity name cannot be empty.", field="name")
    if new_cat not in allowed_category:
        latency = (time.time() - t0) * 1000
        _log(endpoint, "VALIDATION_ERROR", latency, meta={"id": id, "field": "category"})
        return _err("VALIDATION_ERROR", "Invalid entity category.", field="category", allowed=sorted(allowed_category))

    for e in entities:
        if not isinstance(e, dict) or e.get("id") == id:
            continue
        if e.get("name") == new_name and e.get("category") == new_cat:
            latency = (time.time() - t0) * 1000
            _log(endpoint, "CONFLICT", latency, meta={"id": id, "conflict_id": e.get("id")})
            return _err("CONFLICT", "An entity with the same name and category already exists.", name=new_name, category=new_cat)

    if not changed:
        # Idempotent success: return existing row (still an update call but no-op is acceptable)
        latency = (time.time() - t0) * 1000
        _log(endpoint, "OK", latency, meta={"id": id, "changed": False})
        return {"result": entity}

    # Update timestamp and persist
    entity["updated_at"] = _now()
    entities[idx] = entity
    _save("entities.json", entities)

    latency = (time.time() - t0) * 1000
    _log(endpoint, "OK", latency, meta={"id": id, "changed": True})
    return {"result": entity}

def getuserinfo(apiKey, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0525000" if __import__("os").path.isdir("./environment_mix/0525000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_log(endpoint, credential_id, status_code, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(apiKey, str) or not apiKey.strip():
        _record_log("getuserinfo", None, 400, "VALIDATION_ERROR", "apiKey must be a non-empty string")
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string")

    # Authenticate explicit credential by matching stored client-visible value or id (never hashes).
    cred = None
    cred_source = None
    for fname in ("api_keys.json", "apikeys.json", "credentials.json", "keys.json"):
        rows = _load(fname)
        if not isinstance(rows, list) or not rows:
            continue
        for r in rows:
            if not isinstance(r, dict):
                continue
            # Try common fields for client-visible API key value
            candidates = [
                r.get("apiKey"), r.get("api_key"), r.get("key"), r.get("value"), r.get("token")
            ]
            if apiKey == r.get("id") or apiKey in [c for c in candidates if isinstance(c, str)]:
                st = r.get("status")
                if st is None or st in ("active", "enabled", "valid"):
                    cred = r
                    cred_source = fname
                    break
        if cred is not None:
            break

    if cred is None:
        _record_log("getuserinfo", None, 401, "UNAUTHORIZED", "Invalid API key")
        return _err("UNAUTHORIZED", "Invalid API key")

    cred_id = cred.get("id") or cred.get("key_id") or cred.get("api_key_id") or apiKey

    # Rate/quota: derive from request logs if present; otherwise report zeros.
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    now = datetime.datetime.utcnow()
    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    # default entitlement values; may be overridden by stored fields
    rate_limit_per_min = cred.get("rate_limit_per_min") or cred.get("rateLimitPerMin") or cred.get("rpm") or 60
    quota_per_day = cred.get("quota_per_day") or cred.get("quotaPerDay") or cred.get("qpd") or 100000

    try:
        rate_limit_per_min = int(rate_limit_per_min)
    except (ValueError, TypeError):
        rate_limit_per_min = 60
    try:
        quota_per_day = int(quota_per_day)
    except (ValueError, TypeError):
        quota_per_day = 100000

    window_1m_start = now - datetime.timedelta(minutes=1)
    window_1d_start = now - datetime.timedelta(days=1)

    used_1m = 0
    used_1d = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("credential_id") != cred_id:
            continue
        ts = _parse_ts(r.get("timestamp"))
        if ts is None:
            continue
        if ts >= window_1m_start:
            used_1m += 1
        if ts >= window_1d_start:
            used_1d += 1

    # Record this call, then update the numbers to include it (more realistic backend behavior)
    _record_log("getuserinfo", cred_id, 200)
    used_1m += 1
    used_1d += 1

    # Scopes: best-effort from stored fields
    scopes = cred.get("scopes") or cred.get("permissions") or cred.get("grants") or []
    if isinstance(scopes, str):
        scopes = [s for s in (x.strip() for x in scopes.split(",")) if s]
    if not isinstance(scopes, list) or any(not isinstance(s, str) for s in scopes):
        scopes = []

    identity = {
        "credential_id": cred_id,
        "source": cred_source,
        "status": cred.get("status", "active"),
        "workspace_id": cred.get("workspace_id") or cred.get("workspaceId"),
        "account_id": cred.get("account_id") or cred.get("accountId"),
        "scopes": scopes,
        "limits": {
            "rate_limit_per_min": rate_limit_per_min,
            "quota_per_day": quota_per_day,
        },
        "usage": {
            "requests_last_min": used_1m,
            "requests_last_day": used_1d,
            "rate_limit_remaining": max(0, rate_limit_per_min - used_1m),
            "quota_remaining": max(0, quota_per_day - used_1d),
        },
        "timestamp": _now_iso(),
    }

    return {"result": identity}
